import clsx from "clsx";
import type { FC, ReactNode } from "react";
import { Suspense } from "react";

import { normalizeUrl } from "../../utils/url";
import { getTableData } from "./tableResource";
import TableInner from "./TableInner";

import "./Table.css";

export type tableTextAlign = "left" | "center" | "right";
export type tableTextWrap = boolean;

interface TableProps {
  children?: ReactNode;
  textAlign?: tableTextAlign;
  textWrap?: tableTextWrap;
  file?: string;
  domain?: string;
}

const Table: FC<TableProps> = ({
  children,
  textAlign = "left",
  textWrap = false,
  file,
  domain,
}) => {
  if (file && children) {
    return <div className="glass-table error-message">⚠️ Provide either file or children.</div>;
  }

  const wrapperClassName = clsx("glass-table", `text-align-${textAlign}`, textWrap && "nowrap");

  // No fetch needed — render the static markup straight away.
  if (!file) {
    return (
      <div className={wrapperClassName}>
        <table>{children}</table>
      </div>
    );
  }

  const dataPromise = getTableData(normalizeUrl(file, domain));

  return (
    <Suspense fallback={<div className={wrapperClassName}>{/* loading */}</div>}>
      <TableInner className={wrapperClassName} textAlign={textAlign} dataPromise={dataPromise} />
    </Suspense>
  );
};

export default Table;
