"use client";
import clsx from "clsx";
import type { ComponentProps, ReactNode } from "react";
import { VerticalTimeline, VerticalTimelineElement } from "react-vertical-timeline-component";
import "./VerticalTimeline.css";
import "./VerticalTimelineElement.css";
// Override
import "./Timeline.scss";

export interface TimelineProps extends Omit<ComponentProps<typeof VerticalTimeline>, "children"> {
  children: ReactNode;
  className?: string;
}

export interface TimelineItemProps {
  children: ReactNode;
  emoji?: string;
  className?: string;
}

export function TimelineItem({ children, emoji = "✨", className }: TimelineItemProps) {
  return (
    <VerticalTimelineElement
      className={clsx("wf-timeline-item", className)}
      icon={<span className="wf-timeline__emoji">{emoji}</span>}
    >
      {children}
    </VerticalTimelineElement>
  );
}

export function Timeline({ children, className, ...props }: TimelineProps) {
  return (
    <VerticalTimeline className={clsx("wf-timeline", className)} {...props}>
      {children}
    </VerticalTimeline>
  );
}
