"use client";

import type { CSSProperties } from "react";
import { useCallback, useState } from "react";
import { TreeLevelProvider, useTreeLevelContext, useTreeRootContext } from "./Context";
import styles from "./FileTree.module.css";
import { ChevronIcon, FolderClosedIcon, FolderOpenIcon } from "./Icons";
import type { FileTreeFolderProps } from "./types";

export function FolderItem({ name, defaultOpen = false, children }: FileTreeFolderProps) {
  const { level, parentPath } = useTreeLevelContext();
  const { focusedId, setFocusedId } = useTreeRootContext();

  const [open, setOpen] = useState(defaultOpen);

  const id = `${parentPath}/${name}`;
  const hasChildren = children != null;

  const toggle = useCallback(() => {
    setOpen((wasOpen) => !wasOpen);
  }, []);

  const handleClick = useCallback(() => {
    if (hasChildren) toggle();
  }, [hasChildren, toggle]);

  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      // Ignore keydowns that bubbled up from a focused descendant treeitem;
      // only react when this node itself is the one that was focused.
      if (event.target !== event.currentTarget) return;
      if ((event.key === "Enter" || event.key === " ") && hasChildren) {
        event.preventDefault();
        toggle();
      }
    },
    [hasChildren, toggle],
  );

  const handleFocus = useCallback(
    (event: React.FocusEvent<HTMLDivElement>) => {
      // Native focus events bubble (as "focusin"), so without this guard a
      // descendant treeitem receiving focus would also re-fire this handler
      // for every ancestor folder as the event bubbles past them.
      if (event.target !== event.currentTarget) return;
      setFocusedId(id);
    },
    [id, setFocusedId],
  );

  // Children are ALWAYS rendered into the DOM now (no lazy "hasOpened"
  // mount gate) so server-rendered HTML, view-source, and crawlers always
  // see the complete tree regardless of open/closed state. While closed,
  // the branch is marked `inert`: it stays in the DOM but is pulled out of
  // the accessibility tree, tab order, and programmatic focus() — the same
  // practical effect the old "don't mount it" approach had, without
  // actually omitting it from SSR output. Visual collapse is still handled
  // by the `.branch[data-open]` grid-rows transition in CSS.
  const inertProps = open ? {} : ({ inert: true } as { inert?: boolean });

  return (
    <div
      className={styles.node}
      role="treeitem"
      aria-selected={focusedId === id}
      aria-expanded={hasChildren ? open : undefined}
      aria-level={level}
      data-tree-id={id}
      data-tree-type="folder"
      tabIndex={focusedId === id ? 0 : -1}
      onKeyDown={handleKeyDown}
      onFocus={handleFocus}
    >
      <div
        className={styles.row}
        style={{ "--tree-level": level } as CSSProperties}
        onClick={handleClick}
      >
        <span className={styles.chevron} data-open={open} aria-hidden="true">
          {hasChildren && <ChevronIcon />}
        </span>
        <span className={styles.icon} aria-hidden="true">
          {open ? <FolderOpenIcon /> : <FolderClosedIcon />}
        </span>
        <span className={styles.label}>{name}</span>
      </div>

      {hasChildren && (
        <div className={styles.branch} data-open={open} {...inertProps}>
          <div className={styles.branchInner}>
            <div role="group">
              <TreeLevelProvider value={{ level: level + 1, parentPath: id }}>
                {children}
              </TreeLevelProvider>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
