"use client";

import type { CSSProperties, FocusEvent, KeyboardEvent } from "react";
import { useCallback } from "react";
import { useTreeLevelContext, useTreeRootContext } from "./Context";
import styles from "./FileTree.module.css";
import { ArrowRightIcon, FileIcon } from "./Icons";
import type { FileTreeFileProps } from "./types";
import { getFileIconKind } from "./utils";

export function FileItem({ name, code }: FileTreeFileProps) {
  const { level, parentPath } = useTreeLevelContext();
  const { focusedId, setFocusedId, selectedId, setSelectedId } = useTreeRootContext();

  const id = `${parentPath}/${name}`;
  const kind = getFileIconKind(name);

  // A FileItem is a "code file" purely because it received a `code` prop —
  // there's no separate registry of which files support code. This keeps
  // the FileItem itself the single source of truth, and means selection
  // works at any nesting depth with zero upfront tree traversal.
  const hasCode = code !== undefined;
  const isSelected = hasCode && selectedId === id;

  // The editor pane already holds a pre-rendered, always-mounted slot for
  // every code file in the tree (see FileTreeClient) — this file's job is
  // just to say which slot's id is currently open, not to build or carry
  // any rendered content itself. Clicking the file that's already open
  // closes it again, so the row itself doubles as a toggle.
  const openInEditor = useCallback(() => {
    if (!hasCode) return;
    setSelectedId(isSelected ? null : id);
  }, [hasCode, id, isSelected, setSelectedId]);

  const handleClick = useCallback(() => {
    openInEditor();
  }, [openInEditor]);

  const handleKeyDown = useCallback(
    (event: KeyboardEvent<HTMLDivElement>) => {
      // Ignore keydowns that bubbled up from a focused descendant; only
      // react when this node itself is the one that was focused (mirrors
      // the identical guard in FolderItem's handleKeyDown).
      if (event.target !== event.currentTarget) return;
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        openInEditor();
      }
    },
    [openInEditor],
  );

  const handleFocus = useCallback(
    (event: FocusEvent<HTMLDivElement>) => {
      // Native focus events bubble (as "focusin"); this guard keeps a file
      // deep in the tree from also re-firing focus handling on itself twice
      // and keeps the shape consistent with Folder's same guard.
      if (event.target !== event.currentTarget) return;
      setFocusedId(id);
    },
    [id, setFocusedId],
  );

  const rowClassName = [
    styles.row,
    styles.rowFile,
    hasCode ? styles.rowFileCode : "",
    isSelected ? styles.rowFileActive : "",
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <div
      className={styles.node}
      role="treeitem"
      aria-level={level}
      aria-selected={hasCode ? isSelected : undefined}
      data-tree-id={id}
      data-tree-type="file"
      tabIndex={focusedId === id ? 0 : -1}
      onFocus={handleFocus}
      onKeyDown={hasCode ? handleKeyDown : undefined}
    >
      <div
        className={rowClassName}
        style={{ "--tree-level": level } as CSSProperties}
        onClick={hasCode ? handleClick : undefined}
      >
        <span className={styles.chevronSpacer} aria-hidden="true" />
        <span className={styles.icon} aria-hidden="true">
          <FileIcon kind={kind} />
        </span>
        <span className={styles.label}>{name}</span>
        {hasCode && (
          <span className={styles.fileArrow} aria-hidden="true">
            <ArrowRightIcon />
          </span>
        )}
      </div>
    </div>
  );
}
