"use client";

import "./Switch.css";

interface SwitchProps {
  checked: boolean;
  onChange: () => void;
  "aria-label"?: string;
  "aria-labelledby"?: string;
}

const Switch = ({
  checked,
  onChange,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
}: SwitchProps) => {
  return (
    <label className="switch">
      <input
        type="checkbox"
        checked={checked}
        onChange={onChange}
        aria-label={ariaLabel}
        aria-labelledby={ariaLabelledBy}
      />
      <span className="slider round" aria-hidden="true" />
    </label>
  );
};

export default Switch;
