"use client";

import React, { useEffect, useLayoutEffect, useMemo, useRef, useState } from "react";
import "./Flow.css";
import { computeLayout } from "./Flow.layout";
import { flattenTree } from "./Flow.tree";
import type { FlowClientProps, MeasuredSize } from "./Flow.types";

const LEVEL_GAP = 64;
const SIBLING_GAP = 28;

// useLayoutEffect triggers a React warning when it runs during SSR. We only
// ever need it for its "runs before paint" guarantee on the client, so on
// the server it safely falls back to a no-op-until-mount useEffect.
const useIsomorphicLayoutEffect = typeof window !== "undefined" ? useLayoutEffect : useEffect;

function cx(...parts: Array<string | false | null | undefined>): string {
  return parts.filter(Boolean).join(" ");
}

/**
 * FlowClient owns everything that depends on the DOM or on user
 * interaction: measurement, ResizeObserver, layout computation, the
 * toolbar, fullscreen mode, and rendering the SVG connectors + cards.
 *
 * It receives an already-parsed, plain data tree (`tree`) from the server
 * — never raw <Flow.Item> JSX — so it has no dependency on component
 * identity and works identically whether it was mounted from a Server
 * Component page, a Client Component page, SSR, or SSG.
 */
export function FlowClient({ tree, layout, className }: FlowClientProps) {
  const flatNodes = useMemo(() => flattenTree(tree), [tree]);
  const flatNodeIds = useMemo(() => new Set(flatNodes.map((n) => n.id)), [flatNodes]);

  // Refs onto the actual, visible cards (not a separate offscreen copy).
  // Measuring the real element is what guarantees the layout can never
  // under-reserve space relative to what's actually painted: a card's
  // width is fixed by CSS and its height is purely content-driven (via
  // max-height + overflow), so there is nothing position/transform can
  // do to make the real card disagree with its own measurement.
  const cardRefs = useRef(new Map<string, HTMLDivElement | null>());
  const [sizes, setSizes] = useState<Map<string, MeasuredSize>>(new Map());
  const [isMeasured, setIsMeasured] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [activeLayout, setActiveLayout] = useState(layout);

  const frameRef = useRef<number | null>(null);

  // Follow the `layout` prop when the caller changes it, while still
  // letting the person override it locally with the direction toggle.
  useEffect(() => {
    setActiveLayout(layout);
  }, [layout]);

  // While full page view is open: let Escape close it, and lock the
  // underlying page's scroll so only the diagram scrolls.
  useEffect(() => {
    if (!isFullscreen) return;

    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setIsFullscreen(false);
      }
    };

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    document.addEventListener("keydown", onKeyDown);

    return () => {
      document.body.style.overflow = previousOverflow;
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [isFullscreen]);

  // Re-measure whenever the hierarchy shape changes. This runs before the
  // browser paints, so the corrected, content-based layout is what the
  // user actually sees (avoiding a visible jump from the SSR fallback size).
  const measureNodes = React.useCallback(() => {
    const next = new Map<string, MeasuredSize>();

    // Drop refs for ids that no longer exist in the current tree (e.g.
    // after items are removed), so they can't be mistaken for a live
    // measurement and can't leak indefinitely.
    cardRefs.current.forEach((_el, id) => {
      if (!flatNodeIds.has(id)) cardRefs.current.delete(id);
    });

    flatNodes.forEach((node) => {
      const el = cardRefs.current.get(node.id);

      if (!el) return;

      next.set(node.id, {
        width: Math.ceil(el.offsetWidth),
        height: Math.ceil(el.offsetHeight),
      });
    });

    setSizes((previous) => {
      let changed = previous.size !== next.size;

      if (!changed) {
        for (const [id, size] of next) {
          const old = previous.get(id);

          if (!old || old.width !== size.width || old.height !== size.height) {
            changed = true;
            break;
          }
        }
      }

      return changed ? next : previous;
    });

    setIsMeasured(true);
  }, [flatNodes, flatNodeIds]);

  useIsomorphicLayoutEffect(() => {
    measureNodes();

    if (typeof ResizeObserver === "undefined") {
      return;
    }

    const observer = new ResizeObserver(() => {
      if (frameRef.current != null) {
        cancelAnimationFrame(frameRef.current);
      }

      frameRef.current = requestAnimationFrame(() => {
        measureNodes();
      });
    });

    cardRefs.current.forEach((el) => {
      if (el) observer.observe(el);
    });

    return () => {
      observer.disconnect();

      if (frameRef.current != null) {
        cancelAnimationFrame(frameRef.current);
      }
    };
  }, [measureNodes]);

  const { nodes, links, width, height } = useMemo(
    () =>
      computeLayout(tree, sizes, activeLayout, { levelGap: LEVEL_GAP, siblingGap: SIBLING_GAP }),
    [tree, sizes, activeLayout],
  );

  return (
    <div className={cx("wf-flow", isFullscreen && "wf-flow--fullscreen", className)}>
      <div className="wf-flow__toolbar">
        <button
          type="button"
          className="wf-flow__toolbar-button"
          onClick={() =>
            setActiveLayout((prev) => (prev === "vertical" ? "horizontal" : "vertical"))
          }
          aria-label={
            activeLayout === "vertical"
              ? "Switch to horizontal layout"
              : "Switch to vertical layout"
          }
          title={
            activeLayout === "vertical"
              ? "Switch to horizontal layout"
              : "Switch to vertical layout"
          }
        >
          {activeLayout === "vertical" ? (
            <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" focusable="false">
              <path
                d="M4 12h16M4 12l4-4M4 12l4 4M20 12l-4-4M20 12l-4 4"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          ) : (
            <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" focusable="false">
              <path
                d="M12 4v16M12 4l-4 4M12 4l4 4M12 20l-4-4M12 20l4-4"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          )}
        </button>

        <button
          type="button"
          className="wf-flow__toolbar-button"
          onClick={() => setIsFullscreen((prev) => !prev)}
          aria-pressed={isFullscreen}
          aria-label={isFullscreen ? "Exit full page view" : "Open full page view"}
          title={isFullscreen ? "Exit full page view" : "Full page view"}
        >
          {isFullscreen ? (
            <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" focusable="false">
              <path
                d="M9 3v4a2 2 0 0 1-2 2H3M15 3v4a2 2 0 0 0 2 2h4M9 21v-4a2 2 0 0 0-2-2H3M15 21v-4a2 2 0 0 1 2-2h4"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          ) : (
            <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" focusable="false">
              <path
                d="M3 9V5a2 2 0 0 1 2-2h4M21 9V5a2 2 0 0 0-2-2h-4M3 15v4a2 2 0 0 0 2 2h4M21 15v4a2 2 0 0 1-2 2h-4"
                fill="none"
                stroke="currentColor"
                strokeWidth="2"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          )}
        </button>
      </div>

      <div className="wf-flow__scroll">
        <div
          className={cx(
            "wf-flow__canvas",
            `wf-flow__canvas--${activeLayout}`,
            isMeasured && "wf-flow__canvas--ready",
          )}
          style={{ width, height }}
          role="tree"
          aria-label="Flow diagram"
        >
          <svg
            className="wf-flow__connectors"
            width={width}
            height={height}
            viewBox={`0 0 ${width} ${height}`}
            aria-hidden="true"
            focusable="false"
          >
            {links.map((link) => (
              <g key={link.id}>
                {/* Base connector */}
                <path d={link.d} className="wf-flow__link" />

                {/* Animated connector */}
                <path d={link.d} className="wf-flow__link wf-flow__link--animated" />
              </g>
            ))}
          </svg>

          {nodes.map((n) => (
            <div
              key={n.id}
              role="treeitem"
              aria-selected={false}
              tabIndex={0}
              aria-level={n.depth + 1}
              className="wf-flow-card"
              ref={(el) => {
                cardRefs.current.set(n.id, el);
              }}
              style={{
                transform: `translate(${n.x}px, ${n.y}px)`,
              }}
            >
              <div className="wf-flow-card__content">{n.content}</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
