"use client";

import { notFound, usePathname } from "next/navigation";
import { type ReactNode, useEffect, useMemo, useState } from "react";
import type { CourseType } from "~/model/course_model";
import CourseClient from "~/page/Course/CourseClient";
import { createSlug } from "~/utils/slug";
import { useClientSeo } from "~/utils/use_client_seo";
import { CATEGORY_BY_SLUG } from "../data";
import { buildCategorySeo } from "../lib/learn_seo";
import RemoteCourseClient from "./RemoteCourseClient";

const EMPTY_COURSES: CourseType[] = [];

function resolveCategoryData(slug: string) {
  const entry = CATEGORY_BY_SLUG.get(slug);
  if (!entry) return null;

  const [categoryTitle, courses] = entry;
  return { category: slug, categoryTitle, courses };
}

interface LearnRouteClientProps {
  /** Server-rendered <LearnPage /> passed from the page file so /learn is prerendered. */
  learnPage: ReactNode;
}

export default function LearnRouteClient({ learnPage }: LearnRouteClientProps) {
  const routePathname = usePathname();

  // Start from the router's pathname so the server/prerender and first client render
  // agree (and /learn renders real HTML), then sync to the real URL after mount.
  const [pathname, setPathname] = useState<string>(routePathname ?? "");

  useEffect(() => {
    setPathname(window.location.pathname);
  }, [routePathname]);

  useEffect(() => {
    const syncPath = () => setPathname(window.location.pathname);
    window.addEventListener("popstate", syncPath);
    return () => window.removeEventListener("popstate", syncPath);
  }, []);

  const parts = pathname.split("/").filter(Boolean);
  const categorySlug = parts[0] === "learn" ? parts[1] : undefined;
  const resolved = useMemo(
    () => (categorySlug ? resolveCategoryData(categorySlug) : null),
    [categorySlug],
  );
  const courses = resolved?.courses ?? EMPTY_COURSES;
  const groupedCourses = useMemo(
    () =>
      courses.reduce(
        (groups, course) => {
          const subCategory = course.subCategory || "General";
          (groups[subCategory] ??= []).push(course);
          return groups;
        },
        {} as Record<string, CourseType[]>,
      ),
    [courses],
  );
  const subCategoryMap = useMemo(
    () =>
      Object.fromEntries(
        [...new Set(courses.map((course) => course.subCategory || "General"))].map((title) => [
          createSlug(title),
          title,
        ]),
      ),
    [courses],
  );
  const courseSlug = categorySlug ? parts[2] : undefined;

  // SEO for category pages only (/learn/<category>). Course and topic pages set their own in
  // RemoteCourseClient, which knows the real topic name.
  const seo = useMemo(
    () => (resolved && !courseSlug ? buildCategorySeo(resolved) : null),
    [resolved, courseSlug],
  );
  useClientSeo(seo);

  if (parts[0] !== "learn") {
    return null;
  }

  if (!categorySlug) {
    return <>{learnPage}</>;
  }

  if (!resolved) {
    notFound();
  }

  if (!courseSlug) {
    return (
      <CourseClient
        categoryTitle={resolved.categoryTitle}
        groupedCourses={groupedCourses}
        subCategoryMap={subCategoryMap}
        onlyOneCourse={courses.length === 1}
        basePath="learn"
        clientNavigation
      />
    );
  }

  return (
    <RemoteCourseClient
      category={resolved.category}
      categoryTitle={resolved.categoryTitle}
      courses={courses}
      pathname={pathname}
    />
  );
}
