import React from "react";
import "./List.css";

type ListType = "ordered" | "unordered";

type OrderedSymbol = "number" | "alphabet" | "uppercase-alphabet" | "roman" | "lowercase-roman";

export type ListItem = {
  text: React.ReactNode;
  children?: ListItemContent[];
};

type ListItemContent = React.ReactNode | ListItem;

type ListProps = {
  items?: ListItemContent[];
  type?: ListType;
  orderedSymbol?: OrderedSymbol;
  glass?: boolean;
  small?: boolean;
  children?: React.ReactNode;
};

const orderedClassMap: Record<OrderedSymbol, string> = {
  number: "decimal",
  alphabet: "lower-alpha",
  "uppercase-alphabet": "upper-alpha",
  roman: "upper-roman",
  "lowercase-roman": "lower-roman",
};

function isListItem(item: ListItemContent): item is ListItem {
  return typeof item === "object" && item !== null && !React.isValidElement(item) && "text" in item;
}

const Item: React.FC<{ children?: React.ReactNode }> = ({ children }) => <>{children}</>;

const parseChildrenToItems = (children: React.ReactNode): ListItem[] => {
  const parsedItems: ListItem[] = [];

  React.Children.forEach(children, (child) => {
    if (!React.isValidElement(child)) return;

    const element = child as React.ReactElement<{
      children?: React.ReactNode;
    }>;

    const allChildren = React.Children.toArray(element.props.children);

    const textNodes = allChildren.filter(
      (c) =>
        typeof c === "string" ||
        typeof c === "number" ||
        (React.isValidElement(c) && c.type !== Item),
    );

    const nestedItems = allChildren.filter(
      (c): c is React.ReactElement => React.isValidElement(c) && c.type === Item,
    );

    parsedItems.push({
      text: textNodes.length === 1 ? textNodes[0] : <>{textNodes}</>,
      children: nestedItems.length > 0 ? parseChildrenToItems(nestedItems) : undefined,
    });
  });

  return parsedItems;
};

const List: React.FC<ListProps> & { Item: typeof Item } = ({
  items,
  type = "unordered",
  orderedSymbol = "number",
  glass = false,
  small = false,
  children,
}) => {
  const dataItems = items ?? parseChildrenToItems(children);

  const renderList = (listItems: ListItemContent[], nested = false): React.ReactNode => {
    const ListTag = type === "ordered" ? "ol" : "ul";

    return (
      <ListTag
        className={[
          "glassmorphic-list",
          nested && "nested",
          glass && "glass",
          small && "small",
          type === "ordered" && orderedClassMap[orderedSymbol],
        ]
          .filter(Boolean)
          .join(" ")}
      >
        {listItems.map((item, index) => (
          <li key={index} className="list-item">
            {isListItem(item) ? item.text : item}
            {isListItem(item) && item.children && renderList(item.children, true)}
          </li>
        ))}
      </ListTag>
    );
  };

  return <div className="glassmorphic-list-container">{renderList(dataItems)}</div>;
};

List.Item = Item;

export default List;
