"use client";

// This file used to import and call the Syntax component directly, but
// Syntax is a Server Component — a 'use client' file can never import and
// render one. Syntax now runs on the server, inside FileTree.tsx, and its
// output arrives here already rendered, via `file.element`. This file only
// wraps that already-rendered output; it never touches Syntax itself.

import type { CodeFile } from "./Context";
import styles from "./FileTree.module.css";

export interface EditorProps {
  /**
   * The file this slot renders. `FileTreeClient` mounts one `Editor` per
   * code file in the tree, always — see FileTreeClient.tsx — so this
   * component doesn't need to know or care whether its slot is currently
   * the expanded one; that's handled entirely by the wrapping `.branch`
   * collapse and `inert` in the parent.
   */
  file: CodeFile;
}

/**
 * Renders a single code file's pre-rendered content. One of these exists
 * for every code file in the tree at all times (see FileTreeClient), not
 * just the currently-open one — only its wrapping `.branch` slot decides
 * whether it's actually visible.
 */
export function Editor({ file }: EditorProps) {
  return <div className={styles.editorContent}>{file.element}</div>;
}
