import { useEffect } from "react";
import { applyClientSeo } from "./clientSeo";
import type { SEOOptions } from "./meta";

export interface ClientSeo {
  options: SEOOptions;
  jsonLd?: object[];
}

/**
 * Applies title, meta tags and JSON-LD while the component is mounted, and undoes only its own
 * changes on cleanup. `seo` must be memoized (useMemo), otherwise it re-applies on every render.
 */
export function useClientSeo(seo: ClientSeo | null) {
  useEffect(() => {
    if (!seo) return;
    return applyClientSeo(seo.options, seo.jsonLd);
  }, [seo]);
}
