import * as XLSX from "xlsx";

import { isCsv, isExcel } from "~/utils/file_type";

interface RowData {
  [key: string]: string | number | boolean | null;
}

export interface TableData {
  headers: string[];
  rows: RowData[];
  error?: string;
}

export async function getTableData(url: string): Promise<TableData> {
  try {
    if (!isExcel(url) && !isCsv(url)) {
      return {
        headers: [],
        rows: [],
        error: "Unsupported file type",
      };
    }

    const response = await fetch(url);

    if (!response.ok) {
      return {
        headers: [],
        rows: [],
        error: `Failed to load table (${response.status})`,
      };
    }

    let workbook: XLSX.WorkBook;

    if (isCsv(url)) {
      workbook = XLSX.read(await response.text(), {
        type: "string",
      });
    } else {
      workbook = XLSX.read(await response.arrayBuffer(), {
        type: "array",
      });
    }

    const sheet = workbook.Sheets[workbook.SheetNames[0]];

    const json = XLSX.utils.sheet_to_json(sheet, {
      header: 1,
      defval: "",
    });

    if (!json.length) {
      return {
        headers: [],
        rows: [],
        error: "Table is empty",
      };
    }

    const [headerRow, ...bodyRows] = json as (string | number | boolean | null)[][];

    const headers = headerRow.map(String);

    const rows = bodyRows.map((row) =>
      Object.fromEntries(headers.map((header, i) => [header, row[i] ?? ""])),
    );

    return {
      headers,
      rows,
    };
  } catch {
    return {
      headers: [],
      rows: [],
      error: "Failed to load table",
    };
  }
}
