"use client";

import type { KeyboardEvent } from "react";
import { useCallback, useEffect, useRef, useState } from "react";
import type { CodeFile } from "./Context";
import { TreeLevelProvider, TreeRootProvider } from "./Context";
import { Editor } from "./Editor";
import styles from "./FileTree.module.css";
import { DownloadIcon } from "./Icons";
import type { FileEntry, FileTreeProps } from "./types";

/**
 * Toggles a folder treeitem open/closed.
 *
 * We can't just call `el.click()` here: the actual toggle handler lives on
 * the inner `.row` div inside FolderItem, not on this outer `role="treeitem"`
 * element, and native click events only bubble UP from their target — they
 * never propagate down into descendants. So `el.click()` fires on `el`,
 * finds no listener, and bubbles harmlessly up toward the tree root.
 *
 * Instead we dispatch a synthetic Enter keydown directly at `el`. FolderItem
 * already listens for Enter/Space on this exact element to toggle, guarded
 * by `event.target === event.currentTarget` — which holds here since we're
 * dispatching straight at `el`, not at a descendant.
 */
function toggleFolder(el: HTMLElement): void {
  el.dispatchEvent(new KeyboardEvent("keydown", { key: "Enter", bubbles: true, cancelable: true }));
}

/**
 * Reads the ordered list of currently-visible treeitem elements inside a
 * container. Folders always mount their children (for SSR completeness),
 * so "visible" is determined by filtering out anything under an `inert`
 * (collapsed) branch, rather than by what's present in the DOM at all.
 */
function getTreeItems(container: HTMLElement): HTMLElement[] {
  return Array.from(container.querySelectorAll<HTMLElement>('[role="treeitem"]')).filter(
    (el) => !el.closest("[inert]"),
  );
}

interface FileTreeClientProps extends FileTreeProps {
  /**
   * Every code file in the tree, pre-rendered server-side (see
   * FileTree.tsx) — regardless of nesting depth, folder open state, or
   * whether anyone has opened it yet. Rendered into the DOM in full below,
   * on first paint, so the editor pane's content is SSR/SEO-visible even
   * before any file has actually been opened.
   */
  codeFiles: CodeFile[];
  /**
   * Every file in the tree — code or not — as a flat `{ path, content }`
   * list, used to build the "download all as .zip" archive. A file with
   * no `code` prop still gets an entry here, just with `content: ""`.
   */
  fileEntries: FileEntry[];
  /** Base filename (no extension) for the downloaded archive. */
  zipName: string;
}

/**
 * The interactive shell for FileTree: owns focus/selection state and all
 * keyboard handling. Receives its children already fully processed by the
 * server-side `FileTree` wrapper (see FileTree.tsx), plus a flat
 * `codeFiles` list carrying every code file's pre-rendered `Syntax`
 * output. This component itself never touches `Syntax`.
 *
 * Every entry in `codeFiles` gets its own always-mounted slot in the
 * editor pane, styled with the exact same `.branch`/`.branchInner`
 * collapse FolderItem already uses for its children: the slot for
 * whichever file is `selectedId` expands and is interactive, every other
 * slot collapses to zero height and gets `inert` so it's pulled out of
 * the accessibility tree and tab order — but its markup, and the code
 * inside it, stays right there in the initial HTML regardless. Nothing
 * is conditionally mounted the way the old click-to-render Editor pane
 * was.
 */
export function FileTreeClient({ children, codeFiles, fileEntries, zipName }: FileTreeClientProps) {
  const rootRef = useRef<HTMLDivElement>(null);
  const [focusedId, setFocusedId] = useState<string | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [isZipping, setIsZipping] = useState(false);

  // Once the tree has mounted, make the very first treeitem the initial tab
  // stop. Every node renders tabIndex={-1} until this runs, so server and
  // client markup agree on the first paint and there is no hydration mismatch.
  useEffect(() => {
    if (focusedId !== null) return;
    const container = rootRef.current;
    if (!container) return;
    const first = getTreeItems(container)[0];
    const firstId = first?.dataset.treeId;
    if (firstId) setFocusedId(firstId);
  }, [focusedId]);

  const handleKeyDown = useCallback((event: KeyboardEvent<HTMLDivElement>) => {
    const container = rootRef.current;
    if (!container) return;

    const items = getTreeItems(container);
    const currentIndex = items.indexOf(document.activeElement as HTMLElement);
    if (currentIndex === -1) return;

    const current = items[currentIndex];

    switch (event.key) {
      case "ArrowDown": {
        event.preventDefault();
        items[currentIndex + 1]?.focus();
        break;
      }
      case "ArrowUp": {
        event.preventDefault();
        items[currentIndex - 1]?.focus();
        break;
      }
      case "Home": {
        event.preventDefault();
        items[0]?.focus();
        break;
      }
      case "End": {
        event.preventDefault();
        items[items.length - 1]?.focus();
        break;
      }
      case "ArrowRight": {
        if (current.dataset.treeType !== "folder") break;
        if (current.getAttribute("aria-expanded") === "false") {
          event.preventDefault();
          toggleFolder(current);
        } else {
          const next = items[currentIndex + 1];
          const currentLevel = Number(current.getAttribute("aria-level"));
          const nextLevel = next ? Number(next.getAttribute("aria-level")) : -1;
          if (next && nextLevel > currentLevel) {
            event.preventDefault();
            next.focus();
          }
        }
        break;
      }
      case "ArrowLeft": {
        if (
          current.dataset.treeType === "folder" &&
          current.getAttribute("aria-expanded") === "true"
        ) {
          event.preventDefault();
          toggleFolder(current);
        } else {
          const parentItem = current.parentElement?.closest<HTMLElement>('[role="treeitem"]');
          if (parentItem) {
            event.preventDefault();
            parentItem.focus();
          }
        }
        break;
      }
      default:
        break;
    }
  }, []);

  // `jszip` is only imported here, on click, not at module scope — the
  // tree renders (and, more importantly, hydrates) without ever paying
  // for the zip library unless someone actually asks to download.
  //
  // Every entry in `fileEntries` gets written into the archive as-is: a
  // file with real `code` writes that source, a file without it writes
  // `content: ""` (see FileTree.tsx), so the downloaded zip always
  // mirrors the full tree structure rather than only the files that
  // happen to have content.
  const handleDownloadZip = useCallback(async () => {
    if (isZipping || fileEntries.length === 0) return;

    setIsZipping(true);
    try {
      const { default: JSZip } = await import("jszip");
      const zip = new JSZip();
      for (const entry of fileEntries) {
        zip.file(entry.path, entry.content);
      }

      const blob = await zip.generateAsync({ type: "blob" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = `${zipName}.zip`;
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(url);
    } catch (error) {
      console.error("Failed to build the download archive:", error);
    } finally {
      setIsZipping(false);
    }
  }, [fileEntries, isZipping, zipName]);

  return (
    <TreeRootProvider value={{ focusedId, setFocusedId, selectedId, setSelectedId }}>
      <TreeLevelProvider value={{ level: 1, parentPath: "" }}>
        <div className={styles.workspace}>
          <div className={styles.explorerPane}>
            {fileEntries.length > 0 && (
              <div className={styles.toolbar}>
                <span className={styles.toolbarLabel}>Files</span>
                <button
                  type="button"
                  className={styles.downloadButton}
                  onClick={handleDownloadZip}
                  disabled={isZipping}
                  aria-label={`Download all files as ${zipName}.zip`}
                  title={`Download all files as ${zipName}.zip`}
                >
                  <DownloadIcon />
                </button>
              </div>
            )}
            <div
              ref={rootRef}
              role="tree"
              aria-label="File tree"
              className={styles.tree}
              onKeyDown={handleKeyDown}
            >
              {children}
            </div>
          </div>
          {codeFiles.length > 0 && (
            <div className={`${styles.editorPane} ${selectedId ? styles.editorPaneOpen : ""}`}>
              <div className={styles.editorPaneInner}>
                {codeFiles.map((file) => {
                  const isOpen = selectedId === file.id;
                  return (
                    <div
                      key={file.id}
                      className={styles.branch}
                      data-open={isOpen}
                      {...(isOpen ? {} : { inert: true })}
                    >
                      <div className={styles.branchInner}>
                        <Editor file={file} />
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>
      </TreeLevelProvider>
    </TreeRootProvider>
  );
}
