"use client";

import { notFound } from "next/navigation";
import { useEffect, useMemo, useState } from "react";
import type { CourseType } from "~/model/course_model";
import ErrorLayout from "~/page/Errors/ErrorLayout";
import Loading from "~/page/Loading/Loading";
import TutorialClient, { type ClientContentData } from "~/page/Tutorial/TutorialClient";

import { createSlug } from "~/utils/slug";
import { useClientSeo } from "~/utils/use_client_seo";
import { buildCourseSeo } from "../lib/learn_seo";
import { fetchCourseMetadata } from "../lib/remote";
import {
  buildLegacyTopicSlugMap,
  buildTopicIndexMap,
  buildTopicRouteMap,
  createTopicRoute,
  getTopicRouteKey,
  listTopics,
} from "../lib/topic";
import type { CourseMetadata } from "../lib/types";
import CourseHome from "./CourseHome";
import PageBuilderContent from "./PageBuilderContent";

const metadataCache = new Map<string, Promise<CourseMetadata>>();

function getCachedMetadata(docsUrl: string) {
  const cached = metadataCache.get(docsUrl);
  if (cached) return cached;

  const request = fetchCourseMetadata(docsUrl).catch((error: unknown) => {
    metadataCache.delete(docsUrl);
    throw error;
  });

  metadataCache.set(docsUrl, request);
  return request;
}

function getPathParts(pathname: string) {
  return pathname
    .split("/")
    .filter(Boolean)
    .map((part) => {
      try {
        return decodeURIComponent(part);
      } catch {
        return part;
      }
    });
}

interface RemoteCourseClientProps {
  category: string;
  categoryTitle: string;
  courses: CourseType[];
  pathname: string | null;
}

export default function RemoteCourseClient({
  category,
  categoryTitle,
  courses,
  pathname,
}: RemoteCourseClientProps) {
  const pathParts = getPathParts(pathname ?? "");
  const [, , rawCourse] = pathParts;
  const rawTopicParts = pathParts.slice(3);
  // Built once per `courses` list (memoized), then just `.get()` instead
  // of rescanning with `.find()` on every render — same pattern as
  // `CATEGORY_BY_SLUG` for categories.
  const courseBySlug = useMemo(
    () => new Map(courses.map((item) => [createSlug(item.name), item])),
    [courses],
  );
  const course = courseBySlug.get(rawCourse ?? "");
  const topicRouteKey = rawTopicParts.map((part) => createSlug(part)).join("/");
  const hasTopicPath = rawTopicParts.length > 0;
  const docsUrl = course?.docs;
  const [loadState, setLoadState] = useState<{
    docsUrl: string | null;
    metadata: CourseMetadata | null;
    status: "idle" | "loading" | "ready" | "error";
    error: string | null;
  }>({
    docsUrl: null,
    metadata: null,
    status: "idle",
    error: null,
  });

  useEffect(() => {
    if (!docsUrl) {
      return;
    }

    let active = true;

    getCachedMetadata(docsUrl)
      .then((nextMetadata) => {
        if (active) {
          setLoadState({
            docsUrl,
            metadata: nextMetadata,
            status: "ready",
            error: null,
          });
        }
      })
      .catch((reason: unknown) => {
        if (active) {
          setLoadState({
            docsUrl,
            metadata: null,
            status: "error",
            error: reason instanceof Error ? reason.message : "Unable to load course metadata.",
          });
        }
      });

    return () => {
      active = false;
    };
  }, [docsUrl]);

  const metadata = loadState.docsUrl === docsUrl ? loadState.metadata : null;
  const status = loadState.docsUrl === docsUrl ? loadState.status : "loading";
  const error = loadState.docsUrl === docsUrl ? loadState.error : null;
  const topics = useMemo(() => (metadata ? listTopics(metadata, course) : []), [metadata, course]);
  const topicByRoute = useMemo(() => buildTopicRouteMap(topics), [topics]);
  const legacyTopicBySlug = useMemo(() => buildLegacyTopicSlugMap(topics), [topics]);
  const topicIndexByRoute = useMemo(() => buildTopicIndexMap(topics), [topics]);
  const matchedTopic = hasTopicPath
    ? (topicByRoute.get(topicRouteKey) ??
      (rawTopicParts.length === 1 ? (legacyTopicBySlug.get(topicRouteKey) ?? null) : null))
    : null;
  const currentTopicRouteKey = matchedTopic ? getTopicRouteKey(matchedTopic) : topicRouteKey;
  const route = useMemo(
    () =>
      course
        ? topics.map((topic) => ({
            topic: topic.name,
            heading: topic.heading,
            key: getTopicRouteKey(topic),
            path: createTopicRoute("learn", category, course.name, topic),
            type: "H1" as const,
          }))
        : [],
    [topics, course, category],
  );

  // Until the course metadata loads we can't tell "topic not found" from "still loading", so
  // use the course-level title and switch to the topic title once it's ready.
  const seo = useMemo(
    () =>
      course
        ? buildCourseSeo({
            category,
            categoryTitle,
            course,
            topicName: status === "ready" ? matchedTopic?.name : undefined,
            path: pathname || undefined,
          })
        : null,
    [course, matchedTopic, status, category, categoryTitle, pathname],
  );
  useClientSeo(seo);

  if (!course) {
    notFound();
  }

  if (hasTopicPath && (course.singlePage || !course.docs)) {
    notFound();
  }

  if (!course.docs) {
    return (
      <ErrorLayout
        title="Course content is not configured"
        description={
          <>
            Add a published course root to <code>docs</code> in the course registry. It must expose{" "}
            <code>meta.json</code>.
          </>
        }
      />
    );
  }

  if (status === "loading" || status === "idle") {
    return <Loading />;
  }

  if (status === "error" || !metadata) {
    return (
      <ErrorLayout
        title="Unable to load course metadata"
        description={error ?? "The remote course repository is unavailable."}
      />
    );
  }

  if (hasTopicPath && !matchedTopic) {
    notFound();
  }

  const topicContent = hasTopicPath ? matchedTopic : null;
  const contentData: ClientContentData = {
    about: course,
    route,
  };
  const currentIndex = hasTopicPath ? (topicIndexByRoute.get(currentTopicRouteKey) ?? -1) : -1;
  const previousTopicEntry = currentIndex > 0 ? topics[currentIndex - 1] : null;
  const nextTopicEntry =
    currentIndex >= 0 && currentIndex < topics.length - 1 ? topics[currentIndex + 1] : null;
  const previousTopic = previousTopicEntry?.name ?? null;
  const previousTopicPath = previousTopicEntry
    ? createTopicRoute("learn", category, course.name, previousTopicEntry)
    : null;
  const nextTopic = nextTopicEntry?.name ?? null;
  const nextTopicPath = nextTopicEntry
    ? createTopicRoute("learn", category, course.name, nextTopicEntry)
    : null;
  const content = course.singlePage ? (
    <>
      <CourseHome course={course} topics={topics} category={category} showTopicPrompt={false} />
      <PageBuilderContent
        structure={metadata}
        topic={null}
        docsUrl={course.docs}
        options={course}
      />
    </>
  ) : topicContent ? (
    <PageBuilderContent
      structure={metadata}
      topic={topicContent}
      docsUrl={course.docs}
      options={course}
    />
  ) : (
    <CourseHome course={course} topics={topics} category={category} />
  );

  return (
    <TutorialClient
      contentData={contentData}
      category={category}
      currentTopic={currentTopicRouteKey}
      previousTopic={previousTopic}
      previousTopicPath={previousTopicPath}
      nextTopic={nextTopic}
      nextTopicPath={nextTopicPath}
      isMultiPage={topics.length > 0}
      basePath="learn"
      clientNavigation
    >
      {content}
    </TutorialClient>
  );
}
