"use client";
import ArrowBackIosIcon from "@mui/icons-material/ArrowBackIos";
import ArrowForwardIosIcon from "@mui/icons-material/ArrowForwardIos";
import SentenceIcon from "@mui/icons-material/ViewStream";
import TableIcon from "@mui/icons-material/Window";
import { use, useEffect, useMemo, useRef, useState } from "react";
import ReactPaginateImport from "react-paginate";
import HighlightMatch from "~/components/HighlightMatch";
import SearchBar from "~/components/SearchBar/SearchBar";
import Table from "../Table/Table";
import styles from "./Lang.module.scss";
import type { LangData, ViewType } from "./types";

const paginateModule = ReactPaginateImport as unknown as {
  default?: typeof ReactPaginateImport;
};
const ReactPaginate = paginateModule.default ?? ReactPaginateImport;

interface LangInnerProps {
  viewType?: ViewType;
  lang: LangData | Promise<LangData>;
}

const ITEMS_PER_PAGE = 20;

function isPromiseLike<T>(value: T | Promise<T>): value is Promise<T> {
  return typeof (value as { then?: unknown })?.then === "function";
}

const LangInner: React.FC<LangInnerProps> = ({
  viewType: initialViewType = "Sentence",
  lang: langProp,
}) => {
  const lang = isPromiseLike(langProp) ? use(langProp) : langProp;

  const [viewType, setViewType] = useState<ViewType>(initialViewType);
  const [searchTerm, setSearchTerm] = useState("");
  const [currentPage, setCurrentPage] = useState(0);

  const [paginationSettings, setPaginationSettings] = useState({
    pageRangeDisplayed: 2,
    marginPagesDisplayed: 1,
  });

  const containerRef = useRef<HTMLDivElement | null>(null);
  const touchStartX = useRef<number | null>(null);

  const filtered = useMemo(
    () =>
      lang.data.filter(
        (s) =>
          s.primary.toLowerCase().includes(searchTerm.toLowerCase()) ||
          s.secondary.toLowerCase().includes(searchTerm.toLowerCase()),
      ),
    [searchTerm, lang.data],
  );

  const pageCount = Math.ceil(filtered.length / ITEMS_PER_PAGE) || 1;
  const safePage = Math.min(Math.max(0, currentPage), pageCount - 1);

  const pageItems = filtered.slice(safePage * ITEMS_PER_PAGE, (safePage + 1) * ITEMS_PER_PAGE);

  const handlePageClick = ({ selected }: { selected: number }) => {
    setCurrentPage(selected);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  useEffect(() => {
    const updatePaginationSettings = () => {
      const width = window.innerWidth;
      if (width < 480) {
        setPaginationSettings({
          pageRangeDisplayed: 1,
          marginPagesDisplayed: 1,
        });
      } else if (width < 768) {
        setPaginationSettings({
          pageRangeDisplayed: 2,
          marginPagesDisplayed: 1,
        });
      } else {
        setPaginationSettings({
          pageRangeDisplayed: 3,
          marginPagesDisplayed: 2,
        });
      }
    };

    updatePaginationSettings();
    window.addEventListener("resize", updatePaginationSettings);
    return () => window.removeEventListener("resize", updatePaginationSettings);
  }, []);

  useEffect(() => {
    const handleTouchStart = (e: TouchEvent) => {
      touchStartX.current = e.touches[0].clientX;
    };

    const handleTouchEnd = (e: TouchEvent) => {
      if (touchStartX.current === null) return;
      const touchEndX = e.changedTouches[0].clientX;
      const diff = touchStartX.current - touchEndX;

      if (Math.abs(diff) > 50) {
        if (diff > 0 && currentPage < pageCount - 1) {
          setCurrentPage((prev) => prev + 1);
        } else if (diff < 0 && currentPage > 0) {
          setCurrentPage((prev) => prev - 1);
        }
      }
      touchStartX.current = null;
    };

    const node = containerRef.current;
    if (node) {
      node.addEventListener("touchstart", handleTouchStart, { passive: true });
      node.addEventListener("touchend", handleTouchEnd);
    }
    return () => {
      if (node) {
        node.removeEventListener("touchstart", handleTouchStart);
        node.removeEventListener("touchend", handleTouchEnd);
      }
    };
  }, [currentPage, pageCount]);

  return (
    <div className={styles.wrapper} ref={containerRef}>
      <div className={styles.controls}>
        <SearchBar
          searchTerm={searchTerm}
          setSearchTerm={(value) => {
            setSearchTerm(value);
            setCurrentPage(0);
          }}
        />
        <span
          className="toggle-button toggle-button-wh"
          onClick={() => {
            setViewType(viewType === "Sentence" ? "Table" : "Sentence");
            setCurrentPage(0);
          }}
        >
          {viewType === "Sentence" ? <TableIcon /> : <SentenceIcon />}
        </span>
      </div>

      {filtered.length === 0 ? (
        <div className={styles.noResult}>No result found.</div>
      ) : viewType === "Sentence" ? (
        <div className={styles.sentenceContainer}>
          {pageItems.map((sentence, index) => (
            <div className={styles.sentence} key={`sentence-${index}`}>
              <div className={styles.primary}>
                <HighlightMatch text={sentence.primary} query={searchTerm} />
              </div>
              <div className={styles.secondary}>
                <HighlightMatch text={sentence.secondary} query={searchTerm} />
              </div>
            </div>
          ))}
        </div>
      ) : (
        <Table>
          <thead>
            <tr>
              <th>{lang.type.primary}</th>
              <th>{lang.type.secondary}</th>
            </tr>
          </thead>
          <tbody>
            {pageItems.map((sentence, index) => (
              <tr key={`sentence-${index}`}>
                <td>
                  <HighlightMatch text={sentence.primary} query={searchTerm} />
                </td>
                <td>
                  <HighlightMatch text={sentence.secondary} query={searchTerm} />
                </td>
              </tr>
            ))}
          </tbody>
        </Table>
      )}

      {pageCount > 1 && (
        <ReactPaginate
          breakLabel="..."
          nextLabel={<ArrowForwardIosIcon />}
          previousLabel={<ArrowBackIosIcon />}
          onPageChange={handlePageClick}
          pageRangeDisplayed={paginationSettings.pageRangeDisplayed}
          marginPagesDisplayed={paginationSettings.marginPagesDisplayed}
          pageCount={pageCount}
          containerClassName={styles.pagination}
          activeClassName={styles.activePage}
          disabledClassName={styles.disabled}
          nextClassName={styles.btn}
          previousClassName={styles.btn}
          forcePage={safePage}
        />
      )}
    </div>
  );
};

export default LangInner;
