import Link from "next/link";
import { IMAGE_DOMAIN } from "~/utils/domain";

export interface CategoryCardProps {
  /** Display name of the collection, e.g. "JavaScript" */
  title: string;
  /** Image shown in the 16:9 collection media area */
  img: string;
  /** Broad learning field, such as IT, Finance, or Education */
  field: string;
  /** Number of topics/courses inside this collection */
  totalCourses: number;
  /** URL slug for the collection (kept for callers that need it separately from href) */
  slug: string;
  /** Fully resolved destination URL for the card */
  href: string;
}

/**
 * A single, fully clickable collection card.
 * Visual language is copied 1:1 from the Home page "Final CTA" cards
 * (`hp-final-card` / `hp-glass`) so the Learn page feels like the same product.
 */
const CategoryCard = ({ title, img, field, totalCourses, href }: CategoryCardProps) => {
  const courseLabel = totalCourses === 1 ? "course" : "courses";

  return (
    <Link
      href={href}
      className="page-card glass-panel lp-card"
      aria-label={`Explore the ${title} collection — ${totalCourses} ${courseLabel}`}
    >
      <div className="lp-card-media glass-panel">
        <img src={`${IMAGE_DOMAIN}/${img}.webp`} alt={title} loading="lazy" />
      </div>

      <div className="lp-card-top">
        <div className="lp-card-info">
          <span className="lp-card-field">{field}</span>
          <h2 className="lp-card-title">{title}</h2>
          <span className="lp-card-count">
            {totalCourses} {courseLabel}
          </span>
        </div>
      </div>

      <span className="lp-card-arrow">
        Explore Collection <span aria-hidden="true">→</span>
      </span>
    </Link>
  );
};

export default CategoryCard;
