import { SITE_NAME, SITE_URL } from "~/utils/domain";

interface LearningResourceSchemaProps {
  title: string;
  description: string;
  url: string;
}

export default function createLearningResourceSchema({
  title,
  description,
  url,
}: LearningResourceSchemaProps) {
  return {
    "@context": "https://schema.org",
    "@type": "Article",

    name: title,
    description,

    url,

    author: {
      "@type": "Person",
      name: "Sathish Kumar",
    },

    publisher: {
      "@type": "Organization",
      name: SITE_NAME,
      logo: {
        "@type": "ImageObject",
        url: `${SITE_URL}/favicon-32x32.png`,
      },
    },

    educationalLevel: "Beginner to Advanced",
  };
}
