"use client";

import SearchIcon from "@mui/icons-material/Search";
import { useMemo, useState } from "react";
import { pushClientPath } from "../lib/remote";
import type { CourseType } from "~/model/course_model";
import type { TopicEntry } from "../lib/types";
import { createTopicRoute } from "../lib/topic";
import Media from "~/ui/Media/Media";
import Para from "~/ui/Para/Para";
import Title from "~/ui/Title/Title";
import { IMAGE_DOMAIN } from "~/utils/domain";
import "./CourseHome.css";
import Link from "next/link";

export default function CourseHome({
  course,
  topics = [],
  category,
  showTopicPrompt = true,
}: {
  course: CourseType;
  topics?: TopicEntry[];
  category?: string;
  showTopicPrompt?: boolean;
}) {
  const [topicQuery, setTopicQuery] = useState("");
  const filteredTopics = useMemo(() => {
    const normalizedQuery = topicQuery.trim().toLowerCase();
    if (!normalizedQuery) return topics;

    return topics.filter((topic) => topic.name.toLowerCase().includes(normalizedQuery));
  }, [topicQuery, topics]);
  const topicSections = useMemo(() => {
    const sections = new Map<
      string | null,
      { heading: string | null; items: Array<{ topic: TopicEntry; index: number }> }
    >();

    filteredTopics.forEach((topic, index) => {
      const heading = topic.mode === "heading" ? topic.section : null;
      let section = sections.get(heading);

      if (!section) {
        section = { heading, items: [] };
        sections.set(heading, section);
      }

      section.items.push({ topic, index });
    });

    return Array.from(sections.values());
  }, [filteredTopics]);
  const canNavigateToTopics = Boolean(category);

  return (
    <>
      <Title>{course.name}</Title>
      {course.img && (
        <Media
          src={IMAGE_DOMAIN ? `${IMAGE_DOMAIN}/${course.img}` : course.img}
          alt={course.name}
        />
      )}
      <Para>{course.description}</Para>
      {showTopicPrompt && (
        <p className="course-home-note">
          Choose a topic from the course navigation to begin learning.
        </p>
      )}
      {topics.length > 0 && (
        <section className="course-topic-browser" aria-labelledby="course-topics-title">
          <div className="course-topic-browser-header">
            <div>
              <p className="course-topic-eyebrow">Course outline</p>
              <h2 id="course-topics-title">Explore the topics</h2>
              <p>Pick a topic to start learning at your own pace.</p>
            </div>
            <span className="course-topic-count">
              {topics.length} {topics.length === 1 ? "topic" : "topics"}
            </span>
          </div>

          <label className="course-topic-search">
            <SearchIcon aria-hidden="true" fontSize="small" />
            <span className="course-topic-visually-hidden">Filter course topics</span>
            <input
              type="search"
              value={topicQuery}
              onChange={(event) => setTopicQuery(event.target.value)}
              placeholder="Search topics..."
            />
          </label>

          {filteredTopics.length > 0 ? (
            topicSections.map((section) => (
              <div className="course-topic-section" key={section.heading ?? "topics"}>
                {section.heading && (
                  <h3 className="course-topic-section-heading">{section.heading}</h3>
                )}
                <div className="course-topic-grid">
                  {section.items.map(({ topic, index }) => {
                    const path = canNavigateToTopics
                      ? createTopicRoute("learn", category!, course.name, topic)
                      : "#";

                    return (
                      <Link
                        key={`${topic.name}-${index}`}
                        aria-disabled={!canNavigateToTopics}
                        className="course-topic-card"
                        href={path}
                        onClick={(event) => {
                          if (!canNavigateToTopics) {
                            event.preventDefault();
                            return;
                          }
                          event.preventDefault();
                          pushClientPath(path);
                        }}
                      >
                        <span className="course-topic-number">
                          {String(index + 1).padStart(2, "0")}
                        </span>
                        <span className="course-topic-name">{topic.name}</span>
                        <span className="course-topic-arrow" aria-hidden="true">
                          →
                        </span>
                      </Link>
                    );
                  })}
                </div>
              </div>
            ))
          ) : (
            <p className="course-topic-empty">No topics match “{topicQuery}”.</p>
          )}
        </section>
      )}
      {!course.docs && (
        <p role="alert">
          This course does not have a remote content URL configured yet. Add its <code>docs</code>{" "}
          value to the course registry.
        </p>
      )}
    </>
  );
}
