import React, { type ReactNode } from "react";
import Para from "~/ui/Para/Para";
import type { FlowNodeDatum } from "./Flow.types";
import { FlowItem } from "./FlowItem";

/**
 * Walks the children passed to <Flow>, finds every <Flow.Item> element
 * (only direct siblings / direct nesting is honoured, mirroring how
 * authors write the hierarchy) and turns it into a plain data tree.
 *
 * CRITICAL: this must run inside a Server Component, and specifically
 * inside the same server render pass where the JSX was authored (i.e.
 * directly in Flow.tsx, before Flow.tsx returns anything). At that point
 * `FlowItem` is still a live function reference — nothing has been sent
 * across the Server/Client Flight boundary yet — so `child.type ===
 * FlowItem` is a plain, reliable JS reference check. Do not call this
 * from a Client Component: by the time JSX reaches a "use client" module,
 * any Server Component elements embedded in it (like <Flow.Item>) have
 * already been resolved away by React, and this check will silently
 * return an empty tree.
 *
 * Each <Flow.Item> may contain a mix of "content" nodes (anything that
 * isn't itself a <Flow.Item>) and nested <Flow.Item> elements describing
 * its children. Content nodes are preserved in their original order and
 * rendered together inside the card.
 *
 * IDs are derived from each item's structural position (its path of
 * sibling indices), not from a mutable counter. This keeps them stable
 * across re-renders and identical between server and client, which is
 * required to avoid hydration mismatches. Authors can still opt into a
 * fully stable identity across reorders by passing a React `key`.
 */

/**
 * Content written directly under a <Flow.Item> (plain text, sitting on
 * lines adjacent to nested <Flow.Item>s with no blank line between them)
 * gets fused by remark/MDX into a single paragraph node before it ever
 * reaches this parser. Depending on how the surrounding MDX pipeline maps
 * markdown syntax to components, that paragraph can arrive as either a
 * literal HTML `<p>` element or — when the project's mdx-components.tsx
 * maps `p` to a design-system component — as a `<Para>` element instead.
 * Both are "just a paragraph" as far as Flow is concerned, so both must
 * be recognised here or nested <Flow.Item>s silently get swallowed as
 * flattened text inside the wrapper (see: everything collapsing into one
 * card).
 */
function isParagraphElement(
  node: React.ReactNode,
): node is React.ReactElement<{ children?: React.ReactNode }> {
  return React.isValidElement(node) && (node.type === "p" || node.type === Para);
}

function containsFlowItem(children: ReactNode): boolean {
  let found = false;
  React.Children.forEach(children, (c) => {
    if (React.isValidElement(c) && c.type === FlowItem) {
      found = true;
    } else if (isParagraphElement(c) && containsFlowItem(c.props.children)) {
      found = true;
    }
  });
  return found;
}

/**
 * Fully unwraps every paragraph wrapper found among a set of children,
 * however many there are and wherever they sit — not just a single
 * top-level wrapper. This matters because MDX rarely hands a
 * <Flow.Item>'s children over as one clean node: it commonly wraps a lone
 * text run in its own paragraph (e.g. a leaf item like "C Program"), and
 * often pads the array with whitespace-only text nodes from source
 * formatting (so a single meaningful paragraph is one of several array
 * entries, not "the" child). A naive check for "is `children` itself one
 * paragraph element" misses both of those shapes, letting a stray
 * <p>/<Para> leak straight into the rendered card. Flattening
 * unconditionally, for every child, fixes it regardless of shape.
 */
function flattenParagraphs(children: ReactNode): ReactNode[] {
  const out: ReactNode[] = [];

  React.Children.forEach(children, (child) => {
    if (isParagraphElement(child)) {
      out.push(...flattenParagraphs(child.props.children));
    } else {
      out.push(child);
    }
  });

  return out;
}

export function parseFlowChildren(children: ReactNode, path: number[] = []): FlowNodeDatum[] {
  const items: FlowNodeDatum[] = [];
  let localIndex = 0;

  React.Children.forEach(children, (child) => {
    if (!React.isValidElement(child)) return;

    // Allow authors to group items in a Fragment without breaking parsing.
    if (child.type === React.Fragment) {
      items.push(...parseFlowChildren((child.props as { children?: ReactNode }).children, path));
      return;
    }

    if (child.type !== FlowItem) return;

    const currentPath = [...path, localIndex];
    localIndex += 1;

    const props = child.props as { children?: ReactNode };
    const flowChildren = flattenParagraphs(props.children);

    const contentNodes: ReactNode[] = [];
    const nestedChildrenSource: ReactNode[] = [];

    flowChildren.forEach((grandChild) => {
      const isNested =
        React.isValidElement(grandChild) &&
        (grandChild.type === FlowItem ||
          (grandChild.type === React.Fragment &&
            containsFlowItem((grandChild.props as { children?: ReactNode }).children)));

      if (isNested) {
        nestedChildrenSource.push(grandChild);
      } else {
        contentNodes.push(grandChild);
      }
    });

    const id = child.key != null ? String(child.key) : `n-${currentPath.join("-")}`;

    items.push({
      id,
      content: React.createElement(React.Fragment, null, ...contentNodes),
      children: parseFlowChildren(nestedChildrenSource, currentPath),
    });
  });

  return items;
}
