import Link from "next/link";
import { SITE_NAME, SITE_URL } from "~/utils/domain";
import "./A.css";
import { pushClientPath } from "~/features/learning/lib/remote";

interface AProps {
  link: string;
  children?: React.ReactNode;
}

const A = ({ link, children }: AProps) => {
  const isInternal = link.startsWith("/") || link.startsWith("#") || link.startsWith(SITE_URL);

  if (isInternal) {
    return (
      <Link
        className="anchor"
        href={link}
        onClick={(event) => {
          event.preventDefault();
          pushClientPath(link);
        }}
      >
        {children || link}
      </Link>
    );
  }

  const href = `${link}${link.includes("?") ? "&" : "?"}utm_source=${SITE_NAME.toLowerCase()}`;

  return (
    <a className="anchor" href={href} target="_blank" rel="noopener noreferrer">
      {children || link}
    </a>
  );
};

export default A;
