"use client";

import { createContext, useContext } from "react";

/**
 * Internal context shared between Tabs, TabList, Tab, and TabPanel.
 * Not part of the public API — consumers should never import this directly.
 */
export interface TabsContextValue {
  /** Currently selected tab/panel index (0-based). */
  selectedIndex: number;
  /** Selects a tab by index. Called by Tab on click/Enter/Space. */
  onSelectTab: (index: number, event: React.SyntheticEvent) => void;
  /** When true, all TabPanels render their content regardless of selection. */
  forceRenderTabPanel: boolean;
  /** Stable prefix (from useId) used to build deterministic, SSR-safe ids. */
  idPrefix: string;
  /** Default class applied to the selected Tab, overridable per-Tab. */
  selectedTabClassName: string;
  /** Default class applied to the selected TabPanel, overridable per-TabPanel. */
  selectedTabPanelClassName: string;
  /** Default class applied to a disabled Tab, overridable per-Tab. */
  disabledClassName: string;
}

export const TabsContext = createContext<TabsContextValue | null>(null);

TabsContext.displayName = "TabsContext";

/**
 * Safe accessor for the Tabs context. Throws a descriptive error if a
 * consumer (Tab / TabList / TabPanel) is rendered outside of <Tabs>.
 */
export function useTabsContext(componentName: string): TabsContextValue {
  const context = useContext(TabsContext);

  if (context === null) {
    throw new Error(`<${componentName} /> must be rendered inside a <Tabs> component.`);
  }

  return context;
}
