const KIND_ICON_MAP: Record<FileIconKind, (props: IconProps) => ReactElement> = {
  code: CodeGlyph,
  data: DataGlyph,
  doc: DocGlyph,
  style: StyleGlyph,
  markup: MarkupGlyph,
  image: ImageGlyph,
  generic: GenericFileGlyph,
};

/**
 * The color a given icon kind renders in. `doc` (markdown/mdx) and folders
 * get the full accent color, since documentation content is this tree's
 * primary subject; every other file kind uses the muted default text color
 * so the accent stays reserved for the content that matters most.
 */
const KIND_TONE_MAP: Record<FileIconKind, string> = {
  code: "color-mix(in srgb, var(--accent-color) 65%, var(--text-color) 35%)",
  data: "color-mix(in srgb, var(--accent-color) 65%, var(--text-color) 35%)",
  doc: "var(--accent-color)",
  style: "var(--text-faint)",
  markup: "var(--text-faint)",
  image: "var(--text-faint)",
  generic: "var(--text-faint)",
};

export function FileIcon({ kind, ...props }: IconProps & { kind: FileIconKind }) {
  const Glyph = KIND_ICON_MAP[kind];
  return <Glyph color={KIND_TONE_MAP[kind]} {...props} />;
}
