import "./Loading.css";

const Loading = () => {
  return (
    <section
      className="app-section loading-container"
      role="status"
      aria-label="Loading course"
      aria-busy="true"
    >
      <div className="loading-content">
        <h2>Pinktra</h2>
        <p>Preparing your experience...</p>
        <div className="loading-dots">
          <span></span>
          <span></span>
          <span></span>
        </div>
      </div>
    </section>
  );
};

export default Loading;
