import React from "react";
import A from "../A/A";
import "./Note.css";

export type NoteType =
  | "note"
  | "tip"
  | "info"
  | "important"
  | "warning"
  | "danger"
  | "error"
  | "success"
  | "caution"
  | "hint"
  | "example"
  | "question"
  | "answer"
  | "remember"
  | "summary"
  | "best-practice"
  | "reference"
  | "todo";

interface NoteProps {
  children?: React.ReactNode;
  link?: string;
  type?: NoteType;
}

const NOTE_META: Record<
  NoteType,
  {
    title: string;
    icon: string;
  }
> = {
  note: {
    title: "Note",
    icon: "📝",
  },
  tip: {
    title: "Tip",
    icon: "💡",
  },
  info: {
    title: "Information",
    icon: "ℹ️",
  },
  important: {
    title: "Important",
    icon: "❗",
  },
  warning: {
    title: "Warning",
    icon: "⚠️",
  },
  danger: {
    title: "Danger",
    icon: "🚫",
  },
  error: {
    title: "Error",
    icon: "❌",
  },
  success: {
    title: "Success",
    icon: "✅",
  },
  caution: {
    title: "Caution",
    icon: "🟡",
  },
  hint: {
    title: "Hint",
    icon: "🔍",
  },
  example: {
    title: "Example",
    icon: "📖",
  },
  question: {
    title: "Question",
    icon: "❓",
  },
  answer: {
    title: "Answer",
    icon: "💬",
  },
  remember: {
    title: "Remember",
    icon: "🧠",
  },
  summary: {
    title: "Summary",
    icon: "📋",
  },
  "best-practice": {
    title: "Best Practice",
    icon: "⭐",
  },
  reference: {
    title: "Reference",
    icon: "🔗",
  },
  todo: {
    title: "To Do",
    icon: "☑️",
  },
};

const Note = ({ children, link, type = "note" }: NoteProps) => {
  if (children && link) {
    throw new Error("Note component cannot have both 'children' and 'link' props.");
  }

  const meta = NOTE_META[type] ?? NOTE_META.note;
  const { title, icon } = meta;

  return (
    <div className={`note-container note-${type}`}>
      <h3 className="note-title">
        <span className="note-icon" aria-hidden="true">
          {icon}
        </span>
        {title}
      </h3>

      <div className="notes">
        {link ? (
          <>
            Further details can be found at: <A link={link}>{link}</A>
          </>
        ) : (
          children
        )}
      </div>
    </div>
  );
};

export default Note;
