"use client";

import { usePathname } from "next/navigation";
import { useCallback, useEffect, useRef, useState } from "react";
import { createSlug } from "~/utils/slug";

export interface TOCItem {
  id: string;
  text: string;
  level: number;
  element: HTMLElement;
  children: TOCItem[];
}

type FlatHeading = Omit<TOCItem, "children">;

const HEADING_SELECTOR = ".heading-1, .heading-2, .heading-3, .heading-4";
// Below this scroll offset we treat the reader as "at the top" and keep the URL clean
const TOP_THRESHOLD = 80;
// If no headings show up within this window, assume the page has none and collapse the TOC
const EMPTY_GRACE_MS = 1200;

function slugify(text: string, usedIds: Set<string>): string {
  const slug = createSlug(text, { fallback: "heading" });

  let unique = slug;
  let counter = 1;
  while (usedIds.has(unique)) {
    unique = `${slug}-${counter++}`;
  }
  usedIds.add(unique);
  return unique;
}

function buildTree(flat: FlatHeading[]): TOCItem[] {
  const root: TOCItem[] = [];
  const stack: TOCItem[] = [];

  for (const item of flat) {
    const node: TOCItem = { ...item, children: [] };
    while (stack.length > 0 && stack[stack.length - 1].level >= item.level) {
      stack.pop();
    }
    if (stack.length === 0) {
      root.push(node);
    } else {
      stack[stack.length - 1].children.push(node);
    }
    stack.push(node);
  }

  return root;
}

function sameHeadings(a: FlatHeading[], b: FlatHeading[]): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (
      a[i].element !== b[i].element ||
      a[i].id !== b[i].id ||
      a[i].text !== b[i].text ||
      a[i].level !== b[i].level
    ) {
      return false;
    }
  }
  return true;
}

// Replace the URL hash while preserving Next.js' internal history state.
// Wrapped in try/catch: Safari throws if replaceState is called too frequently.
function replaceHash(id: string | null) {
  try {
    const url = `${location.pathname}${location.search}${id ? `#${id}` : ""}`;
    history.replaceState(history.state, "", url);
  } catch {
    // ignore – the URL hash is a nicety, not critical
  }
}

export function useTOC(contentRef: React.RefObject<HTMLElement | null>) {
  const pathname = usePathname();

  const [items, setItems] = useState<TOCItem[]>([]);
  const [activeId, setActiveId] = useState<string>("");
  // true on the server too, so the TOC space is reserved from the very first render
  const [isLoading, setIsLoading] = useState(true);

  const observerRef = useRef<IntersectionObserver | null>(null);
  const mutationRef = useRef<MutationObserver | null>(null);
  const rafRef = useRef<number | null>(null);
  const activeIdRef = useRef<string>("");
  const headingsRef = useRef<FlatHeading[]>([]);
  const visibleRef = useRef(new Set<HTMLElement>());
  // Last hash this hook wrote, so we only ever clear hashes we created
  const writtenHashRef = useRef<string>("");

  const clearObserver = useCallback(() => {
    observerRef.current?.disconnect();
    observerRef.current = null;
    visibleRef.current.clear();
  }, []);

  const setActive = useCallback((id: string) => {
    activeIdRef.current = id;
    setActiveId(id);
  }, []);

  const scanHeadings = useCallback(() => {
    const container = contentRef.current;
    if (!container) return;

    const scanPath = location.pathname;

    const elements = Array.from(container.querySelectorAll<HTMLElement>(HEADING_SELECTOR)).filter(
      (el) => {
        const text = el.textContent?.trim() ?? "";
        if (!text || text.includes("Loading...")) return false;

        const panel = el.closest(".react-tabs__tab-panel");
        // Heading outside tabs, or inside the active tab panel
        return !panel || panel.classList.contains("react-tabs__tab-panel--selected");
      },
    );

    // Nothing to show: clear everything (no-op re-render if already empty).
    // isLoading is NOT touched here; the grace timer decides when to give up.
    if (elements.length === 0) {
      clearObserver();
      headingsRef.current = [];
      setItems((prev) => (prev.length === 0 ? prev : []));
      if (activeIdRef.current) setActive("");
      return;
    }

    // Real headings exist: loading is finished
    setIsLoading(false);

    // Reserve ids the app set itself (not generated by this hook)
    const usedIds = new Set<string>();
    elements.forEach((el) => {
      if (el.id && el.dataset.tocAuto !== "true") usedIds.add(el.id);
    });

    const flat: FlatHeading[] = elements.map((el) => {
      const dataLevel = el.getAttribute("data-toc-level");
      const level = dataLevel ? parseInt(dataLevel, 10) : parseInt(el.tagName.slice(1), 10);
      const text = el.textContent?.trim() ?? "";

      // Regenerate ids we created before: React reuses heading DOM nodes across
      // pages, so an old auto id would otherwise survive the navigation.
      if (!el.id || el.dataset.tocAuto === "true") {
        el.id = slugify(text, usedIds);
        el.dataset.tocAuto = "true";
      }

      return { id: el.id, text, level, element: el };
    });

    // Nothing changed (e.g. unrelated class toggles): skip rebuild entirely
    if (observerRef.current && sameHeadings(headingsRef.current, flat)) return;

    headingsRef.current = flat;
    setItems(buildTree(flat));

    // Drop an active id that no longer exists on this page
    if (activeIdRef.current && !flat.some((h) => h.id === activeIdRef.current)) {
      setActive("");
    }

    clearObserver();

    const observer = new IntersectionObserver(
      (entries) => {
        // Ignore callbacks that belong to a previous page
        if (location.pathname !== scanPath) return;

        const visible = visibleRef.current;
        for (const entry of entries) {
          if (entry.isIntersecting) visible.add(entry.target as HTMLElement);
          else visible.delete(entry.target as HTMLElement);
        }

        if (visible.size === 0) return;

        let current: HTMLElement | null = null;
        let minTop = Infinity;
        visible.forEach((el) => {
          const top = el.getBoundingClientRect().top;
          if (top < minTop) {
            minTop = top;
            current = el;
          }
        });

        const newId = (current as HTMLElement | null)?.id;
        if (!newId || newId === activeIdRef.current) return;

        setActive(newId);

        if (window.scrollY < TOP_THRESHOLD) {
          // At the top of the page: don't pin the first heading in the URL
          if (writtenHashRef.current && location.hash === `#${writtenHashRef.current}`) {
            replaceHash(null);
            writtenHashRef.current = "";
          }
        } else if (location.hash !== `#${newId}`) {
          replaceHash(newId);
          writtenHashRef.current = newId;
        }
      },
      { rootMargin: "-8% 0px -80% 0px", threshold: 0 },
    );

    observerRef.current = observer;
    flat.forEach(({ element }) => observer.observe(element));

    // Only trust the URL hash if that heading exists on this page
    const hashId = decodeURIComponent(location.hash.slice(1));
    if (hashId && flat.some((h) => h.id === hashId)) {
      setActive(hashId);
    }
  }, [contentRef, clearObserver, setActive]);

  // Coalesce bursts of DOM mutations into one scan, after layout has settled
  const scheduleScan = useCallback(() => {
    if (rafRef.current !== null) cancelAnimationFrame(rafRef.current);

    rafRef.current = requestAnimationFrame(() => {
      rafRef.current = requestAnimationFrame(() => {
        rafRef.current = null;
        scanHeadings();
      });
    });
  }, [scanHeadings]);

  // Re-arm the loading state on every page change. If no headings arrive
  // within the grace window, assume the page has none and collapse the TOC.
  useEffect(() => {
    setIsLoading(true);
    const timer = setTimeout(() => setIsLoading(false), EMPTY_GRACE_MS);
    return () => clearTimeout(timer);
  }, [pathname]);

  // Initial scan + MutationObserver for lazy content, page changes and tab switches
  useEffect(() => {
    const visible = visibleRef.current;

    scheduleScan();

    const container = contentRef.current;
    if (container) {
      const mutation = new MutationObserver(scheduleScan);
      mutation.observe(container, {
        childList: true,
        subtree: true,
        attributes: true,
        attributeFilter: ["class"],
      });
      mutationRef.current = mutation;
    }

    return () => {
      mutationRef.current?.disconnect();
      mutationRef.current = null;
      observerRef.current?.disconnect();
      observerRef.current = null;
      if (rafRef.current !== null) {
        cancelAnimationFrame(rafRef.current);
        rafRef.current = null;
      }
      visible.clear();
    };
  }, [scheduleScan, contentRef]);

  return { items, activeId, isLoading };
}

export function getAncestorIds(items: TOCItem[], targetId: string): Set<string> {
  const result = new Set<string>();

  function search(nodes: TOCItem[], path: string[]): boolean {
    for (const node of nodes) {
      if (node.id === targetId) {
        path.forEach((id) => result.add(id));
        return true;
      }
      if (search(node.children, [...path, node.id])) return true;
    }
    return false;
  }

  search(items, []);
  return result;
}
