import React from "react";

import A from "../A/A";
import List from "../List/List";
import styles from "./Para.module.css";

interface ParaProps {
  children?: React.ReactNode;
  link?: string | string[];
  tab?: boolean;
  bold?: boolean;
  italic?: boolean;
  underline?: boolean;
  strikethrough?: boolean;
  code?: boolean;
  align?: "justify" | "left" | "center" | "right";
}

const Para: React.FC<ParaProps> = ({
  children,
  link,
  tab = false,
  bold = false,
  italic = false,
  underline = false,
  strikethrough = false,
  code = false,
  align = "justify",
}) => {
  const classNames = [
    styles.para,
    tab && styles.tabbed,
    bold && styles.bold,
    italic && styles.italic,
    underline && styles.underline,
    strikethrough && styles.strikethrough,
    code && styles.codeStyle,
    align === "justify" && styles.justify,
    align === "center" && styles.center,
    align === "right" && styles.right,
    align === "left" && styles.left,
  ]
    .filter(Boolean)
    .join(" ");

  if (children && link) {
    throw new Error("Para component cannot have both 'children' and 'link' props.");
  }

  const renderLinks = () => {
    if (!link) return null;

    const links = typeof link === "string" ? [link] : link;

    if (links.length === 1) {
      return (
        <>
          Further details can be found at: <A link={links[0]}>{links[0]}</A>
        </>
      );
    }

    return (
      <>
        Further details can be found at:
        <List>
          {links.map((l, i) => (
            <List.Item key={l || i}>
              <A link={l}>{l}</A>
            </List.Item>
          ))}
        </List>
      </>
    );
  };

  return <p className={classNames}>{link ? renderLinks() : children}</p>;
};

export { Para as P };

export default Para;
