import { hierarchy as d3hierarchy, tree as d3tree, type HierarchyPointNode } from "d3-hierarchy";
import type {
  FlowLayout,
  FlowNodeDatum,
  LayoutOptions,
  LayoutResult,
  MeasuredSize,
  PositionedLink,
  PositionedNode,
} from "./Flow.types";

/**
 * DOM-measurement-dependent layout math. This is only ever meaningful once
 * real card sizes have been measured in the browser, so it's imported
 * exclusively by FlowClient.tsx (the client boundary). It has no JSX
 * parsing responsibilities and no dependency on <Flow.Item>/<FlowItem>.
 */

/** Fallback size used before a node has been measured (keeps SSR output deterministic). */
export const DEFAULT_SIZE: MeasuredSize = { width: 180, height: 56 };

/**
 * Computes a balanced, non-overlapping tree layout using d3-hierarchy.
 *
 * We rely on d3's Reingold-Tilford implementation (`tree()`) purely for
 * ordering nodes and centering parents over their children. Because cards
 * have variable, content-driven sizes, we don't use d3's own nodeSize
 * scaling for the "cross" axis. Instead we set nodeSize to a unit value
 * and provide a `separation()` function that returns the exact pixel
 * distance that should exist between two adjacent node centers (based on
 * their measured half-widths/half-heights plus a gap). Because a unit
 * nodeSize multiplies the accumulated separation by 1, the x value tree()
 * produces is already the correct pixel position along the cross axis.
 *
 * The "main" axis (the direction the hierarchy grows in) is computed
 * separately as the cumulative size of each generation, so that rows
 * (vertical layout) or columns (horizontal layout) are only as large as
 * their tallest/widest card.
 */
export function computeLayout(
  root: FlowNodeDatum,
  sizes: Map<string, MeasuredSize>,
  layout: FlowLayout,
  options: LayoutOptions,
): LayoutResult {
  const { levelGap, siblingGap } = options;

  const sizeOf = (id: string): MeasuredSize => sizes.get(id) ?? DEFAULT_SIZE;

  const crossSizeOf = (id: string) =>
    layout === "vertical" ? sizeOf(id).width : sizeOf(id).height;
  const mainSizeOf = (id: string) => (layout === "vertical" ? sizeOf(id).height : sizeOf(id).width);

  const hierarchyRoot = d3hierarchy<FlowNodeDatum>(root, (d) => d.children);

  const treeLayout = d3tree<FlowNodeDatum>()
    .nodeSize([1, 1])
    .separation((a, b) => {
      const halfA = crossSizeOf(a.data.id) / 2;
      const halfB = crossSizeOf(b.data.id) / 2;
      // extra breathing room when nodes don't share a parent
      const extra = a.parent === b.parent ? siblingGap : siblingGap * 1.5;
      return halfA + halfB + extra;
    });

  const points = treeLayout(hierarchyRoot) as HierarchyPointNode<FlowNodeDatum>;
  const descendants = points.descendants();

  // Max size per generation, used to size each row/column of the main axis.
  // NOTE: a depth that contains only the synthetic virtual root (i.e. no
  // real, rendered nodes) intentionally gets NO entry here.
  const maxByDepth = new Map<number, number>();
  descendants.forEach((n) => {
    if (n.data.isVirtual) return;
    const s = mainSizeOf(n.data.id);
    maxByDepth.set(n.depth, Math.max(maxByDepth.get(n.depth) ?? 0, s));
  });

  // Cumulative offset of each generation along the main axis.
  //
  // IMPORTANT: the virtual root that `buildRoot()` inserts for multiple
  // top-level items occupies depth 0 but is never rendered and has no
  // size. It must not consume a `levelGap` of space — otherwise every
  // real generation is pushed down/right by one extra `levelGap`, and
  // that same phantom gap leaks into the final canvas width/height.
  // We only advance `running` by `size + levelGap` for depths that
  // actually contain a real (measured) node.
  const mainOffsetByDepth = new Map<number, number>();
  let running = 0;
  const maxDepth = Math.max(0, ...Array.from(maxByDepth.keys()));
  for (let d = 0; d <= maxDepth; d += 1) {
    mainOffsetByDepth.set(d, running);
    if (maxByDepth.has(d)) {
      running += (maxByDepth.get(d) ?? 0) + levelGap;
    }
  }

  // Determine cross-axis bounds so we can shift everything into positive space.
  let minCross = Infinity;
  let maxCross = -Infinity;
  descendants.forEach((n) => {
    if (n.data.isVirtual) return;
    const half = crossSizeOf(n.data.id) / 2;
    minCross = Math.min(minCross, n.x - half);
    maxCross = Math.max(maxCross, n.x + half);
  });
  if (!Number.isFinite(minCross)) {
    minCross = 0;
    maxCross = 0;
  }
  const crossShift = -minCross;

  const positioned: PositionedNode[] = [];

  descendants.forEach((n) => {
    if (n.data.isVirtual) return;
    const { width, height } = sizeOf(n.data.id);
    const crossCenter = n.x + crossShift;
    const mainStart = mainOffsetByDepth.get(n.depth) ?? 0;

    const x = layout === "vertical" ? crossCenter - width / 2 : mainStart;
    const y = layout === "vertical" ? mainStart : crossCenter - height / 2;

    positioned.push({
      id: n.data.id,
      content: n.data.content,
      x,
      y,
      width,
      height,
      depth: n.depth - (root.isVirtual ? 1 : 0),
      parentId: n.parent && !n.parent.data.isVirtual ? n.parent.data.id : null,
      isVirtual: false,
    });
  });

  const byIdPositioned = new Map(positioned.map((p) => [p.id, p]));
  const links: PositionedLink[] = [];
  descendants.forEach((n) => {
    if (!n.parent || n.data.isVirtual || n.parent.data.isVirtual) return;
    const parent = byIdPositioned.get(n.parent.data.id);
    const child = byIdPositioned.get(n.data.id);
    if (!parent || !child) return;
    links.push({
      id: `${parent.id}->${child.id}`,
      sourceId: parent.id,
      targetId: child.id,
      d: buildConnectorPath(parent, child, layout),
    });
  });

  // `running` now only ever accrued a trailing levelGap after the LAST
  // real depth (phantom depths, like the virtual root's, add nothing),
  // so subtracting one levelGap here is correct and symmetric with the
  // single-root case.
  const width = layout === "vertical" ? maxCross - minCross : running - levelGap;
  const height = layout === "vertical" ? running - levelGap : maxCross - minCross;

  return {
    nodes: positioned,
    links,
    width: Math.max(0, width),
    height: Math.max(0, height),
  };
}

function buildConnectorPath(
  parent: PositionedNode,
  child: PositionedNode,
  layout: FlowLayout,
): string {
  if (layout === "vertical") {
    const sx = parent.x + parent.width / 2;
    const sy = parent.y + parent.height;
    const tx = child.x + child.width / 2;
    const ty = child.y;
    const midY = (sy + ty) / 2;
    return `M ${sx} ${sy} C ${sx} ${midY}, ${tx} ${midY}, ${tx} ${ty}`;
  }
  const sx = parent.x + parent.width;
  const sy = parent.y + parent.height / 2;
  const tx = child.x;
  const ty = child.y + child.height / 2;
  const midX = (sx + tx) / 2;
  return `M ${sx} ${sy} C ${midX} ${sy}, ${midX} ${ty}, ${tx} ${ty}`;
}
