"use client";

import { use } from "react";
import katex from "katex";
import "katex/dist/katex.min.css";
import "./Maths.css";

interface MathsInnerProps {
  formula: string | Promise<string>;
  type?: "inline" | "block";
}

export default function MathsInner({ formula, type = "block" }: MathsInnerProps) {
  const latex = typeof formula === "string" ? formula : use(formula);

  const html = katex.renderToString(latex.trim(), {
    displayMode: type === "block",
    throwOnError: false,
    output: "html",
  });

  return (
    <span className={`wf-maths wf-maths--${type}`} dangerouslySetInnerHTML={{ __html: html }} />
  );
}
