"use client";

import type { ReactNode } from "react";
import H1 from "~/ui/H1/H1";
import H2 from "~/ui/H2/H2";
import H3 from "~/ui/H3/H3";
import Media from "~/ui/Media/Media";
import { Tab, TabList, TabPanel, Tabs } from "~/ui/Tabs/Tabs";
import Title from "~/ui/Title/Title";
import { resolveRemoteUrl } from "../lib/remote";
import type {
  CourseMetadata,
  FolderItem,
  PageBuilderOptions,
  TopicEntry,
} from "../lib/types";
import RemoteFile, { type RemoteFileOptions } from "./RemoteFile";

interface PageBuilderContentProps {
  structure: CourseMetadata;
  topic: TopicEntry | null;
  docsUrl: string;
  options?: PageBuilderOptions;
}

const headings = [Title, H1, H2, H3] as const;

function isMarkdownFile(file: string) {
  const extension = file.split("?")[0].split(".").pop()?.toLowerCase();
  return extension === "md" || extension === "mdx";
}

function renderFolderFiles(
  folder: FolderItem,
  docsUrl: string,
  options: RemoteFileOptions,
): ReactNode {
  const files = folder.files ?? [];
  const mediaFiles = files.filter((file) => !isMarkdownFile(file));
  const firstMediaIndex = files.findIndex((file) => !isMarkdownFile(file));

  return files.map((file, index) => {
    if (isMarkdownFile(file)) {
      return <RemoteFile key={file} file={file} docsUrl={docsUrl} {...options} />;
    }

    if (index !== firstMediaIndex) {
      return null;
    }

    return (
      <Media
        key={`media-${file}`}
        src={mediaFiles.map((mediaFile) => resolveRemoteUrl(docsUrl, mediaFile))}
        {...options}
      />
    );
  });
}

function renderFolder(
  folder: FolderItem,
  level: number,
  docsUrl: string,
  options: RemoteFileOptions,
): ReactNode {
  const HeadingTag = headings[Math.min(Math.max(level - 1, 0), headings.length - 1)];

  return (
    <>
      <HeadingTag>{folder.name}</HeadingTag>
      {renderFolderFiles(folder, docsUrl, options)}
      {folder.folders?.map((sub) => (
        <div key={sub.name}>{renderFolder(sub, level + 1, docsUrl, options)}</div>
      ))}
    </>
  );
}

function renderTabbedFolder(
  folder: FolderItem,
  level: number,
  docsUrl: string,
  options: RemoteFileOptions,
): ReactNode {
  const folders = folder.folders ?? [];

  return (
    <>
      <Tabs>
        <TabList>
          {folders.map((sub) => (
            <Tab key={sub.name}>{sub.name}</Tab>
          ))}
        </TabList>
        {folders.map((sub) => (
          <TabPanel key={sub.name}>{renderFolder(sub, level, docsUrl, options)}</TabPanel>
        ))}
      </Tabs>
      {renderFolderFiles(folder, docsUrl, options)}
    </>
  );
}

function renderSinglePage(
  structure: CourseMetadata,
  docsUrl: string,
  options: RemoteFileOptions & { tabs?: boolean },
): ReactNode {
  if (options.tabs) {
    return (
      <Tabs>
        <TabList>
          {structure.map((folder) => (
            <Tab key={folder.name}>{folder.name}</Tab>
          ))}
        </TabList>
        {structure.map((folder) => (
          <TabPanel key={folder.name}>
            {folder.folders?.map((sub) => (
              <div key={sub.name}>{renderFolder(sub, 2, docsUrl, options)}</div>
            ))}
            {renderFolderFiles(folder, docsUrl, options)}
          </TabPanel>
        ))}
      </Tabs>
    );
  }

  return structure.map((folder) => (
    <div key={folder.name}>{renderFolder(folder, 2, docsUrl, options)}</div>
  ));
}

function renderTopic(
  topic: TopicEntry,
  docsUrl: string,
  options: RemoteFileOptions & { tabs?: boolean },
): ReactNode {
  if (topic.mode === "tabs") {
    return renderTabbedFolder(topic.folder, 1, docsUrl, options);
  }

  if (topic.mode === "heading" && options.tabs && topic.folder.folders?.length) {
    return renderTabbedFolder(topic.folder, 1, docsUrl, options);
  }

  return renderFolder(topic.folder, 1, docsUrl, options);
}

export default function PageBuilderContent({
  structure,
  topic,
  docsUrl,
  options = {},
}: PageBuilderContentProps) {
  const renderOptions: RemoteFileOptions & { tabs?: boolean } = {
    groupImg: options.groupImg,
    movie: options.movie,
    tableTextAlign: options.tableTextAlign,
    tableTextWrap: options.tableTextWrap,
    tabs: options.tabs,
  };

  if (options.singlePage) {
    return <>{renderSinglePage(structure, docsUrl, { ...renderOptions, tabs: options.tabs })}</>;
  }

  return topic ? <>{renderTopic(topic, docsUrl, renderOptions)}</> : null;
}