"use client";

import { use } from "react";

import type { SyntaxData } from "./syntaxResource";
import SyntaxActions from "./SyntaxAction";

interface SyntaxInnerProps {
  title: string;
  dataPromise: Promise<SyntaxData>;
}

export default function SyntaxInner({ title, dataPromise }: SyntaxInnerProps) {
  const { code, html, css } = use(dataPromise);

  if (!code) {
    return null;
  }

  return (
    <div className="syntax-container">
      <div className="syntax-header">
        <h3>{title}</h3>

        <SyntaxActions title={title} code={code} />
      </div>

      {css && <style dangerouslySetInnerHTML={{ __html: css }} />}

      <div
        className="syntax-highlighter"
        dangerouslySetInnerHTML={{
          __html: html,
        }}
      />
    </div>
  );
}
