export const getExtension = (url: string): string => {
  try {
    const clean = url.split(/[?#]/)[0];
    return clean.slice(((clean.lastIndexOf(".") - 1) >>> 0) + 2).toLowerCase();
  } catch {
    return "";
  }
};

export const hasExtension = (file: string, extensions: string | string[]): boolean => {
  const ext = getExtension(file);
  const exts = Array.isArray(extensions) ? extensions : [extensions];

  return exts.includes(ext);
};

export const getType = (file: string): string => {
  try {
    const clean = file.split(/[?#]/)[0];
    const parts = clean.split(".");

    // Need at least: name.type.ext
    if (parts.length < 3) return "";

    return parts[parts.length - 2].toLowerCase();
  } catch {
    return "";
  }
};

export const isYouTubeLink = (url: string) =>
  /(youtube\.com\/(watch\?v=|shorts\/|live\/)|youtu\.be\/)/.test(url);

export const isAudio = (file: string) => hasExtension(file, ["mp3", "wav", "ogg"]);

export const isVideo = (file: string) =>
  hasExtension(file, ["mp4", "webm", "ogg"]) && !isAudio(file);

export const isSvg = (file: string) => hasExtension(file, "svg");

export const isTldr = (file: string) => hasExtension(file, "tldr");

export const isImage = (file: string) =>
  hasExtension(file, ["jpg", "jpeg", "png", "gif", "webp", "avif"]);

export const isMarkdown = (file: string) => hasExtension(file, ["md", "mdx"]);

export const isExcel = (file: string) => hasExtension(file, ["xlsx", "xls"]);

export const isCsv = (file: string) => hasExtension(file, "csv");

export const isPdf = (file: string) => hasExtension(file, "pdf");

export const isJson = (file: string) => hasExtension(file, "json");

export const isLanguageJson = (file: string) =>
  hasExtension(file, "json") && getType(file) === "lang";

export const isSyntax = (file: string) => hasExtension(file, "syntax");

export const isTex = (file: string) => hasExtension(file, "tex");
