"use client";

import RotateRightIcon from "@mui/icons-material/RotateRight";
import ZoomInIcon from "@mui/icons-material/ZoomIn";
import ZoomOutIcon from "@mui/icons-material/ZoomOut";
import IconButton from "@mui/material/IconButton";
import clsx from "clsx";
import React from "react";
import { PhotoProvider, PhotoView } from "react-photo-view";
import "react-photo-view/dist/react-photo-view.css";

/**
 * ImageViewerProvider
 * --------------------
 * Thin client wrapper around react-photo-view's <PhotoProvider>.
 *
 * Because this is a Client Component, its `children` prop can still be
 * arbitrary Server-Component-rendered JSX — React lets a Server Component
 * render a Client Component and pass server output through as `children`.
 * That's what makes it possible for Media.tsx (a Server Component) to wrap
 * server-rendered video/audio/pdf/markdown/etc. output in this provider
 * without those types becoming client code themselves.
 *
 * Only the actual <ImageThumb> leaves (below) are interactive/client.
 */
interface ImageViewerProviderProps {
  children: React.ReactNode;
}

export const ImageViewerProvider: React.FC<ImageViewerProviderProps> = ({ children }) => {
  return (
    <PhotoProvider
      toolbarRender={({ rotate, scale, onScale, onRotate }) => (
        <>
          <IconButton
            onClick={() => onRotate(rotate + 90)}
            style={{ color: "white" }}
            className="PhotoView-Slider__toolbarIcon"
          >
            <RotateRightIcon />
          </IconButton>
          <IconButton
            onClick={() => onScale(scale + 0.2)}
            style={{ color: "white" }}
            className="PhotoView-Slider__toolbarIcon"
          >
            <ZoomInIcon />
          </IconButton>
          <IconButton
            onClick={() => onScale(scale - 0.2)}
            style={{ color: "white" }}
            className="PhotoView-Slider__toolbarIcon"
          >
            <ZoomOutIcon />
          </IconButton>
        </>
      )}
    >
      {children}
    </PhotoProvider>
  );
};

/**
 * ImageThumb
 * ----------
 * The interactive image thumbnail + lightbox trigger. Must be rendered
 * somewhere inside an <ImageViewerProvider> tree (any number of levels deep,
 * interspersed with server-rendered siblings) for the lightbox/gallery
 * navigation to work across all images on the page.
 */
interface ImageThumbProps {
  src: string;
  alt?: string;
  movie?: boolean;
  group?: boolean;
}

export const ImageThumb: React.FC<ImageThumbProps> = ({
  src,
  alt = "Media content",
  movie = false,
  group = false,
}) => {
  return (
    <div className="media-wrapper image-wrapper" style={{ maxHeight: group ? 300 : undefined }}>
      <PhotoView src={src}>
        <img src={src} alt={alt} loading="lazy" className={clsx(movie && "movie")} />
      </PhotoView>
    </div>
  );
};
