import clsx from "clsx";
import React from "react";
import { IMAGE_DOMAIN } from "~/utils/domain";
import {
  getType,
  isAudio,
  isCsv,
  isExcel,
  isImage,
  isLanguageJson,
  isPdf,
  isSvg,
  isSyntax,
  isTex,
  isTldr,
  isVideo,
  isYouTubeLink,
} from "~/utils/file_type";
import { normalizeUrl } from "~/utils/url";

import Lang from "../Lang/Lang";
import Maths from "../Maths/Maths";
import Para from "../Para/Para";
import PDF from "../PDF/PDF";
import { type Language, LANGUAGE } from "../Syntax/Language";
import Syntax from "../Syntax/Syntax";
import type { tableTextAlign, tableTextWrap } from "../Table/Table";
import Table from "../Table/Table";
import { Tab, TabList, TabPanel, Tabs } from "../Tabs/Tabs";
import { ImageThumb, ImageViewerProvider } from "./ImageViewer";
import "./Media.scss";
import Svg from "./Svg";

interface SequenceConfig {
  base: string;
  start: number;
  end: number;
  ext?: string;
  leadingZeros?: number;
  pattern?: string;
}

type MediaEntry = string | { sequence: SequenceConfig };

type MediaType =
  | "auto"
  | "svg"
  | "img"
  | "video"
  | "audio"
  | "youtube"
  | "markdown"
  | "table"
  | "pdf"
  | "lang"
  | "syntax"
  | "tex";

interface MediaProps {
  poster?: string;
  src?: string | string[];
  sequence?: SequenceConfig | SequenceConfig[];
  media?: MediaEntry[];
  alt?: string;
  domain?: string;
  sort?: boolean;
  responsive?: boolean;
  groupImg?: boolean;
  movie?: boolean;
  type?: MediaType;
  presentation?: boolean;
  mode?: "light" | "dark";
  tableTextAlign?: tableTextAlign;
  tableTextWrap?: tableTextWrap;
}

const padNumber = (num: number, width: number): string => num.toString().padStart(width, "0");

const generateSequenceUrls = (config: SequenceConfig, base?: string): string[] => {
  const { base: seqBase, start, end, ext = "png", leadingZeros = 0, pattern } = config;

  const list: string[] = [];

  for (let i = start; i <= end; i++) {
    const n = leadingZeros > 0 ? padNumber(i, leadingZeros) : i.toString();
    const filename = pattern ? pattern.replace("${n}", n) : `${n}.${ext}`;
    list.push(normalizeUrl(`${seqBase}${filename}`, base));
  }

  return list;
};

const getYouTubeEmbedUrl = (url: string) => {
  try {
    let videoId = "";

    if (url.includes("watch?v=")) {
      videoId = url.split("watch?v=")[1]?.split(/[&#]/)[0];
    } else if (url.includes("youtu.be/")) {
      videoId = url.split("youtu.be/")[1]?.split(/[?#]/)[0];
    } else if (url.includes("youtube.com/shorts/")) {
      videoId = url.split("/shorts/")[1]?.split(/[?#]/)[0];
    } else if (url.includes("youtube.com/live/")) {
      videoId = url.split("/live/")[1]?.split(/[?#]/)[0];
    }

    return videoId ? `https://www.youtube.com/embed/${videoId}` : url;
  } catch {
    return url;
  }
};

const getLanguage = (url: string): Language | undefined => {
  const ext = getType(url);
  return LANGUAGE.includes(ext as Language) ? (ext as Language) : undefined;
};

interface BuildMediaArrayArgs {
  media?: MediaEntry[];
  src?: string | string[];
  sequence?: SequenceConfig | SequenceConfig[];
  customDomain?: string;
  sort: boolean;
}

/**
 * Pure helper that replaces the old `useMemo`-based computation.
 * Server Components can't use hooks (no useState/useMemo/etc.), but since
 * this runs once per server render there's no need for memoization anyway.
 */
const buildMediaArray = ({
  media,
  src,
  sequence,
  customDomain,
  sort,
}: BuildMediaArrayArgs): string[] => {
  const fromMedia =
    media?.flatMap((entry) => {
      if (typeof entry === "string") {
        return [normalizeUrl(entry, customDomain)];
      } else if ("sequence" in entry) {
        return generateSequenceUrls(entry.sequence, customDomain);
      }
      return [];
    }) ?? [];

  const fromSrc = Array.isArray(src) ? src : src ? [src] : [];
  const fromSeq = sequence ? (Array.isArray(sequence) ? sequence : [sequence]) : [];

  const fromSrcUrls = fromSrc.map((url) => normalizeUrl(url, customDomain));

  const fromSeqUrls = fromSeq.flatMap((conf) => generateSequenceUrls(conf, customDomain));

  const list = [...fromMedia, ...fromSrcUrls, ...fromSeqUrls];

  return sort ? [...list].sort() : list;
};

// Server Component — no "use client" directive.
// Interactive image lightbox behavior lives entirely in ./ImageViewer.
const Media: React.FC<MediaProps> = ({
  media,
  src,
  sequence,
  alt = "Media content",
  poster,
  domain: customDomain = `${IMAGE_DOMAIN}/`,
  sort = false,
  responsive = false,
  groupImg = false,
  movie = false,
  type = "auto",
  presentation = false,
  mode,
  tableTextAlign,
  tableTextWrap,
}) => {
  const mediaArray = buildMediaArray({ media, src, sequence, customDomain, sort });
  const group = groupImg && !responsive && mediaArray.length > 1;

  const renderMedia = (srcArray: string[]) => (
    <div
      className={clsx("media-container", {
        responsive,
        "group-img": group,
        dark: mode === "dark",
        light: mode === "light",
      })}
    >
      <ImageViewerProvider>
        <div className="media-group-img">
          {srcArray.map((file, index) => {
            // VIDEO
            if (type === "video" || (type === "auto" && isVideo(file))) {
              return (
                <div className="media-wrapper" key={index}>
                  <video
                    src={file}
                    poster={poster}
                    controls
                    crossOrigin="anonymous"
                    preload="metadata"
                    className={clsx(movie && "movie")}
                  />
                </div>
              );
            }

            // YOUTUBE
            if (type === "youtube" || (type === "auto" && isYouTubeLink(file))) {
              return (
                <div className="media-wrapper iframe-wrapper" key={index}>
                  <iframe
                    src={getYouTubeEmbedUrl(file)}
                    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope;"
                    allowFullScreen
                    loading="lazy"
                  />
                </div>
              );
            }

            // AUDIO
            if (type === "audio" || (type === "auto" && isAudio(file))) {
              return (
                <div className="media-wrapper audio-wrapper" key={index}>
                  <audio src={file} controls crossOrigin="anonymous" preload="metadata" />
                </div>
              );
            }

            if (type === "svg" || (type === "auto" && isSvg(file))) {
              return (
                <div className="media-wrapper image-wrapper" key={index}>
                  <Svg src={file} />
                </div>
              );
            }

            if (type === "img" || (type === "auto" && isImage(file))) {
              return <ImageThumb key={index} src={file} alt={alt} movie={movie} group={group} />;
            }

            if (type === "table" || (type === "auto" && (isExcel(file) || isCsv(file)))) {
              return (
                <div className="media-non-group" key={index}>
                  <Table file={file} textAlign={tableTextAlign} textWrap={tableTextWrap} />
                </div>
              );
            }

            if (type === "pdf" || (type === "auto" && isPdf(file))) {
              // Renamed from `type` to `fileType` to avoid shadowing the
              // `type` prop (same behavior as before, just unambiguous).
              const fileType = getType(file);
              return (
                <div className="media-non-group" key={index}>
                  <PDF
                    link={file}
                    type={fileType === "img" || fileType === "pdf" ? fileType : "pdf"}
                  />
                </div>
              );
            }

            if (type === "lang" || (type === "auto" && isLanguageJson(file))) {
              return (
                <div className="media-non-group" key={index}>
                  <Lang src={file} />
                </div>
              );
            }

            if (type === "syntax" || (type === "auto" && isSyntax(file))) {
              return (
                <div className="media-non-group" key={index}>
                  <Syntax src={file} language={getLanguage(file)} />
                </div>
              );
            }

            if (type === "tex" || (type === "auto" && isTex(file))) {
              return (
                <div className="media-non-group" key={index}>
                  <Maths src={file} />
                </div>
              );
            }

            if (isTldr(file)) return null;

            return (
              <div className="media-non-group" key={index}>
                <Para link={file} />
              </div>
            );
          })}
        </div>
      </ImageViewerProvider>
    </div>
  );

  if (presentation) {
    return (
      <Tabs>
        <TabList>
          <Tab>Slides</Tab>
          <Tab>Presentation</Tab>
        </TabList>
        <TabPanel>{renderMedia([mediaArray[mediaArray.length - 1]])}</TabPanel>
        <TabPanel>{renderMedia(mediaArray)}</TabPanel>
      </Tabs>
    );
  }

  return renderMedia(mediaArray);
};

export default Media;
