"use client";

import ClearIcon from "@mui/icons-material/Clear";
import { useEffect, useRef, useState } from "react";
import Backdrop from "~/components/Backdrop/Backdrop";
import Switch from "~/components/Switch/Switch";
import { toTitleCase } from "~/utils/custom_string";
import DoneButton from "../DoneButton/DoneButton";
import "./FilterSidebar.css";
interface FilterSidebarProps {
  category: string;
  toggleFilter: boolean;
  handleToggleFilter: () => void;
  recentlyAdded: boolean;
  handleRecentlyAdded: () => void;
  categoryOptions: string[];
  selectedCategory: string;
  handelSelectedCategory: (value: string) => void;
  enableClearFilter: string | true;
  handleClearFilter: () => void;
}

const FilterSidebar: React.FC<FilterSidebarProps> = ({
  category,
  toggleFilter,
  handleToggleFilter,
  recentlyAdded,
  handleRecentlyAdded,
  categoryOptions,
  selectedCategory,
  handelSelectedCategory,
  enableClearFilter,
  handleClearFilter,
}) => {
  const [isMobileView, setIsMobileView] = useState(false);
  const prevIsMobileRef = useRef(false);

  useEffect(() => {
    const initial = window.innerWidth <= 1200;
    setIsMobileView(initial);
    prevIsMobileRef.current = initial;

    const handleResize = () => {
      const currentIsMobile = window.innerWidth <= 1200;

      // Only update if crossing the 1200px threshold
      if (currentIsMobile !== prevIsMobileRef.current) {
        setIsMobileView(currentIsMobile);
        prevIsMobileRef.current = currentIsMobile;
      }
    };

    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  useEffect(() => {
    if (toggleFilter && isMobileView) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }

    return () => {
      document.body.style.overflow = "";
    };
  }, [toggleFilter, isMobileView]);

  return (
    <>
      {/* Backdrop only on mobile */}

      <Backdrop enable={toggleFilter && isMobileView} onClick={handleToggleFilter} />

      <aside
        id="filter-sidebar"
        className={`filter-sidebar ${toggleFilter && "active"}`}
        aria-label="Filters"
        aria-hidden={!toggleFilter}
      >
        <button
          type="button"
          className="close-filter-toggle"
          onClick={handleToggleFilter}
          aria-label="Close filters"
          title="Close filters"
        >
          <ClearIcon aria-hidden="true" />
        </button>
        <div className="recently-added">
          <Switch
            checked={recentlyAdded}
            onChange={handleRecentlyAdded}
            aria-label="Recently Added"
          />
          <h4 id="recently-added-label">Recently Added</h4>
          <button
            type="button"
            className={`clear-filter ${enableClearFilter && "active"}`}
            onClick={() => {
              handleClearFilter();
              if (isMobileView) {
                handleToggleFilter();
              }
            }}
            aria-label="Clear all filters"
            title="Clear all filters"
          >
            Clear
          </button>
        </div>
        <h2 id="filter-category-title" className="category-title">
          {toTitleCase(category)}
        </h2>
        <div className="radio-list" role="radiogroup" aria-labelledby="filter-category-title">
          <div>
            {categoryOptions.map((option) => (
              <label key={option} className="radio-option">
                <input
                  type="radio"
                  name="radio-list"
                  value={option}
                  checked={selectedCategory === option}
                  onChange={() => handelSelectedCategory(option)}
                />
                <span>{option}</span>
              </label>
            ))}
          </div>
        </div>
        {isMobileView && <DoneButton onClick={handleToggleFilter} />}
      </aside>
    </>
  );
};

export default FilterSidebar;
