// ui/MarkdownViewer/remark-plugins.ts

import type { Blockquote, Code as MdastCode, Text as MdastText, Paragraph, Root } from "mdast";
import { visit } from "unist-util-visit";
import type { NoteType } from "~/ui/Note/Note";

function extractTitle(meta?: string | null): string | undefined {
  if (!meta) {
    return undefined;
  }

  const match = /title=["']([^"']+)["']/.exec(meta);

  return match?.[1];
}

// -----------------------------------------------------------------------
// Keep this list in sync with the NOTE_META keys in ~/ui/Note/Note.tsx —
// it's what both note remark plugins below check a directive/alert
// keyword against before turning it into a <Note type="..."> element.
// -----------------------------------------------------------------------
const NOTE_TYPES = new Set<NoteType>([
  "note",
  "tip",
  "info",
  "important",
  "warning",
  "danger",
  "error",
  "success",
  "caution",
  "hint",
  "example",
  "question",
  "answer",
  "remember",
  "summary",
  "best-practice",
  "reference",
  "todo",
]);

export function isNoteType(value: string): value is NoteType {
  return NOTE_TYPES.has(value as NoteType);
}

// -----------------------------------------------------------------------
// 0a. Remark plugin: container-directive note syntax.
//
//       ::: tip
//       This is additional information.
//       :::
//
//     `remark-directive` (registered in parseMarkdown.tsx, ahead of this
//     plugin) turns `::: name` ... `:::` into a `containerDirective`
//     mdast node with `name: "name"`. mdast-util-to-hast has no default
//     handler for that node type, so EVERY containerDirective must be
//     given an `hName` here or MDX throws "Cannot handle unknown node"
//     — including ones that aren't note keywords. Recognized note
//     keywords become `<note type="...">`, everything else falls back
//     to a plain `<div>` wrapper so a stray `:::something` never breaks
//     the whole page.
// -----------------------------------------------------------------------
interface ContainerDirectiveNode {
  type: "containerDirective";
  name: string;
  data?: { hName?: string; hProperties?: Record<string, unknown> };
}

export function remarkContainerNotes() {
  return (tree: Root) => {
    visit(tree, "containerDirective", (node) => {
      const directive = node as unknown as ContainerDirectiveNode;
      const name = directive.name?.toLowerCase();

      directive.data = directive.data || {};

      if (name && isNoteType(name)) {
        directive.data.hName = "note";
        directive.data.hProperties = { ...(directive.data.hProperties || {}), type: name };
        return;
      }

      // Unknown directive keyword — render inertly instead of crashing.
      directive.data.hName = "div";
      directive.data.hProperties = {
        ...(directive.data.hProperties || {}),
        "data-directive": name,
      };
    });
  };
}

// -----------------------------------------------------------------------
// 0b. Remark plugin: GitHub-style alert syntax.
//
//       > [!NOTE]
//       > This is additional information.
//
//     Blockquotes already have a default hast handler, so unmatched
//     blockquotes are left completely untouched and still render via
//     the plain `blockquote` mapping below. Only a blockquote whose
//     first paragraph starts with a recognized `[!type]` marker gets
//     rewritten into a `<note type="...">`. Covers the common
//     single-marker-line case; unusual formatting (marker split across
//     inline formatting, etc.) is left alone.
// -----------------------------------------------------------------------
export function remarkGithubAlerts() {
  return (tree: Root) => {
    visit(tree, "blockquote", (node: Blockquote) => {
      const firstParagraph = node.children[0] as Paragraph | undefined;

      if (!firstParagraph || firstParagraph.type !== "paragraph") {
        return;
      }

      const firstText = firstParagraph.children[0] as MdastText | undefined;

      if (!firstText || firstText.type !== "text") {
        return;
      }

      const match = /^\[!([a-z][\w-]*)\][ \t]*\n?/i.exec(firstText.value);

      if (!match) {
        return;
      }

      const type = match[1].toLowerCase();

      if (!isNoteType(type)) {
        return;
      }

      firstText.value = firstText.value.slice(match[0].length);

      if (firstText.value.length === 0) {
        firstParagraph.children.shift();
      }

      if (firstParagraph.children.length === 0) {
        node.children.shift();
      }

      node.data = node.data || {};
      node.data.hName = "note";
      node.data.hProperties = { ...(node.data.hProperties || {}), type };
    });
  };
}

// -----------------------------------------------------------------------
// 0c. Remark plugin: single-line container note syntax.
//
//       ::: warning Don't commit secrets. :::
//
//     `remark-directive`'s container form only recognizes `:::name` as
//     an opening fence when it's alone on its own line, so typing the
//     whole thing on one line (easy to do by hand) just leaves it as an
//     ordinary paragraph of text — remarkContainerNotes above never
//     sees it. This plugin catches that shape directly: it only matches
//     a paragraph whose *entire* content is a single text node of the
//     form `::: type ... :::`, so it never reaches into fenced code
//     blocks (those are `code` nodes, not `paragraph` nodes) or partial
//     matches inside longer prose.
// -----------------------------------------------------------------------
export function remarkInlineContainerNotes() {
  return (tree: Root) => {
    visit(tree, "paragraph", (node: Paragraph) => {
      if (node.children.length !== 1 || node.children[0].type !== "text") {
        return;
      }

      const text = node.children[0] as MdastText;
      const match = /^:::\s*([a-z][\w-]*)\s+([\s\S]*?)\s*:::$/i.exec(text.value.trim());

      if (!match) {
        return;
      }

      const type = match[1].toLowerCase();

      if (!isNoteType(type)) {
        return;
      }

      text.value = match[2];
      node.data = node.data || {};
      node.data.hName = "note";
      node.data.hProperties = { ...(node.data.hProperties || {}), type };
    });
  };
}

// -----------------------------------------------------------------------
// 0. Remark plugin: fenced code meta (```tsx title="foo.tsx") isn't
//    forwarded to MDX components as a prop by default — only the
//    language ends up on className. This plugin reads node.meta, pulls
//    out title="...", and writes it to hProperties so it survives the
//    mdast -> hast -> JSX pipeline as a real prop (props.title) on the
//    compiled <code> element.
//
//    Registered in parseMarkdown.tsx's evaluateSync remarkPlugins array,
//    since this codebase compiles MDX client-side rather than through
//    next.config.js.
// -----------------------------------------------------------------------
export function remarkCodeTitle() {
  return (tree: Root) => {
    visit(tree, "code", (node: MdastCode) => {
      const title = extractTitle(node.meta);

      if (!title) {
        return;
      }

      node.data = node.data || {};
      node.data.hProperties = {
        ...(node.data.hProperties || {}),
        title,
      };
    });
  };
}

// -----------------------------------------------------------------------
// 0d. Remark plugin: streaming caret for the AI answer.
//
//     Appends an empty <span class="pia-caret"> as the last inline child of
//     the final paragraph (descending through lists / blockquotes), so the
//     blinking caret sits at the end of the text while it streams. If the
//     document ends in a heading, code block or table there is no inline
//     position, so no caret is drawn.
// -----------------------------------------------------------------------
type ParentLike = { type: string; children?: ParentLike[] };

export function remarkStreamingCaret() {
  return (tree: Root) => {
    let node = tree as unknown as ParentLike;

    while (node.children?.length) {
      const last = node.children[node.children.length - 1];

      if (last.type === "paragraph") {
        last.children = last.children ?? [];
        last.children.push({
          type: "emphasis",
          children: [],
          // `emphasis` is converted to an element, which is then renamed
          // to <span> by hName, so the caret is a real element, not text.
          data: {
            hName: "span",
            hProperties: { className: ["pia-caret"], ariaHidden: "true" },
          },
        } as unknown as ParentLike);
        return;
      }

      if (last.type === "list" || last.type === "listItem" || last.type === "blockquote") {
        node = last;
      } else {
        return;
      }
    }
  };
}
