"use client";

import DownloadIcon from "@mui/icons-material/Download";
import FullscreenIcon from "@mui/icons-material/Fullscreen";
import FullscreenExitIcon from "@mui/icons-material/FullscreenExit";

interface MermaidActionsProps {
  title: string;
  chart: string;
  svg: string | null;
  expanded: boolean;
  onToggleExpand: () => void;
}

export default function MermaidActions({
  title,
  // chart,
  svg,
  expanded,
  onToggleExpand,
}: MermaidActionsProps) {
  // const { copied, copy } = useCopyToClipboard();

  // const handleShare = async () => {
  //   try {
  //     if (navigator.share) {
  //       await navigator.share({ title, text: chart });
  //     } else {
  //       await navigator.clipboard.writeText(chart);
  //     }
  //   } catch {
  //     // User cancelled or sharing failed.
  //   }
  // };

  const handleDownload = () => {
    if (!svg) return;

    const blob = new Blob([svg], { type: "image/svg+xml" });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");

    link.href = url;
    link.download = `${title.trim().replace(/\s+/g, "-").toLowerCase() || "diagram"}.svg`;

    document.body.appendChild(link);
    link.click();
    link.remove();

    URL.revokeObjectURL(url);
  };

  return (
    <div className="buttons">
      {/* <button
        type="button"
        onClick={() => copy(chart)}
        className={`toggle-button mermaid-button ${copied ? "copied" : ""}`}
        aria-label={copied ? "Copied" : "Copy diagram source"}
        title="Copy diagram source"
        disabled={!chart}
      >
        {copied ? <DoneIcon /> : <ContentCopyIcon />}
      </button> */}

      <button
        type="button"
        className="toggle-button mermaid-button"
        onClick={handleDownload}
        aria-label="Download SVG"
        title="Download SVG"
        disabled={!svg}
      >
        <DownloadIcon />
      </button>

      <button
        type="button"
        className="toggle-button mermaid-button"
        onClick={onToggleExpand}
        aria-label={expanded ? "Collapse diagram" : "Expand diagram"}
        title={expanded ? "Collapse" : "Expand"}
        disabled={!svg}
      >
        {expanded ? <FullscreenExitIcon /> : <FullscreenIcon />}
      </button>

      {/* <button
        type="button"
        className="toggle-button mermaid-button share"
        onClick={handleShare}
        aria-label="Share diagram"
        title="Share diagram source"
        disabled={!chart}
      >
        <ShareIcon />
      </button> */}
    </div>
  );
}
