"use client";

import ArrowBackIosIcon from "@mui/icons-material/ArrowBackIos";
import ArrowForwardIosIcon from "@mui/icons-material/ArrowForwardIos";
import CloseIcon from "@mui/icons-material/Close";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useCallback, useEffect, useMemo, useRef, useState, useTransition } from "react";
import Backdrop from "~/components/Backdrop/Backdrop";
import Footer from "~/components/Footer/Footer";
import Header from "~/components/Header/Header";
import TableOfContents from "~/components/TableOfContents/TableOfContents";
import TOCFab from "~/components/TOCFab/TOCFab";
import { pushClientPath } from "~/features/learning/lib/remote";
import { useReadingProgress } from "~/hooks/useReadingProgress";
import { useTOC } from "~/hooks/useTOC";
import type { CourseType } from "~/model/course_model";
import { capitalizeFirstLetter } from "~/utils/custom_string";
import { createRoute } from "~/utils/slug";
import "./Tutorial.css";

export type ClientContentData = {
  about: CourseType;
  route?: Array<{
    heading?: string;
    topic: string;
    key: string;
    path: string;
    type?: "H1" | "H2" | "H3";
  }>;
};

interface TutorialClientProps {
  contentData: ClientContentData;
  category: string;
  currentTopic: string;
  previousTopic: string | null;
  previousTopicPath: string | null;
  nextTopic: string | null;
  nextTopicPath: string | null;
  isMultiPage: boolean;
  basePath?: string;
  clientNavigation?: boolean;
  children?: React.ReactNode;
}

// Stops the hash-scroll loop if the target heading never appears
const MAX_HASH_SCROLL_MS = 2000;

const TutorialClient = ({
  contentData,
  children,
  category,
  currentTopic,
  previousTopic,
  previousTopicPath,
  nextTopic,
  nextTopicPath,
  isMultiPage,
  basePath = "",
  clientNavigation = false,
}: TutorialClientProps) => {
  const router = useRouter();
  const pathname = usePathname();

  const [showTopic, setShowTopic] = useState(false);
  const [showTOCDrawer, setShowTOCDrawer] = useState(false);
  const [isPending, startTransition] = useTransition();
  const isNavigatingRef = useRef(false);
  const offCanvasRef = useRef<HTMLDivElement>(null);
  const tocDrawerRef = useRef<HTMLDivElement>(null);
  const activeTopicRef = useRef<HTMLLIElement>(null);
  const contentMainRef = useRef<HTMLDivElement>(null);

  // Only needed here to render the sidebar list — nav targets
  // (previousTopic/nextTopic/isMultiPage) already arrive as props.
  const topicSections = useMemo(() => {
    const routeList = contentData.route ?? [];

    return routeList.reduce<Array<{ heading: string; topics: typeof routeList }>>(
      (sections, content) => {
        if (content.heading || sections.length === 0) {
          sections.push({
            heading: content.heading ?? "Topics",
            topics: [],
          });
        }

        sections[sections.length - 1].topics.push(content);
        return sections;
      },
      [],
    );
  }, [contentData.route]);

  const { items: tocItems, activeId, isLoading: tocLoading } = useTOC(contentMainRef);
  const progress = useReadingProgress(contentMainRef);

  useEffect(() => {
    if (activeTopicRef.current) {
      activeTopicRef.current.scrollIntoView({
        block: "center",
      });
    }
  }, [currentTopic, showTopic]);

  // Scroll to the URL hash (or to the top) whenever the topic changes
  useEffect(() => {
    if (!window.location.hash) {
      window.scrollTo({ top: 0 });
      return;
    }

    const id = decodeURIComponent(window.location.hash.slice(1));
    let rafId = 0;
    const startedAt = performance.now();

    const scrollToHash = () => {
      const element = document.getElementById(id);

      if (!element) {
        // Content may still be mounting; retry briefly, then give up
        if (performance.now() - startedAt < MAX_HASH_SCROLL_MS) {
          rafId = requestAnimationFrame(scrollToHash);
        }
        return;
      }

      const header = document.querySelector<HTMLElement>(".app-header");
      const headerHeight = header?.offsetHeight ?? 0;

      window.scrollTo({
        top: element.getBoundingClientRect().top + window.scrollY - headerHeight - 16,
        behavior: "auto",
      });
    };

    rafId = requestAnimationFrame(() => {
      rafId = requestAnimationFrame(scrollToHash);
    });

    return () => cancelAnimationFrame(rafId);
  }, [currentTopic]);

  // Close both drawers when the page changes
  useEffect(() => {
    setShowTOCDrawer(false);
    setShowTopic(false);
  }, [pathname, currentTopic]);

  useEffect(() => {
    function handleClickOutside(event: MouseEvent | TouchEvent) {
      if (
        showTopic &&
        offCanvasRef.current &&
        !offCanvasRef.current.contains(event.target as Node)
      ) {
        setShowTopic(false);
      }
      if (
        showTOCDrawer &&
        tocDrawerRef.current &&
        !tocDrawerRef.current.contains(event.target as Node)
      ) {
        setShowTOCDrawer(false);
      }
    }

    document.addEventListener("mousedown", handleClickOutside);
    document.addEventListener("touchstart", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      document.removeEventListener("touchstart", handleClickOutside);
    };
  }, [showTopic, showTOCDrawer]);

  useEffect(() => {
    const handleResize = () => {
      if (window.innerWidth > 1200) setShowTopic(false);
      if (window.innerWidth > 1280) setShowTOCDrawer(false);
    };
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  // Guards against a second click firing a new push while the first
  // transition is still resolving; cleared once the URL actually changes.
  useEffect(() => {
    isNavigatingRef.current = false;
  }, [pathname, currentTopic]);

  const handleNavigation = useCallback(
    (nextPath: string | null) => {
      if (!nextPath || isNavigatingRef.current) return;
      isNavigatingRef.current = true;

      startTransition(() => {
        if (clientNavigation) {
          pushClientPath(nextPath);
        } else {
          router.push(nextPath);
        }
      });
    },
    [clientNavigation, router],
  );

  // Prefetch previous/next as soon as we know them, so the arrow
  // navigation feels instant even on cold cache.
  useEffect(() => {
    if (clientNavigation) return;
    if (previousTopicPath) {
      router.prefetch(previousTopicPath);
    }
    if (nextTopicPath) {
      router.prefetch(nextTopicPath);
    }
  }, [previousTopicPath, nextTopicPath, router, clientNavigation]);

  const handlePrefetch = useCallback(
    (path: string) => {
      if (!clientNavigation) {
        router.prefetch(path);
      }
    },
    [router, clientNavigation],
  );

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (!(event.ctrlKey || event.metaKey)) return;

      switch (event.key) {
        case "ArrowLeft":
          event.preventDefault();
          handleNavigation(previousTopicPath);
          break;
        case "ArrowRight":
          event.preventDefault();
          handleNavigation(nextTopicPath);
          break;
      }
    };

    window.addEventListener("keydown", handleKeyDown);

    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [previousTopicPath, nextTopicPath, handleNavigation]);

  const hasTOC = tocItems.length > 0;
  // Reserve the sidebar / FAB while headings are still loading, so nothing pops in
  const showTOC = hasTOC || tocLoading;

  return (
    <>
      {/* <ReadingProgress progress={progress} /> */}
      <section className="app-section tutorial-section">
        <Header onClick={() => setShowTopic(true)} isShowTopicButton={isMultiPage} />

        <div className="app-container content-wrapper">
          {/* Backdrops */}
          <Backdrop enable={showTopic} className="tutorial-backdrop" />
          <Backdrop
            enable={showTOCDrawer}
            className="toc-backdrop"
            onClick={() => setShowTOCDrawer(false)}
          />

          {/* Left Sidebar — topic navigation */}
          {isMultiPage && (
            <div
              id="topic-sidebar"
              className={`content-topic ${showTopic ? "active" : ""}`}
              ref={offCanvasRef}
              // aria-hidden={!showTopic}
            >
              <div className="content-topic-header">
                <Link
                  className="course-home-link"
                  href={createRoute(basePath, category, contentData.about.name)}
                  onClick={(event) => {
                    if (clientNavigation) {
                      event.preventDefault();
                      pushClientPath(createRoute(basePath, category, contentData.about.name));
                    }
                    setShowTopic(false);
                  }}
                >
                  {contentData.about.name}
                </Link>
                <button
                  type="button"
                  onClick={() => setShowTopic(false)}
                  aria-label="Close topics sidebar"
                  title="Close topics sidebar"
                >
                  <CloseIcon aria-hidden="true" />
                </button>
              </div>

              <nav className="topic-nav" aria-label="Topics navigation">
                {topicSections.map((section, sectionIndex) => (
                  <details
                    className="topic-section"
                    key={`${section.heading}-${sectionIndex}`}
                    open
                  >
                    <summary className="topic-heading">
                      <span>{section.heading}</span>
                      <span className="topic-heading-icon" aria-hidden="true">
                        ›
                      </span>
                    </summary>
                    <ul>
                      {section.topics.map((content, index) => {
                        const isActive = content.key === currentTopic;
                        const indentClass =
                          content.type === "H2"
                            ? "topic-h2"
                            : content.type === "H3"
                              ? "topic-h3"
                              : "topic-h1";

                        return (
                          <li
                            key={`${content.topic} ${index}`}
                            ref={isActive ? activeTopicRef : null}
                            className={`topic-item ${indentClass}`}
                          >
                            <Link
                              className={`my-nav-link${isActive ? " active" : ""}`}
                              aria-current={isActive ? "page" : undefined}
                              href={content.path}
                              onClick={(event) => {
                                if (clientNavigation) {
                                  event.preventDefault();
                                  pushClientPath(content.path);
                                }
                                setShowTopic(false);
                              }}
                              onMouseEnter={() => handlePrefetch(content.path)}
                            >
                              {contentData.about.captalise !== false
                                ? capitalizeFirstLetter(content.topic)
                                : content.topic}
                            </Link>
                          </li>
                        );
                      })}
                    </ul>
                  </details>
                ))}
              </nav>
            </div>
          )}

          {/* Center — main content */}
          <div className="content-main" ref={contentMainRef}>
            {children}

            <div className="navigation-buttons" aria-busy={isPending}>
              {previousTopic && previousTopicPath ? (
                <Link
                  href={previousTopicPath}
                  className={`navigation-button active ${isPending ? "pending" : ""}`}
                  onClick={(event) => {
                    event.preventDefault();
                    handleNavigation(previousTopicPath);
                  }}
                  onMouseEnter={() => handlePrefetch(previousTopicPath)}
                  aria-label={`Previous: ${capitalizeFirstLetter(previousTopic)}`}
                >
                  <ArrowBackIosIcon aria-hidden="true" />
                  <span>Previous: {capitalizeFirstLetter(previousTopic)}</span>
                </Link>
              ) : (
                <span
                  className="navigation-button"
                  aria-label="No previous topic"
                  aria-disabled="true"
                >
                  <ArrowBackIosIcon aria-hidden="true" />
                  <span>Previous: No previous topic</span>
                </span>
              )}

              {nextTopic && nextTopicPath ? (
                <Link
                  href={nextTopicPath}
                  className={`navigation-button active ${isPending ? "pending" : ""}`}
                  onClick={(event) => {
                    event.preventDefault();
                    handleNavigation(nextTopicPath);
                  }}
                  onMouseEnter={() => handlePrefetch(nextTopicPath)}
                  aria-label={`Next: ${capitalizeFirstLetter(nextTopic)}`}
                >
                  <span>Next: {capitalizeFirstLetter(nextTopic)}</span>
                  <ArrowForwardIosIcon aria-hidden="true" />
                </Link>
              ) : (
                <span className="navigation-button" aria-label="No next topic" aria-disabled="true">
                  <span>Next: No next topic</span>
                  <ArrowForwardIosIcon aria-hidden="true" />
                </span>
              )}
            </div>
          </div>

          {/* Right — sticky TOC (desktop) */}
          {showTOC && (
            <TableOfContents
              items={tocItems}
              activeId={activeId}
              isLoading={tocLoading}
              isDrawer={false}
            />
          )}
        </div>

        <Footer />
      </section>

      {/* TOC floating drawer (tablet / mobile) */}
      {hasTOC && (
        <div ref={tocDrawerRef}>
          <TableOfContents
            items={tocItems}
            activeId={activeId}
            isDrawer={true}
            isOpen={showTOCDrawer}
            onClose={() => setShowTOCDrawer(false)}
          />
        </div>
      )}

      {/* FAB */}
      {showTOC && (
        <TOCFab
          progress={progress}
          isOpen={showTOCDrawer}
          loading={!hasTOC}
          onToggle={() => hasTOC && setShowTOCDrawer((p) => !p)}
        />
      )}
    </>
  );
};

export default TutorialClient;