"use client";

import React from "react";
import { useTabsContext } from "./TabsContext";

export interface TabProps {
  children: React.ReactNode;
  /** Disables the tab: no click/keyboard selection, aria-disabled, removed from tab order. */
  disabled?: boolean;
  /** Extra class name(s) merged with the base "react-tabs__tab" class. */
  className?: string;
  /** Overrides the Tabs-level selectedTabClassName for this specific Tab. */
  selectedClassName?: string;
  /** Overrides the Tabs-level disabledClassName for this specific Tab. */
  disabledClassName?: string;
  /** Overrides the auto-generated id (also used to build aria-controls on the panel). */
  id?: string;
  /**
   * @internal Injected automatically by TabList via cloneElement based on
   * position among its Tab children. Do not pass this manually.
   */
  index?: number;
}

function TabImpl({
  children,
  disabled = false,
  className,
  selectedClassName,
  disabledClassName,
  id,
  index,
}: TabProps) {
  const {
    selectedIndex,
    onSelectTab,
    idPrefix,
    selectedTabClassName,
    disabledClassName: contextDisabledClassName,
  } = useTabsContext("Tab");

  const resolvedIndex = index ?? 0;
  const isSelected = resolvedIndex === selectedIndex;

  const tabId = id ?? `${idPrefix}-tab-${resolvedIndex}`;
  const panelId = `${idPrefix}-panel-${resolvedIndex}`;

  const classes = ["react-tabs__tab", className];
  if (isSelected) classes.push(selectedClassName || selectedTabClassName);
  if (disabled) classes.push(disabledClassName || contextDisabledClassName);

  const handleClick = (event: React.MouseEvent<HTMLDivElement>) => {
    if (disabled) return;
    onSelectTab(resolvedIndex, event);
  };

  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (disabled) return;
    // Space and Enter both activate the focused tab (WAI-ARIA manual activation pattern).
    // "Spacebar" is included for older browsers that report the legacy key value.
    if (event.key === "Enter" || event.key === " " || event.key === "Spacebar") {
      event.preventDefault();
      onSelectTab(resolvedIndex, event);
    }
  };

  return (
    <div
      role="tab"
      id={tabId}
      className={classes.filter(Boolean).join(" ")}
      aria-selected={isSelected}
      aria-disabled={disabled ? "true" : undefined}
      aria-controls={panelId}
      data-index={resolvedIndex}
      // Roving tabindex: only the selected, enabled tab sits in the natural
      // Tab order. Arrow-key navigation (handled by TabList) moves DOM focus
      // programmatically between tabs regardless of tabIndex.
      tabIndex={disabled ? -1 : isSelected ? 0 : -1}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
    >
      {children}
    </div>
  );
}

TabImpl.displayName = "Tab";

export const Tab = React.memo(TabImpl) as React.MemoExoticComponent<typeof TabImpl> & {
  tabsRole: string;
};
Tab.displayName = "Tab";
// Stable marker used by TabList to identify Tab children when injecting
// index props. Deliberately NOT a `child.type === Tab` reference check —
// under Next.js Turbopack/Fast Refresh (and RSC/client module boundaries),
// hot reloads can produce a second module instance of this component, which
// breaks reference equality and silently stops index injection (every Tab
// then falls back to index 0, making all tabs appear selected at once).
// A plain string marker survives that because it's re-set identically on
// every module evaluation, regardless of which instance is live.
Tab.tabsRole = "Tab";
