"use client";

import { DotLottieReact } from "@lottiefiles/dotlottie-react";
import { useTheme } from "next-themes";
import "./NoResultFound.css";

const LOTTIE_DEFAULT = "/lottie/no-result-found.lottie";
const LOTTIE_DARK = "/lottie/no-result-found-dark.lottie";

interface NoResultFoundProps extends React.HTMLAttributes<HTMLDivElement> {
  searchTerm: string;
}

const NoResultFound: React.FC<NoResultFoundProps> = ({ searchTerm, ...props }) => {
  const { theme } = useTheme();

  return (
    <div className="no-courses-message" role="status" aria-live="polite" {...props}>
      <div className="message-lottie" aria-hidden="true">
        <DotLottieReact
          // DotLottieReact doesn't recreate its animation player when only the `src`
          // changes. `key={theme}` forces React to unmount the old player and mount a
          // new one, ensuring the correct animation loads after a theme change.
          key={theme}
          src={theme === "dark" ? LOTTIE_DARK : LOTTIE_DEFAULT}
          loop
          autoplay
          style={{ width: "150px", height: "150px" }}
        />
      </div>
      <div className="message">
        <h5>Nothing Found &ldquo;{searchTerm}&rdquo;</h5>
        <p>Try adjusting your search. Suggestions:</p>
        <ul>
          <li>Check your spelling</li>
          <li>Use different keywords</li>
          <li>Try more general words</li>
        </ul>
      </div>
    </div>
  );
};

export default NoResultFound;