import { Suspense } from "react";

import { normalizeUrl } from "~/utils/url";

import LangInner from "./LangInner";
import { getLangData } from "./langResource";

import type { LangData, ViewType } from "./types";

export interface LangProps {
  viewType?: ViewType;
  lang?: LangData;
  src?: string;
  domain?: string;
}

export default function Lang({ lang, src, domain, viewType }: LangProps) {
  if (lang && src) {
    return <div>❌ Use either lang or src.</div>;
  }

  if (!lang && !src) {
    return <div>❌ Missing lang or src.</div>;
  }

  // Literal data — no fetch, no promise, render straight away.
  if (lang) {
    return <LangInner lang={lang} viewType={viewType} />;
  }

  const langPromise = getLangData(normalizeUrl(src!, domain));

  return (
    <Suspense fallback={null}>
      <LangInner lang={langPromise} viewType={viewType} />
    </Suspense>
  );
}
