"use client";

import { use } from "react";
import { PhotoView } from "react-photo-view";

import type { SvgData } from "./Svg";

interface SvgClientProps {
  src: string;
  dataPromise: Promise<SvgData>;
}

const SvgClient = ({ src, dataPromise }: SvgClientProps) => {
  const { svg, error } = use(dataPromise);

  if (error || !svg) {
    return <p>{error ?? "Failed to load SVG"}</p>;
  }

  return (
    <PhotoView src={src}>
      <div className="svg-wrapper" dangerouslySetInnerHTML={{ __html: svg }} />
    </PhotoView>
  );
};

export default SvgClient;
