"use client";

import FilterListIcon from "@mui/icons-material/FilterList";
import { usePathname, useRouter } from "next/navigation";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import Footer from "~/components/Footer/Footer";
import Header from "~/components/Header/Header";
import SearchBar from "~/components/SearchBar/SearchBar";
import { useDebounce } from "~/hooks/useDebounce";
import type { CourseWithFirstTopic } from "~/model/course_model";
import NoResultFound from "~/page/Course/components/NoResultFound/NoResultFound";
import { normalizeSearch } from "~/utils/custom_string";
import { createSlug } from "~/utils/slug";
import CourseList from "./components/CourseList/CourseList";
import FilterSidebar from "./components/FilterSidebar/FilterSidebar";
import "./Course.css";

interface CourseClientProps {
  categoryTitle: string;
  groupedCourses: Record<string, CourseWithFirstTopic[]>;
  subCategoryMap: Record<string, string>;
  onlyOneCourse: boolean;
  /** Base path segment prepended to all internal doc links (e.g. "learn"). Default: "". */
  basePath?: string;
  /** Keep navigation inside the category shell instead of asking Next for a new route. */
  clientNavigation?: boolean;
}

const CourseClient = ({
  categoryTitle,
  groupedCourses,
  subCategoryMap,
  onlyOneCourse,
  basePath = "",
  clientNavigation = false,
}: CourseClientProps) => {
  const pathname = usePathname();
  const router = useRouter();

  // NOTE: we deliberately never call `useSearchParams()` here.
  //
  // `useSearchParams()` opts the whole page out of static rendering: Next
  // requires a Suspense boundary above it, and since there's no real
  // request/URL at build time, statically generated pages would just embed
  // the Suspense fallback (the loading screen) as their HTML instead of
  // actual course content.
  //
  // Instead, the URL query string is treated exactly like `window.innerWidth`
  // elsewhere in this file: unknown/empty during SSR & SSG (and therefore on
  // the very first client paint too, to avoid a hydration mismatch), then
  // read for real from `window.location` once mounted.
  const [searchParams, setSearchParamsState] = useState<URLSearchParams>(
    () => new URLSearchParams(),
  );

  // Sync from the real URL after mount, and keep in sync with browser
  // back/forward navigation (router.replace/push don't fire `popstate`,
  // but we mirror those into state manually in `setSearchParams` below).
  useEffect(() => {
    const syncFromLocation = () => {
      setSearchParamsState(new URLSearchParams(window.location.search));
    };

    syncFromLocation();

    window.addEventListener("popstate", syncFromLocation);
    return () => window.removeEventListener("popstate", syncFromLocation);
  }, []);

  const setSearchParams = useCallback(
    (next: URLSearchParams) => {
      const query = next.toString();
      router.replace(query ? `${pathname}?${query}` : pathname, { scroll: false });
      // router.replace() alone won't re-render this component (we're not
      // subscribed to route changes via useSearchParams), so mirror the
      // change into local state immediately as well.
      setSearchParamsState(next);
    },
    [pathname, router],
  );

  const selectedSubCategory = searchParams.get("sub") || "all";
  const recentlyAdded = searchParams.get("recent") === "true";

  const urlSearchQuery = normalizeSearch(searchParams.get("q") || "");
  const [searchTerm, setSearchTerm] = useState(urlSearchQuery);
  const debouncedSearch = normalizeSearch(useDebounce(searchTerm, 300, searchTerm === ""));

  // Runs only on the first render. During SSR/SSG, `window` is unavailable,
  // so the initial value is `false` on page refresh/direct URL.
  const [toggleFilter, setToggleFilter] = useState(false);
  const prevWidthRef = useRef(0);

  const inputRef = useRef<HTMLInputElement>(null);

  //! ================= EFFECTS =================

  // Set the initial sidebar state after the component mounts,
  // since `window` is only available in the browser.
  useEffect(() => {
    const width = window.innerWidth;
    setToggleFilter(width > 1200);
    prevWidthRef.current = width;
  }, []);

  useEffect(() => {
    const handleResize = () => {
      const currentWidth = window.innerWidth;
      const prevWidth = prevWidthRef.current;

      if (prevWidth > 1200 && currentWidth <= 1200) {
        setToggleFilter(false);
      }
      if (prevWidth <= 1200 && currentWidth > 1200) {
        setToggleFilter(true);
      }

      prevWidthRef.current = currentWidth;
    };

    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  useEffect(() => {
    const handleScroll = () => {
      if (inputRef.current) inputRef.current.blur();
    };

    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  useEffect(() => {
    window.scrollTo({ top: 0, behavior: "smooth" });
  }, [searchParams]);

  useEffect(() => {
    const newParams = new URLSearchParams(searchParams);

    let shouldUpdate = false;

    if (selectedSubCategory !== "all" && !subCategoryMap[selectedSubCategory]) {
      newParams.delete("sub");
      shouldUpdate = true;
    }

    const recentParam = searchParams.get("recent");

    if (recentParam !== null && recentParam !== "true") {
      newParams.delete("recent");
      shouldUpdate = true;
    }

    if (shouldUpdate) {
      setSearchParams(newParams);
    }
  }, [searchParams, selectedSubCategory, subCategoryMap, setSearchParams]);

  useEffect(() => {
    setSearchTerm(urlSearchQuery);
  }, [urlSearchQuery]);

  //! ================= HANDLERS =================

  const handleSubCategoryChange = useCallback(
    (value: string) => {
      const newParams = new URLSearchParams(searchParams);

      if (value === "All") {
        newParams.delete("sub");
      } else {
        newParams.set("sub", createSlug(value));
      }

      setSearchParams(newParams);
    },
    [searchParams, setSearchParams],
  );

  const handleRecentlyAddedChange = useCallback(() => {
    const newParams = new URLSearchParams(searchParams);
    const newValue = !recentlyAdded;
    if (!newValue) {
      newParams.delete("recent");
    } else {
      newParams.set("recent", "true");
    }
    setSearchParams(newParams);
  }, [searchParams, recentlyAdded, setSearchParams]);

  const handleSearchQueryChange = useCallback(
    (value: string) => {
      setSearchTerm(value);

      const newParams = new URLSearchParams(searchParams);

      if (value.trim() === "") {
        newParams.delete("q");
      } else {
        newParams.set("q", normalizeSearch(value));
      }

      setSearchParams(newParams);
    },
    [searchParams, setSearchParams],
  );

  const clearFilters = useCallback(() => {
    setSearchTerm("");
    setSearchParams(new URLSearchParams());
  }, [setSearchParams]);

  //! ================= DATA =================
  // Grouping (groupedCourses) and the subcategory slug map (subCategoryMap)
  // are computed once on the server and passed in as props — only the
  // parts that depend on client-only state (debounced search text,
  // recently-added ordering) are (re)computed here.

  const processedCourses = useMemo(() => {
    const filtered = Object.entries(groupedCourses).reduce(
      (result, [subCat, courses]) => {
        result[subCat] = courses.filter((course) =>
          normalizeSearch(course.name).includes(debouncedSearch),
        );
        return result;
      },
      {} as Record<string, CourseWithFirstTopic[]>,
    );

    if (recentlyAdded) {
      return Object.fromEntries(
        Object.entries(filtered)
          .reverse()
          .map(([subCat, courses]) => [subCat, [...courses].reverse()]),
      );
    }

    return filtered;
  }, [groupedCourses, debouncedSearch, recentlyAdded]);

  const activeSubCategory =
    selectedSubCategory === "all" ? "All" : subCategoryMap[selectedSubCategory];

  const subCategories = useMemo(
    () => ["All", ...Object.keys(processedCourses)],
    [processedCourses],
  );

  const isAnyFilterApplied = selectedSubCategory !== "all" || recentlyAdded || debouncedSearch;

  //! ================= UI =================

  return (
    <>
      <section className="app-section course-section">
        <Header />

        <div className="app-container course-wrapper">
          {!onlyOneCourse && (
            <FilterSidebar
              category={categoryTitle}
              toggleFilter={toggleFilter}
              handleToggleFilter={() => setToggleFilter((prev) => !prev)}
              recentlyAdded={recentlyAdded}
              handleRecentlyAdded={handleRecentlyAddedChange}
              categoryOptions={subCategories}
              selectedCategory={activeSubCategory}
              handelSelectedCategory={handleSubCategoryChange}
              enableClearFilter={isAnyFilterApplied}
              handleClearFilter={clearFilters}
            />
          )}

          <div className="course-main">
            {!onlyOneCourse && (
              <div className="filter-header">
                <button
                  type="button"
                  className="filter-button"
                  onClick={() => setToggleFilter((prev) => !prev)}
                  aria-expanded={toggleFilter}
                  aria-controls="filter-sidebar"
                  aria-label={toggleFilter ? "Hide filters" : "Show filters"}
                  title={toggleFilter ? "Hide filters" : "Show filters"}
                >
                  <h4>Filter</h4>
                  <span aria-hidden="true">
                    <FilterListIcon />
                  </span>
                </button>

                <SearchBar
                  searchTerm={searchTerm}
                  setSearchTerm={handleSearchQueryChange}
                  placeholder="Search course..."
                  inputRef={inputRef}
                />
              </div>
            )}

            {activeSubCategory === "All" &&
              Object.values(processedCourses).every((c) => c.length === 0) && (
                <NoResultFound searchTerm={debouncedSearch} style={{ marginTop: "2rem" }} />
              )}

            <CourseList
              processedCourses={processedCourses}
              selectedSubCategory={activeSubCategory}
              searchQuery={debouncedSearch}
              category={categoryTitle}
              learnMoreText="Learn More"
              basePath={basePath}
              clientNavigation={clientNavigation}
            />
          </div>
        </div>

        <Footer />
      </section>
    </>
  );
};

export default CourseClient;
