// src/utils/url.ts

export const isAbsoluteUrl = (url: string): boolean => /^(http|https|\/)/.test(url);

export const normalizeUrl = (url: string, base?: string): string => {
  if (!base) return url;
  if (isAbsoluteUrl(url)) return url;
  return `${base}${url}`;
};

/**
 * Turns a relative path ("/img/a.png" or "img/a.png") into a full URL on `base`, joining with
 * exactly one "/" whether or not `base` ends with one or `src` starts with one.
 * Full http(s) URLs are returned as-is. Unlike `normalizeUrl`, a leading "/" is treated as
 * relative to `base`, which is what OG/canonical URLs need.
 */
export const toAbsoluteUrl = (src: string | undefined, base: string): string | undefined => {
  if (!src) return undefined;
  if (/^https?:\/\//.test(src)) return src;
  return `${base.replace(/\/+$/, "")}/${src.replace(/^\/+/, "")}`;
};
