import type { FlowNodeDatum } from "./Flow.types";

/**
 * Pure data-tree helpers. These never touch React elements, JSX, or the
 * DOM, so they are safe to import from either a Server Component (Flow.tsx,
 * to assemble the tree) or a Client Component (FlowClient.tsx, to flatten
 * it for measurement). Keeping them React/JSX-free is what makes them
 * environment-agnostic.
 */

/**
 * Wraps one or more top-level items under a single synthetic root so the
 * layout algorithm always has one hierarchy to work with. The synthetic
 * root is never rendered as a card.
 */
export function buildRoot(items: FlowNodeDatum[]): FlowNodeDatum {
  if (items.length === 1) return items[0];
  return {
    id: "__flow-root__",
    content: null,
    children: items,
    isVirtual: true,
  };
}

/** Flattens the data tree into a list, used for the offscreen measurement pass. */
export function flattenTree(root: FlowNodeDatum): FlowNodeDatum[] {
  const out: FlowNodeDatum[] = [];
  const walk = (n: FlowNodeDatum) => {
    if (!n.isVirtual) out.push(n);
    n.children.forEach(walk);
  };
  walk(root);
  return out;
}
