"use client";

import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import { useEffect, useMemo, useRef, useState } from "react";
import { PageHeader } from "~/components/PageLayout/PageLayout";
import SearchBar from "~/components/SearchBar/SearchBar";
import CategoryCard from "./CategoryCard";
import { LearnCollection } from "./LearnPage";
import "./LearnPage.css";

interface Props {
  collections: LearnCollection[];
}

export default function LearnPageClient({ collections }: Props) {
  const [searchTerm, setSearchTerm] = useState("");
  const [selectedField, setSelectedField] = useState("all");
  const [isFieldMenuOpen, setIsFieldMenuOpen] = useState(false);
  const fieldMenuRef = useRef<HTMLDivElement>(null);

  const fieldOptions = useMemo(
    () => ["all", ...Array.from(new Set(collections.map((collection) => collection.field))).sort()],
    [collections],
  );

  const filteredCollections = useMemo(() => {
    const query = searchTerm.trim().toLowerCase();

    return collections.filter(
      (collection) =>
        (selectedField === "all" || collection.field === selectedField) &&
        (!query ||
          collection.title.toLowerCase().includes(query) ||
          collection.field.toLowerCase().includes(query)),
    );
  }, [collections, searchTerm, selectedField]);

  const hasCollections = collections.length > 0;
  const hasResults = filteredCollections.length > 0;
  const selectedFieldLabel = selectedField === "all" ? "All fields" : selectedField;

  useEffect(() => {
    const handlePointerDown = (event: PointerEvent) => {
      if (!fieldMenuRef.current?.contains(event.target as Node)) {
        setIsFieldMenuOpen(false);
      }
    };

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setIsFieldMenuOpen(false);
      }
    };

    document.addEventListener("pointerdown", handlePointerDown);
    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("pointerdown", handlePointerDown);
      document.removeEventListener("keydown", handleKeyDown);
    };
  }, []);

  const handleFieldSelect = (field: string) => {
    setSelectedField(field);
    setIsFieldMenuOpen(false);
  };

  return (
    <>
      <PageHeader
        badge="Learn"
        title="Browse Guides & Tutorials"
        description={
          <>
            Choose a collection to start learning. Every collection contains structured
            documentation, tutorials, guides, and practical resources.
          </>
        }
      >
        {hasCollections && (
          <div className="lp-filter-controls">
            <div className="lp-search-wrap">
              <SearchBar
                searchTerm={searchTerm}
                setSearchTerm={setSearchTerm}
                placeholder="Search collections…"
                inputId="lp-search-input"
                ariaControls="lp-grid"
              />
            </div>

            <div className="lp-select" ref={fieldMenuRef}>
              <button
                type="button"
                className="lp-select-trigger"
                aria-haspopup="listbox"
                aria-expanded={isFieldMenuOpen}
                aria-controls="lp-field-options"
                onClick={() => setIsFieldMenuOpen((isOpen) => !isOpen)}
              >
                <span>{selectedFieldLabel}</span>
                <span
                  className={`lp-select-arrow${isFieldMenuOpen ? " is-open" : ""}`}
                  aria-hidden="true"
                >
                  <ExpandMoreIcon />
                </span>
              </button>

              {isFieldMenuOpen && (
                <ul
                  id="lp-field-options"
                  className="lp-select-menu"
                  role="listbox"
                  aria-label="Fields"
                >
                  {fieldOptions.map((field) => {
                    const isSelected = selectedField === field;

                    return (
                      <li key={field} role="presentation">
                        <button
                          type="button"
                          className={`lp-select-option${isSelected ? " is-selected" : ""}`}
                          role="option"
                          aria-selected={isSelected}
                          onClick={() => handleFieldSelect(field)}
                        >
                          <span>{field === "all" ? "All fields" : field}</span>
                          {isSelected && <span aria-hidden="true">✓</span>}
                        </button>
                      </li>
                    );
                  })}
                </ul>
              )}
            </div>
          </div>
        )}
      </PageHeader>

      {!hasCollections ? (
        <div className="lp-empty" role="status">
          <h2 className="lp-empty-title">No collections yet</h2>

          <p className="lp-empty-text">
            Check back soon. New documentation collections are on the way.
          </p>
        </div>
      ) : hasResults ? (
        <ul id="lp-grid" className="page-grid lp-grid" aria-label="Documentation collections">
          {filteredCollections.map((collection) => (
            <li key={collection.slug} className="page-grid-item">
              <CategoryCard
                title={collection.title}
                img={collection.img}
                field={collection.field}
                totalCourses={collection.totalCourses}
                slug={collection.slug}
                href={collection.href}
              />
            </li>
          ))}
        </ul>
      ) : (
        <div className="lp-empty" role="status">
          <h2 className="lp-empty-title">No matches for {searchTerm}</h2>

          <p className="lp-empty-text">
            Try a different search term or browse the full list of collections.
          </p>
        </div>
      )}
    </>
  );
}
