"use client";

import { type RefObject, useEffect, useRef, useState } from "react";

export function useReadingProgress(contentRef: RefObject<HTMLElement | null>) {
  const [progress, setProgress] = useState(0);

  const last = useRef(-1);

  useEffect(() => {
    const content = contentRef.current;
    if (!content) return;

    let contentTop = 0;
    let total = 1;

    const measure = () => {
      const rect = content.getBoundingClientRect();

      contentTop = window.scrollY + rect.top;
      total = Math.max(content.offsetHeight - window.innerHeight, 1);
    };

    const update = () => {
      const current = Math.min(Math.max(window.scrollY - contentTop, 0), total);

      const next = Math.round((current / total) * 100);

      if (next !== last.current) {
        last.current = next;
        setProgress(next);
      }
    };

    measure();
    update();

    const resizeObserver = new ResizeObserver(() => {
      measure();
      update();
    });

    resizeObserver.observe(content);

    window.addEventListener("scroll", update, { passive: true });
    window.addEventListener("resize", measure);

    return () => {
      resizeObserver.disconnect();
      window.removeEventListener("scroll", update);
      window.removeEventListener("resize", measure);
    };
  }, [contentRef]);

  return progress;
}

