// syntaxResource.ts

import { transformerColorizedBrackets } from "@shikijs/colorized-brackets";
import { transformerStyleToClass } from "@shikijs/transformers";
import { codeToHtml } from "shiki";
import "./generated-syntax-themes.css";
import type { Language } from "./Language";
import { SYNTAX_THEMES } from "./syntax-themes";

const SHIKI_THEMES = Object.fromEntries(
  Object.entries(SYNTAX_THEMES).map(([id, theme]) => [id, theme.shiki]),
);

export async function getCode(url: string) {
  const res = await fetch(url);

  if (!res.ok) {
    return `Failed to load file (${res.status})`;
  }

  return res.text();
}

export async function getHighlightedHtml(code: string, lang: Language) {
  // Fresh instance per call — keeps CSS scoped to this snippet only,
  // safe under concurrent server-component renders.
  const toClass = transformerStyleToClass({
    classPrefix: "__pinktra_",
  });

  const html = await codeToHtml(code, {
    lang,
    themes: SHIKI_THEMES,
    defaultColor: false,
    cssVariablePrefix: "--pinktra-",
    transformers: [
      // Comment notations, e.g. `// [!code ++]`, `// [!code highlight]`
      // transformerNotationDiff(),
      // transformerNotationHighlight(),
      // transformerNotationWordHighlight(),
      // transformerNotationFocus(),
      // transformerNotationErrorLevel(),

      // Code-fence meta string, e.g. ```ts {1,3-4}` or ```ts /word/`
      // transformerMetaHighlight(),
      // transformerMetaWordHighlight(),

      // Rendering helpers
      // transformerRenderWhitespace(),
      // transformerRenderIndentGuides(),
      // transformerRemoveLineBreak(),
      // transformerRemoveNotationEscape(),
      // transformerCompactLineOptions(),

      // Color Brackets
      transformerColorizedBrackets(),

      // Must run last: converts whatever inline styles remain into
      // real CSS classes so the stylesheet below can be extracted.
      toClass,
    ],
  });
  const css = toClass.getCSS();

  return { html, css };
}

export interface SyntaxData {
  code: string;
  html: string;
  css: string;
}

interface GetSyntaxDataInput {
  /** Literal source, already resolved by the caller (children/code prop). */
  code?: string;
  /** Already-normalized URL to fetch source from, when no literal code was given. */
  src?: string;
  lang: Language;
}

/**
 * Resolves the source (literal or fetched) and highlights it, in one promise.
 * Built so a sync Server Component can create this promise and hand it to a
 * Client Component, which unwraps it with React's `use()`.
 */
export async function getSyntaxData({ code, src, lang }: GetSyntaxDataInput): Promise<SyntaxData> {
  const sourceCode = code !== undefined ? code : src ? await getCode(src) : "";

  if (!sourceCode) {
    return { code: "", html: "", css: "" };
  }

  const { html, css } = await getHighlightedHtml(sourceCode.trim(), lang);

  return { code: sourceCode, html, css };
}
