import styles from "./ContentSkeleton.module.css";

interface ContentSkeletonProps {
  compact?: boolean;
}

export function ContentSkeleton({ compact = false }: ContentSkeletonProps) {
  return (
    <div
      className={`${styles.articleSkeleton}${compact ? ` ${styles.compact}` : ""}`}
      aria-hidden="true"
    >
      <div className={`${styles.shimmer} ${styles.kicker}`} />
      <div className={`${styles.shimmer} ${styles.articleTitle}`} />
      <div className={`${styles.shimmer} ${styles.articleLine}`} />
      <div className={`${styles.shimmer} ${styles.articleLine} ${styles.lineWide}`} />
      <div className={`${styles.shimmer} ${styles.articleLine} ${styles.lineShort}`} />
      <div className={`${styles.shimmer} ${styles.sectionTitle}`} />
      <div className={`${styles.shimmer} ${styles.articleLine} ${styles.lineWide}`} />
      <div className={`${styles.shimmer} ${styles.articleLine}`} />
      <div className={`${styles.shimmer} ${styles.articleLine} ${styles.lineShort}`} />
    </div>
  );
}
