"use client";

import React from "react";
import { useTabsContext } from "./TabsContext";

export interface TabPanelProps {
  children: React.ReactNode;
  /** Extra class name(s) merged with the base "react-tabs__tab-panel" class. */
  className?: string;
  /** Overrides the Tabs-level selectedTabPanelClassName for this specific panel. */
  selectedClassName?: string;
  /** Forces this single panel to render its content even when not selected. */
  forceRender?: boolean;
  /** Overrides the auto-generated id (also used to build aria-labelledby on the tab). */
  id?: string;
  /**
   * @internal Injected automatically by Tabs via cloneElement based on
   * position among its TabPanel children. Do not pass this manually.
   */
  index?: number;
}

function TabPanelImpl({
  children,
  className,
  selectedClassName,
  forceRender = false,
  id,
  index,
}: TabPanelProps) {
  const { selectedIndex, forceRenderTabPanel, idPrefix, selectedTabPanelClassName } =
    useTabsContext("TabPanel");

  const resolvedIndex = index ?? 0;
  const isSelected = resolvedIndex === selectedIndex;

  const panelId = id ?? `${idPrefix}-panel-${resolvedIndex}`;
  const tabId = `${idPrefix}-tab-${resolvedIndex}`;

  const classes = ["react-tabs__tab-panel", className];
  if (isSelected) classes.push(selectedClassName || selectedTabPanelClassName);

  // Lazy by default: only the selected panel mounts its children, unless
  // forced globally (Tabs.forceRenderTabPanel) or locally (TabPanel.forceRender).
  // This preserves state correctly for the active panel while avoiding the
  // cost of mounting every panel's contents up front.
  const shouldRenderContent = isSelected || forceRender || forceRenderTabPanel;

  return (
    <div
      role="tabpanel"
      id={panelId}
      aria-labelledby={tabId}
      className={classes.filter(Boolean).join(" ")}
    >
      {shouldRenderContent ? children : null}
    </div>
  );
}

TabPanelImpl.displayName = "TabPanel";

export const TabPanel = React.memo(TabPanelImpl) as React.MemoExoticComponent<
  typeof TabPanelImpl
> & { tabsRole: string };
TabPanel.displayName = "TabPanel";
// See Tab.tsx for why this is a string marker rather than a reference check.
TabPanel.tabsRole = "TabPanel";
