"use client";

import Image from "next/image";
import { useEffect, useState } from "react";
import pdfImg from "~/assets/pdf/pdf.png";
import Media from "../Media/Media";
import styles from "./style.module.css";

interface PDFViewProps {
  link: string;
  heading?: boolean;
  headingName?: string;
  type?: "pdf" | "img";
}

const PDF: React.FC<PDFViewProps> = ({
  link,
  heading = false,
  headingName = "Reference",
  type = "pdf",
}) => {
  const [images, setImages] = useState<string[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (type !== "img") return;
    if (typeof window === "undefined") return;

    let mounted = true;

    const renderPdfAsImages = async () => {
      try {
        setLoading(true);
        setError(null);

        const pdfjs = await import("pdfjs-dist");

        pdfjs.GlobalWorkerOptions.workerSrc = new URL(
          "pdfjs-dist/build/pdf.worker.mjs",
          import.meta.url,
        ).toString();

        const pdf = await pdfjs.getDocument({
          url: link,
        }).promise;

        const pageImages: string[] = [];

        for (let pageNumber = 1; pageNumber <= pdf.numPages; pageNumber++) {
          const page = await pdf.getPage(pageNumber);

          const viewport = page.getViewport({
            scale: 2,
          });

          const canvas = document.createElement("canvas");
          const context = canvas.getContext("2d");

          if (!context) continue;

          canvas.width = viewport.width;
          canvas.height = viewport.height;

          await page.render({
            canvas,
            canvasContext: context,
            viewport,
          }).promise;

          pageImages.push(canvas.toDataURL("image/png"));
        }

        if (mounted) {
          setImages(pageImages);
        }
      } catch (error) {
        console.error("Failed to render PDF:", error);

        if (mounted) {
          setImages([]);
          setError("Failed to load PDF");
        }
      } finally {
        if (mounted) {
          setLoading(false);
        }
      }
    };

    renderPdfAsImages();

    return () => {
      mounted = false;
    };
  }, [link, type]);

  if (type === "img") {
    return (
      <div className={styles.pdf_glass_item}>
        {heading && <p className={styles.name}>{headingName}</p>}

        <div className={styles.image_container}>
          {loading && <div className={styles.loading}>⏳ Loading PDF pages...</div>}

          {!loading && error && (
            <div className={styles.error}>
              <div className={styles.pdf_info}>
                <Image
                  className={styles.icon}
                  src={pdfImg}
                  alt="pdf icon"
                  width={40}
                  placeholder="blur"
                />

                <p className={styles.url}>Failed to Load PDF</p>
              </div>
            </div>
          )}

          {!loading && !error && images.length > 0 && <Media type="img" src={images} />}
        </div>
      </div>
    );
  }

  return (
    <div className={styles.pdf_glass_item}>
      {heading && <p className={styles.name}>{headingName}</p>}

      <a href={link} target="_blank" rel="noopener noreferrer" className={styles.pdf}>
        <div className={styles.pdf_info}>
          <Image
            className={styles.icon}
            src={pdfImg}
            alt="pdf icon"
            width={40}
            placeholder="blur"
          />

          <p className={styles.url}>{link.substring(link.lastIndexOf("/") + 1)}</p>
        </div>
      </a>
    </div>
  );
};

export default PDF;
