import { parseFlowChildren } from "./Flow.parse";
import { buildRoot } from "./Flow.tree";
import type { FlowProps } from "./Flow.types";
import { FlowClient } from "./FlowClient";
import { FlowItem } from "./FlowItem";

/**
 * <Flow> is a Server Component. It is the *only* place where the raw
 * <Flow.Item> JSX tree is inspected, because it's the only place where
 * that inspection is guaranteed to happen before any Server -> Client
 * serialization occurs. It converts the JSX into a plain data tree and
 * hands that tree — not JSX — to <FlowClient>, the sole "use client"
 * boundary in this component.
 *
 * The public authoring API is unchanged:
 *
 *   <Flow layout="vertical">
 *     <Flow.Item>
 *       Root
 *       <Flow.Item>Child A</Flow.Item>
 *       <Flow.Item>Child B</Flow.Item>
 *     </Flow.Item>
 *   </Flow>
 */
function FlowBase({ layout = "vertical", className, children }: FlowProps) {
  const items = parseFlowChildren(children);
  const root = buildRoot(items);

  return <FlowClient tree={root} layout={layout} className={className} />;
}

export const Flow = FlowBase as typeof FlowBase & { Item: typeof FlowItem };
Flow.Item = FlowItem;

export type { FlowItemProps, FlowLayout, FlowProps } from "./Flow.types";
