import { Suspense } from "react";
import { normalizeUrl } from "~/utils/url";
import MathsInner from "./MathsInner";
import { getMathData } from "./mathResource";

export interface MathsProps {
  children?: string;
  src?: string;
  domain?: string;
  type?: "inline" | "block";
}

export default function Maths({ children, src, domain, type }: MathsProps) {
  if (children && src) {
    return <div>❌ Use either children or src.</div>;
  }

  if (!children && !src) {
    return <div>❌ Missing children or src.</div>;
  }

  const formula = children ?? getMathData(normalizeUrl(src!, domain));

  return (
    <Suspense fallback={<span className={`wf-maths wf-maths--${type ?? "block"}`} />}>
      <MathsInner formula={formula} type={type} />
    </Suspense>
  );
}
