// ui/MarkdownViewer/MarkdownRenderer.tsx
"use client";

/* eslint-disable react-hooks/static-components -- MDX compilation intentionally creates a component per content source. */
import type { MDXComponents } from "mdx/types";
import { Suspense, use, useMemo } from "react";
import { ContentSkeleton } from "~/page/Loading/ContentSkeleton";
import { getMdxComponents, type MdxMediaOptions } from "./markdown-components";
import { parseMarkdown } from "./parseMarkdown";

interface MarkdownRendererProps extends MdxMediaOptions {
  content: string | Promise<string>;
  components?: MDXComponents;
}

// Single renderer for both .md and .mdx (and inline content/mdxContent) —
// plain markdown is a subset of MDX, so this compiles either one through
// the MDX pipeline and maps it to the design-system components.
export function MarkdownRenderer({
  content: contentProp,
  domain,
  groupImg,
  movie,
  tableTextAlign,
  tableTextWrap,
  components,
}: MarkdownRendererProps) {
  const content = typeof contentProp === "string" ? contentProp : use(contentProp);

  const Component = useMemo(() => parseMarkdown(content), [content]);

  const resolvedComponents = useMemo(() => {
    const baseComponents = getMdxComponents({
      domain,
      groupImg,
      movie,
      tableTextAlign,
      tableTextWrap,
    });

    return components ? { ...baseComponents, ...components } : baseComponents;
  }, [domain, groupImg, movie, tableTextAlign, tableTextWrap, components]);

  return (
    <Suspense
      fallback={
        <div role="status" aria-busy="true" aria-label="Loading document">
          <ContentSkeleton compact />
        </div>
      }
    >
      <Component components={resolvedComponents} />
    </Suspense>
  );
}
