// ui/MarkdownViewer/markdown-components.tsx
import type { MDXComponents } from "mdx/types";
import type { ComponentPropsWithoutRef } from "react";
import type { PageBuilderOptions } from "~/model/course_model";
import A from "~/ui/A/A";
import { FileItem, FileTree, FolderItem } from "~/ui/FileTree";
import { Flow } from "~/ui/Flow";
import H1 from "~/ui/H1/H1";
import H2 from "~/ui/H2/H2";
import H3 from "~/ui/H3/H3";
import { Code } from "~/ui/HL/HL";
import List from "~/ui/List/List";
import Maths from "~/ui/Maths/Maths";
import Media from "~/ui/Media/Media";
import Mermaid from "~/ui/Mermaid/Mermaid";
import Note from "~/ui/Note/Note";
import Para from "~/ui/Para/Para";
import Quote from "~/ui/Quote/Quote";
import Syntax from "~/ui/Syntax/Syntax";
import Table from "~/ui/Table/Table";
import { Tab, TabList, TabPanel, Tabs } from "~/ui/Tabs/Tabs";
import { Timeline, TimelineItem } from "~/ui/Timeline/Timeline";
import { type Language, LANGUAGE_ALIASES } from "../Syntax/Language";
import { isNoteType } from "./remark-plugins";

export {
  remarkCodeTitle,
  remarkContainerNotes,
  remarkGithubAlerts,
  remarkInlineContainerNotes,
} from "./remark-plugins";

// -----------------------------------------------------------------------
// Media-related props that the renderer receives from the caller (page
// builder options / RemoteFile) and that need to reach every place an
// <img> or <Media> tag can appear inside a .md or .mdx document — both
// the markdown-image shorthand (![alt](src)) and an author-written
// <Media /> JSX tag need the same `domain`, `groupImg`, `movie`,
// `tableTextAlign`, `tableTextWrap` values.
// -----------------------------------------------------------------------
export type MdxMediaOptions = Pick<
  PageBuilderOptions,
  "groupImg" | "movie" | "tableTextAlign" | "tableTextWrap"
> & {
  domain?: string;
};

function resolveLanguage(lang?: string): Language {
  if (!lang) {
    return "cmd";
  }

  const normalized = lang.toLowerCase();

  return LANGUAGE_ALIASES[normalized] || "cmd";
}

// -----------------------------------------------------------------------
// 1. Named custom components — used when .mdx authors write JSX tags
//    directly, e.g. <Title>, <Note>, <Flow.Item>, <H1>, <Table>, etc.
//    `Media` is intentionally left out here — it needs the caller's
//    domain/groupImg/movie/tableTextAlign/tableTextWrap, so it's built
//    per-render in getMdxComponents() below instead of statically.
// -----------------------------------------------------------------------
const customComponents: MDXComponents = {
  Title: () => null,
  H1,
  H2,
  H3,
  Para,
  Code,
  Quote,
  List,
  "List.Item": List.Item,
  Syntax,
  Table,
  A,
  Note,
  Maths,
  Flow,
  "Flow.Item": Flow.Item,
  Timeline,
  TimelineItem,
  FileTree,
  FileItem,
  FolderItem,
  Tabs,
  Tab,
  TabList,
  TabPanel,
  Mermaid,
};

// -----------------------------------------------------------------------
// 2. Default markdown syntax mapping — lets plain markdown written in
//    .mdx (# heading, - item, > quote, **bold**, ```code```, tables,
//    images, links, math, mermaid fences, `::: type` / `> [!TYPE]`
//    notes, etc.) render through the same design-system components as
//    the named tags above. Logic mirrors the react-markdown
//    MarkdownRenderer reference exactly (plus the note handling, which
//    that reference never had).
// -----------------------------------------------------------------------
const markdownComponents: MDXComponents = {
  // # / ## / ### -> H1 / H2 / H3  (falls back to H3 for h4-h6, no
  // deeper heading component exists yet)
  h1: H1,
  h2: H2,
  h3: H3,
  h4: H3,
  h5: H3,
  h6: H3,

  // Paragraph text
  p: Para,

  // Links [text](url)
  a: (props: ComponentPropsWithoutRef<"a">) => <A link={props.href ?? ""}>{props.children}</A>,

  // Blockquote (> quote)
  blockquote: Quote,

  // <note type="..."> — synthesized by remarkContainerNotes (::: tip)
  // and remarkGithubAlerts (> [!NOTE]) above; renders through the same
  // Note component as an author-written <Note type="tip"> JSX tag.
  note: (props: ComponentPropsWithoutRef<"div"> & { type?: string }) => (
    <Note type={props.type && isNoteType(props.type) ? props.type : "note"}>{props.children}</Note>
  ),

  // Lists: - item / 1. item
  ul: (props) => <List type="unordered">{props.children}</List>,
  ol: (props) => <List type="ordered">{props.children}</List>,
  li: (props) => <List.Item>{props.children}</List.Item>,

  // Table (| a | b |) — Table wraps its own thead/tbody/tr/td
  // internally, so the sub-elements don't need remapping.
  table: (props) => <Table>{props.children}</Table>,

  // Inline `code` and fenced ```code blocks``` — branches into Maths
  // (math / math-display), Mermaid, syntax-highlighted Syntax, or
  // plain inline Code, exactly like the reference renderer. `title`
  // arrives as a real prop courtesy of remarkCodeTitle.
  code: (props: ComponentPropsWithoutRef<"code"> & { title?: string }) => {
    const { children, className = "", title } = props;
    const code = String(children).replace(/\n$/, "");

    if (className.includes("language-math")) {
      return <Maths type={className.includes("math-display") ? "block" : "inline"}>{code}</Maths>;
    }

    const match = /language-(\w+)/.exec(className);

    if (match?.[1].toLowerCase() === "mermaid") {
      return <Mermaid code={code} title={title} />;
    }

    if (!match) {
      return <Code>{code}</Code>;
    }

    return <Syntax code={code} language={resolveLanguage(match[1])} title={title} />;
  },

  // Fenced code blocks are wrapped in <pre><code>...</code></pre> by
  // markdown; unwrap pre so the `code` renderer above isn't double-boxed.
  pre: (props) => <>{props.children}</>,

  // Horizontal rule ---
  hr: () => <div className="my-10 border-t border-zinc-800" />,

  // Bold / italic
  strong: (props) => <strong className="font-bold text-white">{props.children}</strong>,
  em: (props) => <em className="italic text-zinc-300">{props.children}</em>,

  div: (props) => <>{props.children}</>,
};

// -----------------------------------------------------------------------
// 3. Media + img — built per-render because both the markdown image
//    shorthand (![alt](src)) and an author-written <Media /> JSX tag
//    need the caller's domain/groupImg/movie/tableTextAlign/
//    tableTextWrap, and those only exist once MarkdownViewer/RemoteFile
//    calls in with real values. `movie` defaults to true for the plain
//    ![alt](src) shorthand since that path never lets the author pass
//    it explicitly, matching the previous MarkdownRenderer behaviour.
// -----------------------------------------------------------------------
function createMediaComponents(options: MdxMediaOptions = {}): MDXComponents {
  const { domain, groupImg, movie, tableTextAlign, tableTextWrap } = options;

  return {
    img: (props: ComponentPropsWithoutRef<"img">) => {
      const src = typeof props.src === "string" ? props.src : "";

      return (
        <Media
          src={src}
          alt={props.alt ?? ""}
          domain={domain}
          groupImg={groupImg}
          movie={movie ?? true}
          tableTextAlign={tableTextAlign}
          tableTextWrap={tableTextWrap}
        />
      );
    },
    Media: (props: ComponentPropsWithoutRef<typeof Media>) => (
      <Media
        domain={domain}
        groupImg={groupImg}
        movie={movie}
        tableTextAlign={tableTextAlign}
        tableTextWrap={tableTextWrap}
        {...props}
      />
    ),
  };
}

// -----------------------------------------------------------------------
// 4. Merged export — markdown syntax first, named components layered on
//    top, media components last so they always win. Order matters only
//    where a key could collide (it doesn't here: lowercase html tags vs
//    PascalCase component names), so `# Heading`, `<H1>Heading</H1>`,
//    `![alt](src)`, and `<Media src="..." />` all work side by side in
//    the same .md/.mdx file.
// -----------------------------------------------------------------------
export function getMdxComponents(options: MdxMediaOptions = {}): MDXComponents {
  return {
    ...markdownComponents,
    ...customComponents,
    ...createMediaComponents(options),
  };
}

export const mdxComponents: MDXComponents = getMdxComponents();

// -----------------------------------------------------------------------
// 5. Next.js MDX convention: lets callers merge in additional custom
//    components per-page on top of the defaults, without losing
//    markdown or named-component support.
//
//    app/mdx-components.tsx:
//      export { useMDXComponents } from "~/ui/MarkdownViewer/markdown-components";
// -----------------------------------------------------------------------
export function useMDXComponents(components?: MDXComponents): MDXComponents {
  return {
    ...mdxComponents,
    ...components,
  };
}

export default mdxComponents;
