// ui/MarkdownViewer/parseMarkdown.tsx
"use client";

import { evaluateSync, type EvaluateOptions } from "@mdx-js/mdx";
import { useMDXComponents } from "@mdx-js/react";
import * as runtime from "react/jsx-runtime";
import remarkDirective from "remark-directive";
import remarkGfm from "remark-gfm";
import remarkMath from "remark-math";

import {
  remarkCodeTitle,
  remarkContainerNotes,
  remarkGithubAlerts,
  remarkInlineContainerNotes,
} from "./markdown-components";
import type { Frontmatter, MDXComponent } from "./types";

function ErrorFallback({ error }: { error: unknown }) {
  const message = error instanceof Error ? error.message : String(error);

  if (process.env.NODE_ENV !== "production") {
    return (
      <pre style={{ color: "crimson", whiteSpace: "pre-wrap" }}>MDX parse error: {message}</pre>
    );
  }

  return null;
}

export function parseMarkdown(source: string): MDXComponent {
  try {
    const evaluated = evaluateSync(source, {
      ...runtime,
      useMDXComponents,
      format: "mdx",
      // remarkDirective must run before remarkContainerNotes — it's what
      // turns `::: tip ... :::` (block form) into the containerDirective
      // node that remarkContainerNotes then rewrites into
      // `<note type="tip">`. remarkInlineContainerNotes is independent —
      // it catches the single-line `::: tip ... :::` shape that
      // remark-directive doesn't recognize as a fence at all.
      remarkPlugins: [
        remarkGfm,
        remarkMath,
        remarkDirective,
        remarkContainerNotes,
        remarkInlineContainerNotes,
        remarkGithubAlerts,
        remarkCodeTitle,
      ],
    } as EvaluateOptions);

    const Component = evaluated.default as MDXComponent;

    Component.frontmatter = (evaluated as { frontmatter?: Frontmatter }).frontmatter ?? {};

    return Component;
  } catch (error) {
    console.error(error);

    const Fallback = (() => <ErrorFallback error={error} />) as unknown as MDXComponent;

    Fallback.frontmatter = {};

    return Fallback;
  }
}
