import { LANGUAGE, LANGUAGE_ALIASES, type Language } from "../Syntax/Language";
import type { FileIconKind } from "./types";

/**
 * Returns the lowercase extension of a filename, without the leading dot.
 * Handles dotfiles and multi-dot names (e.g. "_meta.js" -> "js",
 * "index.mdx" -> "mdx", ".gitignore" -> "gitignore", "README" -> "").
 */
export function getExtension(filename: string): string {
  const base = filename.trim();
  const lastDot = base.lastIndexOf(".");

  if (lastDot <= 0) {
    // No dot, or a dotfile with no further extension (".env").
    return lastDot === 0 ? base.slice(1).toLowerCase() : "";
  }

  return base.slice(lastDot + 1).toLowerCase();
}

const EXTENSION_KIND_MAP: Record<string, FileIconKind> = {
  ts: "code",
  tsx: "code",
  js: "code",
  jsx: "code",
  mjs: "code",
  cjs: "code",
  json: "data",
  jsonc: "data",
  md: "doc",
  mdx: "doc",
  css: "style",
  scss: "style",
  sass: "style",
  less: "style",
  html: "markup",
  htm: "markup",
  svg: "image",
  png: "image",
  jpg: "image",
  jpeg: "image",
  gif: "image",
  webp: "image",
  ico: "image",
};

/**
 * Classifies a filename into a broad icon category. Unknown or missing
 * extensions fall back to a neutral generic-file icon rather than guessing.
 * Independent of `Language` — this only ever drives icon choice.
 */
export function getFileIconKind(filename: string): FileIconKind {
  const extension = getExtension(filename);
  return EXTENSION_KIND_MAP[extension] ?? "generic";
}

/**
 * Fallback when an extension has no entry in Syntax's own
 * `LANGUAGE_ALIASES` and isn't itself a valid `Language` id. Mirrors
 * Syntax's own plaintext handling — its aliases table already maps
 * txt/text/plain/plaintext to "cmd", so unknown extensions land there too.
 */
const FALLBACK_LANGUAGE: Language = "cmd";

const LANGUAGE_SET = new Set<string>(LANGUAGE);

/**
 * Derives the `Syntax` `language` prop from a filename's extension.
 *
 * Uses Syntax's own `LANGUAGE_ALIASES` table as the source of truth (so
 * this stays correct automatically if Syntax adds, renames, or re-aliases
 * languages later — nothing here duplicates that mapping). If an
 * extension has no alias entry but is already a valid `Language` id on
 * its own (e.g. "xml", "yaml", "toml" as literal ids), it's used as-is.
 * Only truly unknown extensions fall back to plaintext.
 */
export function getSyntaxLanguage(filename: string): Language {
  const extension = getExtension(filename);

  const alias = LANGUAGE_ALIASES[extension];
  if (alias) return alias;

  if (LANGUAGE_SET.has(extension)) return extension as Language;

  return FALLBACK_LANGUAGE;
}
