import { SITE_NAME, SITE_URL } from "./domain";
import { DEFAULT_IMAGE, DEFAULT_ROBOTS, type SEOOptions } from "./meta";

type Cleanup = () => void;

/**
 * Cleanups only undo what this helper changed, and only if nobody else has changed it since.
 * When the user leaves the page for a different route (e.g. /learn/... -> /), Next.js writes
 * the new page's title/meta first and our effect cleanup runs afterwards. Restoring a stale
 * snapshot at that point would overwrite the new page's tags.
 */

function upsertMeta(attr: "name" | "property", key: string, content?: string): Cleanup {
  if (!content) return () => {};

  let el = document.head.querySelector<HTMLMetaElement>(`meta[${attr}="${key}"]`);
  const created = !el;
  const previous = el?.getAttribute("content") ?? null;

  if (!el) {
    el = document.createElement("meta");
    el.setAttribute(attr, key);
    document.head.appendChild(el);
  }
  el.setAttribute("content", content);

  const target = el;
  return () => {
    if (created) {
      target.remove();
      return;
    }
    // Someone else (Next.js on navigation) already changed it: leave their value alone.
    if (target.getAttribute("content") !== content) return;
    if (previous !== null) target.setAttribute("content", previous);
  };
}

function upsertCanonical(href: string): Cleanup {
  let el = document.head.querySelector<HTMLLinkElement>('link[rel="canonical"]');
  const created = !el;
  const previous = el?.getAttribute("href") ?? null;

  if (!el) {
    el = document.createElement("link");
    el.setAttribute("rel", "canonical");
    document.head.appendChild(el);
  }
  el.setAttribute("href", href);

  const target = el;
  return () => {
    if (created) {
      target.remove();
      return;
    }
    if (target.getAttribute("href") !== href) return;
    if (previous !== null) target.setAttribute("href", previous);
  };
}

function addJsonLd(schemas: object[]): Cleanup {
  const nodes = schemas.map((schema) => {
    const script = document.createElement("script");
    script.type = "application/ld+json";
    script.dataset.clientSeo = "true";
    script.text = JSON.stringify(schema);
    document.head.appendChild(script);
    return script;
  });
  return () => nodes.forEach((node) => node.remove());
}

function setTitle(title: string): Cleanup {
  const previousTitle = document.title;
  document.title = title;

  return () => {
    // Only restore if the title is still ours; otherwise the next page already set its own.
    if (document.title === title) document.title = previousTitle;
  };
}

export function applyClientSeo(
  {
    title,
    description,
    path = "",
    image = DEFAULT_IMAGE,
    keywords,
    type = "article",
    robots = DEFAULT_ROBOTS,
  }: SEOOptions,
  jsonLd: object[] = [],
): Cleanup {
  const url = `${SITE_URL}${path}`;

  const cleanups: Cleanup[] = [
    setTitle(title),

    upsertMeta("name", "description", description),
    upsertMeta("name", "keywords", keywords),
    upsertMeta("name", "robots", robots),
    upsertCanonical(url),

    upsertMeta("property", "og:title", title),
    upsertMeta("property", "og:description", description),
    upsertMeta("property", "og:type", type),
    upsertMeta("property", "og:url", url),
    upsertMeta("property", "og:site_name", SITE_NAME),
    upsertMeta("property", "og:locale", "en_US"),
    upsertMeta("property", "og:image", image),
    upsertMeta("property", "og:image:width", "1200"),
    upsertMeta("property", "og:image:height", "630"),

    upsertMeta("name", "twitter:card", "summary_large_image"),
    upsertMeta("name", "twitter:title", title),
    upsertMeta("name", "twitter:description", description),
    upsertMeta("name", "twitter:image", image),

    addJsonLd(jsonLd),
  ];

  return () => cleanups.forEach((cleanup) => cleanup());
}
