export interface MermaidSourceData {
  source?: string;
  error?: string;
}

export async function getMermaidSource(url: string): Promise<MermaidSourceData> {
  try {
    const res = await fetch(url);

    if (!res.ok) {
      return { error: `Failed to load file (${res.status})` };
    }

    const text = await res.text();

    return { source: text.trim() };
  } catch (err) {
    return { error: err instanceof Error ? err.message : "Failed to load diagram source." };
  }
}
