"use client";

import React, { Children, cloneElement, isValidElement, useCallback, useRef } from "react";
import { useTabsContext } from "./TabsContext";

export interface TabListProps {
  children: React.ReactNode;
  /** Extra class name(s) merged with the base "react-tabs__tab-list" class. */
  className?: string;
}

function TabListImpl({ children, className }: TabListProps) {
  // Pulled for context validation only (throws if used outside <Tabs>).
  useTabsContext("TabList");

  const listRef = useRef<HTMLDivElement>(null);

  const getEnabledIndex = useCallback(
    (startIndex: number, direction: 1 | -1, tabs: NodeListOf<HTMLElement>): number => {
      if (tabs.length === 0) return startIndex;
      let index = startIndex;
      for (let i = 0; i < tabs.length; i++) {
        index = (index + direction + tabs.length) % tabs.length;
        if (tabs[index]?.getAttribute("aria-disabled") !== "true") {
          return index;
        }
      }
      return startIndex;
    },
    [],
  );

  const focusTabAt = useCallback((tabs: NodeListOf<HTMLElement>, index: number) => {
    tabs[index]?.focus();
  }, []);

  const handleKeyDown = useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      const node = listRef.current;
      if (!node) return;

      const tabs = node.querySelectorAll<HTMLElement>('[role="tab"]');
      if (tabs.length === 0) return;

      const activeElement = document.activeElement as HTMLElement | null;
      const activeIndexAttr = activeElement?.getAttribute("data-index");
      const currentIndex =
        activeIndexAttr !== null && activeIndexAttr !== undefined ? Number(activeIndexAttr) : 0;

      switch (event.key) {
        case "ArrowRight": {
          event.preventDefault();
          focusTabAt(tabs, getEnabledIndex(currentIndex, 1, tabs));
          break;
        }
        case "ArrowLeft": {
          event.preventDefault();
          focusTabAt(tabs, getEnabledIndex(currentIndex, -1, tabs));
          break;
        }
        case "Home": {
          event.preventDefault();
          const firstEnabled =
            tabs[0]?.getAttribute("aria-disabled") === "true" ? getEnabledIndex(0, 1, tabs) : 0;
          focusTabAt(tabs, firstEnabled);
          break;
        }
        case "End": {
          event.preventDefault();
          const lastIndex = tabs.length - 1;
          const lastEnabled =
            tabs[lastIndex]?.getAttribute("aria-disabled") === "true"
              ? getEnabledIndex(lastIndex, -1, tabs)
              : lastIndex;
          focusTabAt(tabs, lastEnabled);
          break;
        }
        // Enter / Space are intentionally left to Tab's own onKeyDown so that
        // selection only ever happens through a single code path.
        default:
          break;
      }
    },
    [getEnabledIndex, focusTabAt],
  );

  // Inject a positional `index` prop into every element child. TabList's
  // contract is that its only children are Tab elements, so there is no
  // need to runtime-check component identity here — doing so was actually
  // the source of a real bug: identity checks (`child.type === Tab`, and
  // even a `tabsRole` marker) can be fooled by bundler/module duplication
  // in some Next.js setups, silently skipping index injection and making
  // every Tab fall back to index 0 (i.e. "everything appears selected").
  // Structural position has no such failure mode.
  const renderedChildren = Children.map(children, (child, position) => {
    if (!isValidElement(child)) {
      return child;
    }
    return cloneElement(child as React.ReactElement<{ index?: number }>, {
      index: position,
    });
  });

  return (
    <div
      ref={listRef}
      role="tablist"
      className={className ? `react-tabs__tab-list ${className}` : "react-tabs__tab-list"}
      onKeyDown={handleKeyDown}
    >
      {renderedChildren}
    </div>
  );
}

TabListImpl.displayName = "TabList";

export const TabList = React.memo(TabListImpl);
(TabList as unknown as { displayName: string }).displayName = "TabList";
