"use client";

import { use } from "react";

import type { tableTextAlign } from "./Table";
import type { TableData } from "./tableResource";

interface TableInnerProps {
  className: string;
  textAlign: tableTextAlign;
  dataPromise: Promise<TableData>;
}

export default function TableInner({ className, textAlign, dataPromise }: TableInnerProps) {
  const tableData = use(dataPromise);

  return (
    <div className={className}>
      <table>
        {tableData.error ? (
          <tbody>
            <tr>
              <td colSpan={999} style={{ textAlign: "center" }}>
                {tableData.error}
              </td>
            </tr>
          </tbody>
        ) : (
          <>
            <thead>
              <tr>
                {tableData.headers.map((header) => (
                  <th key={header}>{header}</th>
                ))}
              </tr>
            </thead>

            <tbody>
              {tableData.rows.map((row, i) => (
                <tr key={i}>
                  {tableData.headers.map((header) => (
                    <td key={header} style={{ textAlign }}>
                      {row[header]}
                    </td>
                  ))}
                </tr>
              ))}
            </tbody>
          </>
        )}
      </table>
    </div>
  );
}
