"use client";

import React, {
  Children,
  cloneElement,
  isValidElement,
  useCallback,
  useId,
  useMemo,
  useState,
} from "react";
import { Tab } from "./Tab";
import { TabList } from "./TabList";
import { TabPanel } from "./TabPanel";
import { TabsContext, TabsContextValue } from "./TabsContext";
import "./react-tabs.scss";

const DEFAULT_SELECTED_TAB_CLASS = "react-tabs__tab--selected";
const DEFAULT_SELECTED_PANEL_CLASS = "react-tabs__tab-panel--selected";
const DEFAULT_DISABLED_CLASS = "react-tabs__tab--disabled";

export interface TabsProps {
  children: React.ReactNode;
  /** Extra class name(s) merged with the base "react-tabs" class. */
  className?: string;
  /** Initial selected index for uncontrolled usage. Ignored if `selectedIndex` is provided. */
  defaultIndex?: number;
  /** Selected index for controlled usage. When provided, Tabs no longer manages its own state. */
  selectedIndex?: number;
  /** Called whenever the selection changes, whether by click or keyboard. */
  onSelect?: (index: number, lastIndex: number, event: React.SyntheticEvent) => void;
  /** When true, every TabPanel renders its content up front instead of lazily. */
  forceRenderTabPanel?: boolean;
  /** Default class applied to the selected Tab; a Tab's own `selectedClassName` wins if set. */
  selectedTabClassName?: string;
  /** Default class applied to the selected TabPanel; a TabPanel's own `selectedClassName` wins if set. */
  selectedTabPanelClassName?: string;
  /** Default class applied to a disabled Tab; a Tab's own `disabledClassName` wins if set. */
  disabledClassName?: string;
  /** Forwarded ref to the root "react-tabs" div. */
  domRef?: React.Ref<HTMLDivElement>;
}

function TabsImpl({
  children,
  className,
  defaultIndex = 0,
  selectedIndex: controlledIndex,
  onSelect,
  forceRenderTabPanel = true,
  selectedTabClassName = DEFAULT_SELECTED_TAB_CLASS,
  selectedTabPanelClassName = DEFAULT_SELECTED_PANEL_CLASS,
  disabledClassName = DEFAULT_DISABLED_CLASS,
  domRef,
}: TabsProps) {
  const isControlled = controlledIndex !== undefined;
  const [uncontrolledIndex, setUncontrolledIndex] = useState(defaultIndex);
  const selectedIndex = isControlled ? (controlledIndex as number) : uncontrolledIndex;

  // Stable, SSR-safe id source (no Math.random / Date.now — no hydration mismatch).
  const idPrefix = useId();

  const handleSelectTab = useCallback(
    (index: number, event: React.SyntheticEvent) => {
      if (index === selectedIndex) return;

      if (!isControlled) {
        setUncontrolledIndex(index);
      }

      onSelect?.(index, selectedIndex, event);
    },
    [isControlled, onSelect, selectedIndex],
  );

  const contextValue = useMemo<TabsContextValue>(
    () => ({
      selectedIndex,
      onSelectTab: handleSelectTab,
      forceRenderTabPanel,
      idPrefix,
      selectedTabClassName,
      selectedTabPanelClassName,
      disabledClassName,
    }),
    [
      selectedIndex,
      handleSelectTab,
      forceRenderTabPanel,
      idPrefix,
      selectedTabClassName,
      selectedTabPanelClassName,
      disabledClassName,
    ],
  );

  // Inject a positional `index` prop into every TabPanel. Tabs' contract is:
  // first element child = TabList (rendered untouched), every element child
  // after that = a TabPanel. We deliberately do NOT check component identity
  // (no `child.type === TabPanel`, no marker property) — that was the actual
  // source of a real "select-all" bug: identity checks can silently fail
  // under some Next.js bundling setups, leaving every panel's index
  // undefined -> defaulting to 0 -> every panel reading as selected at once.
  // Structural position has no such failure mode.
  let hasSeenTabList = false;
  let panelPosition = 0;
  const renderedChildren = Children.map(children, (child) => {
    if (!isValidElement(child)) {
      return child;
    }

    if (!hasSeenTabList) {
      hasSeenTabList = true;
      return child;
    }

    const currentPosition = panelPosition;
    panelPosition += 1;
    return cloneElement(child as React.ReactElement<{ index?: number }>, {
      index: currentPosition,
    });
  });

  return (
    <TabsContext.Provider value={contextValue}>
      <div ref={domRef} className={className ? `react-tabs ${className}` : "react-tabs"}>
        {renderedChildren}
      </div>
    </TabsContext.Provider>
  );
}

TabsImpl.displayName = "Tabs";

type TabsComponent = React.MemoExoticComponent<typeof TabsImpl> & {
  TabList: typeof TabList;
  Tab: typeof Tab;
  TabPanel: typeof TabPanel;
};

const Tabs = React.memo(TabsImpl) as TabsComponent;
Tabs.TabList = TabList;
Tabs.Tab = Tab;
Tabs.TabPanel = TabPanel;
(Tabs as unknown as { displayName: string }).displayName = "Tabs";

export type { TabProps } from "./Tab";
export type { TabListProps } from "./TabList";
export type { TabPanelProps } from "./TabPanel";
export { Tab, TabList, TabPanel, Tabs };
