import type { FC, ReactNode } from "react";
import { Suspense } from "react";

import type { Language } from "./Language";

import { normalizeUrl } from "../../utils/url";
import { getSyntaxData } from "./syntaxResource";

import "./Syntax.css";
import SyntaxInner from "./SyntaxInner";

interface SyntaxProps {
  src?: string;
  code?: string;
  children?: ReactNode;
  title?: string;
  language?: Language;
  domain?: string;
}

const Syntax: FC<SyntaxProps> = ({
  src,
  code,
  children,
  title = "Code Snippet",
  language: lang = "cmd",
  domain,
}) => {
  const hasMultipleSources = [code, children, src].filter((v) => v !== undefined).length > 1;

  if (hasMultipleSources) {
    return <pre className="glass-table error-message">❌ Provide only one source.</pre>;
  }

  const inlineCode =
    code !== undefined ? code : typeof children === "string" ? children : undefined;

  if (inlineCode === undefined && !src) {
    return null;
  }

  const dataPromise = getSyntaxData({
    code: inlineCode,
    src: src ? normalizeUrl(src, domain) : undefined,
    lang,
  });

  return (
    <Suspense fallback={<div className="syntax-container syntax-preload" />}>
      <SyntaxInner title={title} dataPromise={dataPromise} />
    </Suspense>
  );
};

export { Syntax as CodeBlock };

export default Syntax;
