import { Children, isValidElement, type ReactElement, type ReactNode } from "react";

// Sibling directory per the project's actual layout (src/ui/Syntax,
// src/ui/FileTree). This is the ONLY place in the whole FileTree package
// that touches Syntax. Everything below FileTreeClient is 'use client'
// and never imports it.
import Syntax from "../Syntax/Syntax";

import type { CodeFile } from "./Context";
import { FileItem } from "./FileItem";
import { FileTreeClient } from "./FileTreeClient";
import { FolderItem } from "./FolderItem";
import type { FileEntry, FileTreeFileProps, FileTreeFolderProps, FileTreeProps } from "./types";
import { getSyntaxLanguage } from "./utils";

interface CollectedFileData {
  /** Every code file's pre-rendered `Syntax` output, for the editor pane. */
  codeFiles: CodeFile[];
  /** Every file, code or not, for the "download all as .zip" archive. */
  fileEntries: FileEntry[];
}

/**
 * `Syntax` is a Server Component. `FileTreeClient` (the interactive shell
 * that owns focus/selection state via hooks) has to be a Client Component,
 * and a Client Component can never `import` and render a Server Component
 * directly — React/Next has no way to execute server-only code from
 * inside client-bundled code.
 *
 * The fix is the standard RSC composition pattern: render `Syntax` here,
 * on the server, once per code `FileItem`, and collect every result into
 * a flat list keyed by the exact same path-based id each `FileItem`
 * computes for itself at render time (`${parentPath}/${name}`). By the
 * time it reaches the client boundary each entry is just an opaque,
 * already-resolved node — safe to hold in state, safe to render
 * unconditionally.
 *
 * The same walk also builds `fileEntries` — a flat list covering *every*
 * `FileItem` in the tree, not just code ones, keyed by a plain
 * slash-joined path (the same id with its single leading slash stripped)
 * — used to build the "download all as .zip" archive client-side. A file
 * with no `code` prop still gets an entry, just with empty content, so
 * the downloaded zip always mirrors the full tree structure.
 *
 * Every code file gets collected up front — including ones nested inside
 * folders that start closed, and ones no one has opened yet — for two
 * reasons: a client component can't call a server component later on
 * demand, and (just as importantly) `FileTreeClient` renders this entire
 * list into the DOM on first paint, exactly like folders already always
 * render their children and only toggle visibility via `inert` + a CSS
 * collapse (see the `.branch` reuse in FileTree.module.css). That's what
 * makes every file's source SSR/SEO-visible, not just whichever one
 * happens to be open.
 *
 * `Children.forEach` only knows each child is *some* `ReactElement`, so
 * once we've confirmed `child.type` is `FileItem`/`FolderItem` we cast to
 * the matching `ReactElement<Props>` to read its props safely.
 */
function collectFileData(children: ReactNode, parentPath: string): CollectedFileData {
  const codeFiles: CodeFile[] = [];
  const fileEntries: FileEntry[] = [];

  Children.forEach(children, (child) => {
    if (!isValidElement(child)) return;

    if (child.type === FileItem) {
      const { name, code } = (child as ReactElement<FileTreeFileProps>).props;
      const id = `${parentPath}/${name}`;
      // `id` always carries exactly one leading slash (from the root's
      // empty parentPath) — stripped here to get a clean, zip-friendly
      // relative path like "src/App.tsx" instead of "/src/App.tsx".
      const zipPath = id.replace(/^\//, "");

      fileEntries.push({ path: zipPath, content: code ?? "" });

      if (code !== undefined) {
        const language = getSyntaxLanguage(name);
        const element = (
          <Syntax language={language} title={name}>
            {code}
          </Syntax>
        );
        codeFiles.push({ id, name, code, element });
      }
      return;
    }

    if (child.type === FolderItem) {
      const { name, children: nested } = (child as ReactElement<FileTreeFolderProps>).props;
      if (nested == null) return;

      const folderId = `${parentPath}/${name}`;
      const nestedData = collectFileData(nested, folderId);
      codeFiles.push(...nestedData.codeFiles);
      fileEntries.push(...nestedData.fileEntries);
    }
  });

  return { codeFiles, fileEntries };
}

function FileTreeRoot({ children, name }: FileTreeProps) {
  const { codeFiles, fileEntries } = collectFileData(children, "");

  return (
    <FileTreeClient codeFiles={codeFiles} fileEntries={fileEntries} zipName={name ?? "files"}>
      {children}
    </FileTreeClient>
  );
}

export interface FileTreeComponent {
  (props: FileTreeProps): ReactNode;
  Folder: typeof FolderItem;
  File: typeof FileItem;
}

/**
 * IMPORTANT: whatever page/route renders `<FileTree>` must itself be a
 * Server Component (no `'use client'` at the top of that file). That's
 * what allows this component to actually execute on the server and call
 * `Syntax`. If the page needs unrelated client interactivity, put that in
 * a separate client child — don't put `'use client'` on the page itself.
 */
export const FileTree: FileTreeComponent = Object.assign(FileTreeRoot, {
  Folder: FolderItem,
  File: FileItem,
});
