import type { LangData } from "./types";

const EMPTY_LANG: LangData = {
  type: {
    primary: "Error",
    secondary: "Message",
  },
  data: [
    {
      primary: "Failed to load",
      secondary: "Language file not found",
    },
  ],
};

export async function getLangData(url: string): Promise<LangData> {
  try {
    const res = await fetch(url);

    if (!res.ok) {
      return {
        ...EMPTY_LANG,
        data: [
          {
            primary: `HTTP ${res.status}`,
            secondary: "Failed to load language file",
          },
        ],
      };
    }

    return res.json();
  } catch {
    return {
      ...EMPTY_LANG,
      data: [
        {
          primary: "Error",
          secondary: "Failed to load language file",
        },
      ],
    };
  }
}
