"use client";

import CloseIcon from "@mui/icons-material/Close";
import { useTheme } from "next-themes";
import { use, useCallback, useEffect, useId, useRef, useState } from "react";
import { createPortal } from "react-dom";

import MermaidActions from "./MermaidAction";
import type { MermaidSourceData } from "./mermaidResource";

interface MermaidInnerProps {
  title: string;
  className?: string;
  /** Literal source (or `null` when there's nothing to render), for the inline-string case. */
  source?: string | null;
  /** Fetch result promise, for the `src` case — resolved with `use()`. */
  sourcePromise?: Promise<MermaidSourceData>;
}

// ---------------------------------------------------------------------------
// Mermaid is loaded once and reused across every <Mermaid /> instance on the
// page — it's a fairly heavy module, so we don't want N copies of it.
// ---------------------------------------------------------------------------
let mermaidPromise: Promise<typeof import("mermaid").default> | null = null;

function loadMermaid() {
  if (!mermaidPromise) {
    mermaidPromise = import("mermaid").then((m) => m.default);
  }
  return mermaidPromise;
}

function readCssVar(name: string, fallback: string) {
  if (typeof window === "undefined") return fallback;
  const value = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  return value || fallback;
}

/**
 * Maps the app's `next-themes` theme onto a mermaid theme + themeVariables
 * pair. Mirrors the `resolveAutoTheme` logic in SyntaxThemeSwitcher.tsx so
 * diagrams always match the code blocks around them.
 */
function resolveMermaidTheme(appTheme: string | undefined) {
  switch (appTheme) {
    case "light":
      return { theme: "neutral" as const, themeVariables: undefined };
    case "dark":
      return { theme: "dark" as const, themeVariables: undefined };
    case "pinktra":
    default:
      return {
        theme: "base" as const,
        themeVariables: {
          primaryColor: readCssVar("--accent-color-tint", "#f4d3d9"),
          primaryTextColor: readCssVar("--text-color", "#111113"),
          primaryBorderColor: readCssVar("--accent-color", "#8a2435"),
          lineColor: readCssVar("--accent-color", "#8a2435"),
          secondaryColor: readCssVar("--accent-light", "#f9e5e8"),
          tertiaryColor: readCssVar("--off-canvas-color", "#ffffff"),
          fontFamily: "var(--font-geist-mono)",
        },
      };
  }
}

export default function MermaidInner({
  title,
  className,
  source: literalSource,
  sourcePromise,
}: MermaidInnerProps) {
  const rawId = useId().replace(/:/g, "-");
  const elementId = `mermaid-${rawId}`;

  const { theme: appTheme, resolvedTheme } = useTheme();

  // Only suspends when a promise was actually handed down (the `src` case).
  const fetched = sourcePromise ? use(sourcePromise) : null;

  const source = sourcePromise ? (fetched?.source ?? null) : (literalSource ?? null);
  const sourceError = sourcePromise ? (fetched?.error ?? null) : null;

  const [svg, setSvg] = useState<string | null>(null);
  const [renderError, setRenderError] = useState<string | null>(null);
  const [expanded, setExpanded] = useState(false);
  const [mounted, setMounted] = useState(false);

  const renderToken = useRef(0);

  useEffect(() => {
    setMounted(true);
  }, []);

  // Close the lightbox on Escape and lock page scroll while it's open.
  useEffect(() => {
    if (!expanded) return;

    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") setExpanded(false);
    };

    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    window.addEventListener("keydown", onKeyDown);

    return () => {
      document.body.style.overflow = prevOverflow;
      window.removeEventListener("keydown", onKeyDown);
    };
  }, [expanded]);

  // ---- Render the diagram whenever the source or app theme changes -------
  // (This part stays client-side no matter what: mermaid.render() needs the
  // DOM, so it can't move into the server-side promise above.)
  const render = useCallback(
    async (diagram: string) => {
      const token = ++renderToken.current;

      try {
        const mermaid = await loadMermaid();
        const activeTheme = appTheme === "system" ? resolvedTheme : appTheme;
        const { theme, themeVariables } = resolveMermaidTheme(activeTheme);

        mermaid.initialize({
          startOnLoad: false,
          securityLevel: "strict",
          suppressErrorRendering: true,
          fontFamily: "var(--font-geist-mono)",
          theme,
          themeVariables,
        });

        const { svg: renderedSvg } = await mermaid.render(elementId, diagram);

        if (renderToken.current === token) {
          setSvg(renderedSvg);
          setRenderError(null);
        }
      } catch (err) {
        if (renderToken.current === token) {
          setSvg(null);
          setRenderError(err instanceof Error ? err.message : "Failed to render diagram.");
        }
      }
    },
    [elementId, appTheme, resolvedTheme],
  );

  useEffect(() => {
    if (source) render(source);
  }, [source, render]);

  const error = sourceError ?? renderError;

  return (
    <div className={`mermaid-container ${className ?? ""}`}>
      <div className="mermaid-header">
        <h3>{title}</h3>

        <MermaidActions
          title={title}
          chart={source ?? ""}
          svg={svg}
          expanded={expanded}
          onToggleExpand={() => setExpanded((v) => !v)}
        />
      </div>

      {/* Hidden but crawlable/accessible source — gives SSR'd HTML real
          content even before mermaid hydrates on the client. */}
      {source && <pre className="mermaid-sr-source">{source}</pre>}

      {error ? (
        <div className="mermaid-error" role="alert">
          <p>⚠️ Failed to render diagram: {error}</p>
          {source && <pre>{source}</pre>}
        </div>
      ) : svg ? (
        <div className="mermaid-viewer" dangerouslySetInnerHTML={{ __html: svg }} />
      ) : (
        <div className="mermaid-preload" aria-busy="true">
          <span className="mermaid-spinner" aria-hidden="true" />
          Rendering diagram…
        </div>
      )}

      {expanded &&
        svg &&
        mounted &&
        createPortal(
          <div
            className="mermaid-lightbox"
            role="dialog"
            aria-modal="true"
            aria-label={title}
            onClick={() => setExpanded(false)}
          >
            <button
              type="button"
              className="mermaid-lightbox-close"
              onClick={() => setExpanded(false)}
              aria-label="Close fullscreen diagram"
              title="Close (Esc)"
            >
              <CloseIcon />
            </button>

            <div
              className="mermaid-lightbox-content"
              onClick={(e) => e.stopPropagation()}
              dangerouslySetInnerHTML={{ __html: svg }}
            />
          </div>,
          document.body,
        )}
    </div>
  );
}
