"use client";

import { createContext, useContext, type ReactNode } from "react";

/**
 * A code file's server-rendered content, paired with its stable id.
 *
 * `element` is the *already server-rendered* `<Syntax>` output for this
 * file — produced once, on the server, by the top-level `FileTree` wrapper
 * (see FileTree.tsx), for every code file in the tree, not just whichever
 * one happens to be open. Client code (this context, FileTreeClient,
 * Editor) never imports or calls `Syntax` itself; it only ever moves this
 * opaque node around. `code` is kept alongside it purely so the Editor can
 * derive a line count for the gutter without needing to inspect the
 * rendered tree.
 */
export interface CodeFile {
  /** Stable path-based id, matching the owning FileItem's `data-tree-id`. */
  id: string;
  /** Display name, e.g. "index.html". */
  name: string;
  /** Raw source, exactly as passed to `FileItem`'s `code` prop. Used only for the line-number gutter. */
  code: string;
  /** Pre-rendered `<Syntax>` output for this file, produced server-side. */
  element: ReactNode;
}

/**
 * Tree-wide state shared by every node, used to implement roving tabindex:
 * only one treeitem in the whole tree is ever a tab stop at a time, and
 * arrow keys move focus between the others.
 *
 * Also carries the "which code file is open in the editor pane" state.
 * This piggybacks on the same tree-root context rather than a second
 * provider: any `FileItem`, at any depth, can open itself into the editor
 * simply by calling `setSelectedId` — there is no need to walk the tree
 * to "discover" code files ahead of time.
 *
 * Note this only tracks *which* file is open, as an id. Every code file's
 * rendered content already exists in the DOM regardless (see
 * FileTreeClient) — `selectedId` just controls which one is expanded.
 */
export interface TreeRootContextValue {
  /** The `data-tree-id` of the treeitem that currently owns tabIndex 0. */
  focusedId: string | null;
  setFocusedId: (id: string) => void;
  /** The id of the code file currently expanded in the editor pane, if any. */
  selectedId: string | null;
  /** Opens a code file's slot in the editor pane. Pass `null` to close it. */
  setSelectedId: (id: string | null) => void;
}

const TreeRootContext = createContext<TreeRootContextValue | null>(null);

export const TreeRootProvider = TreeRootContext.Provider;

export function useTreeRootContext(): TreeRootContextValue {
  const ctx = useContext(TreeRootContext);
  if (!ctx) {
    throw new Error("FileTree.Folder and FileTree.File must be rendered inside <FileTree>.");
  }
  return ctx;
}

/**
 * Per-level context, re-provided by every `Folder`, used so each node knows
 * its own `aria-level` and can build a stable, path-based id for itself
 * without any node needing to know about its siblings.
 */
export interface TreeLevelContextValue {
  /** 1-indexed nesting depth, per the `aria-level` spec. */
  level: number;
  /** Stable id of the containing folder (or "" at the root), used as an id prefix. */
  parentPath: string;
}

const TreeLevelContext = createContext<TreeLevelContextValue>({
  level: 1,
  parentPath: "",
});

export const TreeLevelProvider = TreeLevelContext.Provider;

export function useTreeLevelContext(): TreeLevelContextValue {
  return useContext(TreeLevelContext);
}
