"use client";

import { useEffect, useState } from "react";
import type { PageBuilderOptions } from "~/model/course_model";
import { ContentSkeleton } from "~/page/Loading/ContentSkeleton";
import { MarkdownRenderer } from "~/ui/MarkdownViewer/MarkdownRenderer";
import Media from "~/ui/Media/Media";
import { fetchRemoteText, resolveRemoteUrl } from "../lib/remote";

export type RemoteFileOptions = Pick<
  PageBuilderOptions,
  "groupImg" | "movie" | "tableTextAlign" | "tableTextWrap"
>;

interface RemoteFileProps extends RemoteFileOptions {
  file: string;
  docsUrl: string;
}

function fileExtension(file: string) {
  return file.split("?")[0].split(".").pop()?.toLowerCase() ?? "";
}

function fileDirectory(url: string) {
  return new URL("./", url).toString();
}

export default function RemoteFile({
  file,
  docsUrl,
  groupImg,
  movie,
  tableTextAlign,
  tableTextWrap,
}: RemoteFileProps) {
  const url = resolveRemoteUrl(docsUrl, file);
  const extension = fileExtension(file);
  const isMarkdown = extension === "md" || extension === "mdx";
  const [loadState, setLoadState] = useState<{
    url: string | null;
    content: string | null;
    error: string | null;
  }>({ url: null, content: null, error: null });

  useEffect(() => {
    if (!isMarkdown) return;

    let active = true;

    fetchRemoteText(url)
      .then((text) => {
        if (active) setLoadState({ url, content: text, error: null });
      })
      .catch((reason: unknown) => {
        if (active) {
          setLoadState({
            url,
            content: null,
            error: reason instanceof Error ? reason.message : "Unable to load this file.",
          });
        }
      });

    return () => {
      active = false;
    };
  }, [isMarkdown, url]);

  const content = loadState.url === url ? loadState.content : null;
  const error = loadState.url === url ? loadState.error : null;

  if (!isMarkdown) {
    return (
      <Media
        src={url}
        alt={file.split("/").pop() ?? "Course media"}
        groupImg={groupImg}
        movie={movie}
        tableTextAlign={tableTextAlign}
        tableTextWrap={tableTextWrap}
      />
    );
  }

  if (error) {
    return (
      <p role="alert">
        Unable to load {file}: {error}
      </p>
    );
  }

  if (content === null) {
    return (
      <div role="status" aria-busy="true" aria-label="Loading tutorial content">
        <ContentSkeleton compact />
      </div>
    );
  }

  // .md and .mdx both go through the single MarkdownRenderer now — no
  // more extension branching or a per-instance Media component override;
  // the media props just get passed straight through, and it wires them
  // into both `![alt](src)` and `<Media />` internally.
  return (
    <MarkdownRenderer
      content={content}
      domain={fileDirectory(url)}
      groupImg={groupImg}
      movie={movie}
      tableTextAlign={tableTextAlign}
      tableTextWrap={tableTextWrap}
    />
  );
}
