import LaunchOutlinedIcon from "@mui/icons-material/LaunchOutlined";
import React from "react";
import type { CourseWithFirstTopic } from "~/model/course_model";
import NoResultFound from "~/page/Course/components/NoResultFound/NoResultFound";
import { pushClientPath } from "~/features/learning/lib/remote";
import { IMAGE_DOMAIN } from "~/utils/domain";
import { createRoute } from "~/utils/slug";
import "./CourseList.css";
import Link from "next/link";

interface CourseListProps {
  processedCourses: Record<string, CourseWithFirstTopic[]>;
  selectedSubCategory: string;
  searchQuery: string;
  category: string;
  learnMoreText: string;
  /** Base path segment prepended to all internal doc links (e.g. "learn"). Default: "". */
  basePath?: string;
  clientNavigation?: boolean;
}

const CourseList: React.FC<CourseListProps> = ({
  processedCourses,
  selectedSubCategory,
  searchQuery,
  category,
  learnMoreText,
  basePath = "",
  clientNavigation = false,
}) => {
  return (
    <>
      {Object.entries(processedCourses).map(([subCat, courses]) => {
        const isAll = selectedSubCategory === "All";
        const isSelected = selectedSubCategory === subCat;

        if (isAll && courses.length === 0) return null;
        if (!isAll && !isSelected) return null;

        return (
          <div key={subCat} className="subcategory-section">
            <h2 className="subcategory-title">{subCat}</h2>
            {courses.length > 0 ? (
              <div className="course-list">
                {courses.map((item, index) => {
                  const isExternal = !!item.link;

                  return (
                    <div key={index} className="course-card">
                      {item.resource && (
                        <a
                          href={item.resource}
                          target="_blank"
                          rel="noopener noreferrer"
                          className="course-resource"
                          title="Open resource"
                          aria-label={`Open resource for ${item.name}`}
                        >
                          <LaunchOutlinedIcon fontSize="small" aria-hidden="true" />
                        </a>
                      )}
                      <img
                        src={`${IMAGE_DOMAIN}/${item.img}`}
                        alt={item.name}
                        className="course-img"
                        loading="lazy"
                      />
                      <h3>{item.name}</h3>
                      <p>{item.description}</p>

                      {isExternal ? (
                        <a
                          href={item.link}
                          target="_blank"
                          className="course-link"
                          rel="noopener noreferrer"
                          aria-label={`${learnMoreText}: ${item.name}`}
                        >
                          {learnMoreText}
                        </a>
                      ) : (
                        <Link
                          href={
                            item.firstTopic
                              ? createRoute(basePath, category, item.name, item.firstTopic)
                              : createRoute(basePath, category, item.name)
                          }
                          className="course-link"
                          onClick={(event) => {
                            if (clientNavigation) {
                              event.preventDefault();
                              pushClientPath(
                                createRoute(basePath, category, item.name, item.firstTopic),
                              );
                            }
                          }}
                          aria-label={`${learnMoreText}: ${item.name}`}
                        >
                          {learnMoreText}
                        </Link>
                      )}
                    </div>
                  );
                })}
              </div>
            ) : (
              !isAll && <NoResultFound searchTerm={searchQuery} />
            )}
          </div>
        );
      })}
    </>
  );
};

export default CourseList;
