"use client";

import CloseIcon from "@mui/icons-material/Close";
import { useLayoutEffect, useMemo, useRef } from "react";
import type { TOCItem } from "~/hooks/useTOC";
import { getAncestorIds } from "~/hooks/useTOC";
import "./TableOfContents.css";

interface TOCNodeProps {
  item: TOCItem;
  activeId: string;
  ancestorIds: Set<string>;
  depth: number;
  isClickScrollingRef: React.MutableRefObject<boolean>;
  onClose?: () => void;
}

const TOCNode = ({
  item,
  activeId,
  ancestorIds,
  depth,
  isClickScrollingRef,
  onClose,
}: TOCNodeProps) => {
  const isActive = item.id === activeId;
  const isAncestor = ancestorIds.has(item.id);
  const hasChildren = item.children.length > 0;

  const handleAnchorClick = (e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault();

    isClickScrollingRef.current = true;

    const header = document.querySelector<HTMLElement>(".app-header");

    const headerHeight = header?.offsetHeight ?? 0;

    const el = document.getElementById(item.id);

    if (el) {
      const y = el.getBoundingClientRect().top + window.scrollY - headerHeight - 16;

      window.scrollTo({
        top: y,
      });

      if (location.hash !== `#${item.id}`) {
        history.replaceState(null, "", `#${item.id}`);
      }

      if (onClose) {
        onClose();
      }
    }

    setTimeout(() => {
      isClickScrollingRef.current = false;
    }, 600);
  };

  return (
    <li
      className={`toc-item toc-depth-${depth} ${isActive ? "toc-active" : ""} ${isAncestor ? "toc-ancestor" : ""}`}
    >
      <a
        href={`#${item.id}`}
        className="toc-link"
        aria-current={isActive ? "location" : undefined}
        onClick={handleAnchorClick}
      >
        {item.text}
      </a>

      {hasChildren && (
        <ul className="toc-children">
          {item.children.map((child) => (
            <TOCNode
              key={child.id}
              item={child}
              activeId={activeId}
              ancestorIds={ancestorIds}
              depth={depth + 1}
              isClickScrollingRef={isClickScrollingRef}
              onClose={onClose}
            />
          ))}
        </ul>
      )}
    </li>
  );
};

/* ---------- Loading skeleton ---------- */

const SKELETON_ROWS = [
  { w: "78%", d: 0 },
  { w: "62%", d: 1 },
  { w: "70%", d: 1 },
  { w: "85%", d: 0 },
  { w: "58%", d: 1 },
  { w: "66%", d: 2 },
  { w: "80%", d: 0 },
  { w: "60%", d: 1 },
];

const TOCSkeleton = () => (
  <div className="toc-skeleton" aria-hidden="true">
    {SKELETON_ROWS.map((row, i) => (
      <div
        key={i}
        className="toc-skeleton-line"
        style={{ width: row.w, marginLeft: row.d * 14 }}
      />
    ))}
  </div>
);

interface TableOfContentsProps {
  items: TOCItem[];
  activeId: string;
  isLoading?: boolean;
  isDrawer?: boolean;
  isOpen?: boolean;
  onClose?: () => void;
}

const TableOfContents = ({
  items,
  activeId,
  isLoading = false,
  isDrawer = false,
  isOpen = false,
  onClose,
}: TableOfContentsProps) => {
  const listRef = useRef<HTMLUListElement>(null);
  const isClickScrolling = useRef(false);

  const ancestorIds = useMemo(() => getAncestorIds(items, activeId), [items, activeId]);

  useLayoutEffect(() => {
    if (isClickScrolling.current) return;

    if (!listRef.current) return;

    const activeEl = listRef.current.querySelector(".toc-active");

    if (activeEl) {
      activeEl.scrollIntoView({
        block: "nearest",
        // behavior: "smooth",
      });
    }
  }, [activeId]);

  const showSkeleton = isLoading && items.length === 0;

  if (items.length === 0 && !isLoading) return null;

  const content = (
    <>
      <div className="toc-header">
        <h2 className="toc-title">On this page</h2>

        {isDrawer && (
          <button className="toc-close-btn" onClick={onClose} aria-label="Close table of contents">
            <CloseIcon fontSize="small" />
          </button>
        )}
      </div>

      <div className="toc-scroll">
        {showSkeleton ? (
          <TOCSkeleton />
        ) : (
          <nav aria-label="Table of contents" className="toc-fade-in">
            <ul ref={listRef} className="toc-list">
              {items.map((item) => (
                <TOCNode
                  key={item.id}
                  item={item}
                  activeId={activeId}
                  ancestorIds={ancestorIds}
                  depth={0}
                  isClickScrollingRef={isClickScrolling}
                  onClose={onClose}
                />
              ))}
            </ul>
          </nav>
        )}
      </div>
    </>
  );

  if (isDrawer) {
    return (
      <div
        className={`toc-drawer ${isOpen ? "toc-drawer-open" : ""}`}
        role="dialog"
        aria-modal="true"
        aria-label="Table of contents"
      >
        <div className="toc-drawer-inner">{content}</div>
      </div>
    );
  }

  return <aside className="toc-sidebar">{content}</aside>;
};

export default TableOfContents;
