"use client";

import { useEffect, useRef, useState } from "react";
import "./TOCFab.css";

interface TOCFabProps {
  progress: number;
  isOpen: boolean;
  onToggle: () => void;
  loading?: boolean;
}

const RADIUS = 20;
const CIRCUMFERENCE = 2 * Math.PI * RADIUS;

const TOCFab = ({ progress, isOpen, onToggle, loading = false }: TOCFabProps) => {
  const [visible, setVisible] = useState(true);
  const lastScrollY = useRef(0);
  const ticking = useRef(false);

  useEffect(() => {
    const handleScroll = () => {
      if (ticking.current) return;
      ticking.current = true;
      requestAnimationFrame(() => {
        const current = window.scrollY;
        if (current < 80) {
          setVisible(true);
        } else if (current > lastScrollY.current + 4) {
          setVisible(false);
        } else if (current < lastScrollY.current - 4) {
          setVisible(true);
        }
        lastScrollY.current = current;
        ticking.current = false;
      });
    };

    window.addEventListener("scroll", handleScroll, { passive: true });
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const dash = ((100 - progress) / 100) * CIRCUMFERENCE;
  const shouldShow = visible || isOpen;

  return (
    <button
      className={`toc-fab ${shouldShow ? "toc-fab-visible" : "toc-fab-hidden"} ${isOpen ? "toc-fab-active" : ""} ${loading ? "toc-fab-loading" : ""}`}
      onClick={onToggle}
      aria-label={isOpen ? "Close table of contents" : "Open table of contents"}
      aria-expanded={isOpen}
      aria-busy={loading}
    >
      <svg className="toc-fab-ring" width="52" height="52" viewBox="0 0 52 52" aria-hidden="true">
        <circle className="toc-fab-ring-track" cx="26" cy="26" r={RADIUS} strokeWidth="2.5" />
        <circle
          className="toc-fab-ring-fill"
          cx="26"
          cy="26"
          r={RADIUS}
          strokeWidth="2.5"
          strokeDasharray={CIRCUMFERENCE}
          strokeDashoffset={dash}
        />
      </svg>

      <span className="toc-fab-icon" aria-hidden="true">
        {isOpen ? (
          <svg width="18" height="18" viewBox="0 0 18 18" fill="none">
            <line
              x1="2"
              y1="2"
              x2="16"
              y2="16"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
            />
            <line
              x1="16"
              y1="2"
              x2="2"
              y2="16"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
            />
          </svg>
        ) : (
          <svg width="18" height="18" viewBox="0 0 18 18" fill="none">
            <line
              x1="2"
              y1="4"
              x2="16"
              y2="4"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
            />
            <line
              x1="2"
              y1="9"
              x2="12"
              y2="9"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
            />
            <line
              x1="2"
              y1="14"
              x2="16"
              y2="14"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
            />
          </svg>
        )}
      </span>
    </button>
  );
};

export default TOCFab;
