import type { CourseType } from "~/model/course_model";
import createBreadcrumbSchema from "~/utils/create_breadcrumb_schema";
import createLearningResourceSchema from "~/utils/create_learning_resource_schema";
import { truncateText } from "~/utils/custom_string";
import { IMAGE_CDN, SITE_NAME, SITE_URL } from "~/utils/domain";
import { createSlug } from "~/utils/slug";
import { toAbsoluteUrl } from "~/utils/url";
import type { ClientSeo } from "~/utils/use_client_seo";

interface Crumb {
  name: string;
  /** Site-relative path, e.g. "/learn/html-and-css". */
  path: string;
}

interface LearnSeoInput {
  title: string;
  description: string;
  path: string;
  /** Full image URL. Omit to use the site's default OG image. */
  image?: string;
  keywords: (string | undefined)[];
  /** Breadcrumbs after Home > Learn. */
  crumbs: Crumb[];
}

const BASE_CRUMBS: Crumb[] = [
  { name: "Home", path: "" },
  { name: "Learn", path: "/learn" },
];

function createLearnSeo({
  title,
  description,
  path,
  image,
  keywords,
  crumbs,
}: LearnSeoInput): ClientSeo {
  return {
    options: {
      title,
      description,
      path,
      image,
      keywords: keywords.filter(Boolean).join(", "),
      type: "article",
    },
    jsonLd: [
      createBreadcrumbSchema(
        [...BASE_CRUMBS, ...crumbs].map((crumb) => ({
          name: crumb.name,
          url: `${SITE_URL}${crumb.path}`,
        })),
      ),
      createLearningResourceSchema({ title, description, url: `${SITE_URL}${path}` }),
    ],
  };
}

/** Course images are served from IMAGE_CDN not the site itself. */
const courseImageUrl = (course: CourseType | undefined) => toAbsoluteUrl(course?.img, IMAGE_CDN);

interface CategorySeoInput {
  category: string;
  categoryTitle: string;
  courses: CourseType[];
}

/** SEO for /learn/<category>. */
export function buildCategorySeo({ category, categoryTitle, courses }: CategorySeoInput) {
  const path = `/learn/${category}`;
  const singleCourse = courses.length === 1 ? courses[0] : undefined;
  const topNames = courses
    .slice(0, 3)
    .map((course) => course.name)
    .join(", ");

  return createLearnSeo({
    title: `${categoryTitle} | Learn | ${SITE_NAME}`,
    description: truncateText(
      singleCourse
        ? singleCourse.description
        : `Learn ${categoryTitle}: ${topNames} and more on ${SITE_NAME}.`,
    ),
    path,
    // Only a single-course category has one image that represents the page.
    image: courseImageUrl(singleCourse),
    keywords: [
      categoryTitle,
      `learn ${categoryTitle}`,
      ...new Set(courses.map((course) => course.subCategory)),
      SITE_NAME,
    ],
    crumbs: [{ name: categoryTitle, path }],
  });
}

interface CourseSeoInput {
  category: string;
  categoryTitle: string;
  course: CourseType;
  /** Real topic name once known; omit for the course landing page. */
  topicName?: string;
  /** Current page path; defaults to the course landing page. */
  path?: string;
}

/** SEO for /learn/<category>/<course> and /learn/<category>/<course>/...topic. */
export function buildCourseSeo({
  category,
  categoryTitle,
  course,
  topicName,
  path,
}: CourseSeoInput) {
  const coursePath = `/learn/${category}/${createSlug(course.name)}`;
  const currentPath = path ?? coursePath;

  return createLearnSeo({
    title: topicName
      ? `${topicName} | ${course.name} | Learn | ${SITE_NAME}`
      : `${course.name} | Learn | ${SITE_NAME}`,
    description: truncateText(course.description),
    path: currentPath,
    image: courseImageUrl(course),
    keywords: [topicName, course.name, categoryTitle, SITE_NAME],
    crumbs: [
      { name: categoryTitle, path: `/learn/${category}` },
      { name: course.name, path: coursePath },
      ...(topicName ? [{ name: topicName, path: currentPath }] : []),
    ],
  });
}
