import type { ReactNode } from "react";
import { Suspense } from "react";

import { normalizeUrl } from "~/utils/url";
import "./Mermaid.css";
import { getMermaidSource } from "./mermaidResource";
import MermaidInner from "./MermaidInner";

interface MermaidProps {
  /** Diagram source, passed inline. */
  chart?: string;
  /** Alias for `chart` — kept for parity with the Syntax component's `code` prop. */
  code?: string;
  /** Diagram source as JSX children (a template string). */
  children?: ReactNode;
  /** Fetch the diagram source from a URL (relative to `domain`, if given). */
  src?: string;
  domain?: string;
  title?: string;
  className?: string;
}

export default function Mermaid({
  chart,
  code,
  children,
  src,
  domain,
  title = "Diagram",
  className,
}: MermaidProps) {
  const inline = chart ?? code ?? (typeof children === "string" ? children : undefined);

  if (inline !== undefined) {
    return <MermaidInner title={title} className={className} source={inline.trim()} />;
  }

  if (src) {
    const sourcePromise = getMermaidSource(normalizeUrl(src, domain));

    return (
      <Suspense
        fallback={
          <div className={`mermaid-container ${className ?? ""}`}>
            <div className="mermaid-preload" aria-busy="true">
              <span className="mermaid-spinner" aria-hidden="true" />
              Loading diagram…
            </div>
          </div>
        }
      >
        <MermaidInner title={title} className={className} sourcePromise={sourcePromise} />
      </Suspense>
    );
  }

  return <MermaidInner title={title} className={className} source={null} />;
}
