// Svg.tsx
import { Suspense } from "react";
import { normalizeUrl } from "~/utils/url";
import SvgClient from "./SvgClient";

interface SvgProps {
  src: string;
}

export interface SvgData {
  svg?: string;
  error?: string;
}

async function getSvgData(src: string): Promise<SvgData> {
  const res = await fetch(normalizeUrl(src));

  if (!res.ok) {
    return { error: "Failed to load SVG" };
  }

  return { svg: await res.text() };
}

const Svg = ({ src }: SvgProps) => {
  const dataPromise = getSvgData(src);

  return (
    <Suspense fallback={null}>
      <SvgClient src={src} dataPromise={dataPromise} />
    </Suspense>
  );
};

export default Svg;
