import type { FlowItemProps } from "./Flow.types";

/**
 * <Flow.Item> is a pure data-description component and a Server Component
 * (no "use client" directive). <Flow> — also a Server Component — walks
 * its children directly via React.Children/element.props to build the
 * data tree, and never actually mounts <FlowItem> to render it; it only
 * uses this function's identity as a marker via `child.type === FlowItem`.
 *
 * Because that identity check happens inside Flow.tsx's own server render
 * pass (before anything crosses to the client), the reference stays
 * intact. This render path only executes if someone renders a <Flow.Item>
 * outside of a <Flow>, in which case we fall back to rendering its
 * content inline so nothing is silently lost.
 */
export function FlowItem({ children }: FlowItemProps) {
  return <>{children}</>;
}

FlowItem.displayName = "Flow.Item";
